import React, { useState, useRef } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI } from "@google/genai";
import * as XLSX from 'https://esm.sh/xlsx';
import { Upload, FileSpreadsheet, Loader2, CheckCircle, AlertCircle, X, Download, Image as ImageIcon } from 'lucide-react';

const App = () => {
  const [file, setFile] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [extractedData, setExtractedData] = useState<any[] | null>(null);
  const [error, setError] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      processFile(e.target.files[0]);
    }
  };

  const processFile = (selectedFile: File) => {
    if (!selectedFile.type.startsWith('image/')) {
      setError('Please select a valid image file (PNG, JPG, WEBP).');
      return;
    }

    setFile(selectedFile);
    setError(null);
    setExtractedData(null);

    const reader = new FileReader();
    reader.onload = (e) => {
      setImagePreview(e.target?.result as string);
    };
    reader.readAsDataURL(selectedFile);
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      processFile(e.dataTransfer.files[0]);
    }
  };

  const clearFile = () => {
    setFile(null);
    setImagePreview(null);
    setExtractedData(null);
    setError(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const analyzeImage = async () => {
    if (!file || !imagePreview) return;

    setIsAnalyzing(true);
    setError(null);

    try {
      // Initialize Gemini
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // Prepare base64 data (remove header if present)
      const base64Data = imagePreview.split(',')[1];

      const prompt = `
        Analyze this image and extract all tabular data or lists found within it.
        Return the data as a JSON array of objects.

        Strict Rules:
        1. Each object in the array represents a row.
        2. Use consistent keys for the columns (e.g., "Name", "Age", "Phone", etc. based on the image headers).
        3. CRITICAL: Preserve the EXACT order of rows (especially names) as they appear in the image from top to bottom. Do not reorder them.
        4. If a cell is empty, use an empty string or null.
        5. Ensure numbers are formatted correctly (e.g., phone numbers as strings if they contain symbols).

        The response must be a valid JSON array.
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: {
          parts: [
            {
              inlineData: {
                mimeType: file.type,
                data: base64Data
              }
            },
            { text: prompt }
          ]
        },
        config: {
          responseMimeType: "application/json"
        }
      });

      const responseText = response.text;
      if (!responseText) throw new Error("No data returned from model.");

      const data = JSON.parse(responseText);

      if (Array.isArray(data)) {
        setExtractedData(data);
      } else if (typeof data === 'object' && data !== null) {
        // Handle case where model wraps array in an object key like { "data": [...] }
        const key = Object.keys(data).find(k => Array.isArray(data[k]));
        if (key) {
          setExtractedData(data[key]);
        } else {
           // Fallback if it's just a single object representing one row or unstructured
           setExtractedData([data]);
        }
      } else {
        throw new Error("Invalid data format received.");
      }

    } catch (err) {
      console.error(err);
      setError("Failed to extract data from the image. Please try again or ensure the image is clear.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const downloadExcel = () => {
    if (!extractedData || extractedData.length === 0) return;

    const ws = XLSX.utils.json_to_sheet(extractedData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Extracted Data");

    // Auto-width columns roughly
    const maxWidth = 50;
    const colWidths = Object.keys(extractedData[0] || {}).map(key => ({
        wch: Math.min(maxWidth, Math.max(key.length, ...extractedData.map(row => (row[key] ? row[key].toString().length : 0))) + 2)
    }));
    ws['!cols'] = colWidths;

    XLSX.writeFile(wb, "extracted_data.xlsx");
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col items-center py-12 px-4 sm:px-6 lg:px-8 text-gray-800">
      <div className="max-w-4xl w-full space-y-8">

        {/* Header */}
        <div className="text-center">
          <div className="mx-auto h-16 w-16 bg-green-100 rounded-full flex items-center justify-center mb-4">
            <FileSpreadsheet className="h-8 w-8 text-green-600" />
          </div>
          <h1 className="text-3xl font-bold text-gray-900 tracking-tight">Image to Excel Converter</h1>
          <p className="mt-2 text-lg text-gray-600">
            Upload an image of a list or table, and we'll convert it to Excel while keeping the order intact.
          </p>
        </div>

        {/* Main Content */}
        <div className="bg-white shadow-xl rounded-2xl overflow-hidden border border-gray-100">

          {/* File Upload Area */}
          {!imagePreview ? (
            <div 
              className="p-12 border-2 border-dashed border-gray-300 rounded-xl m-6 flex flex-col items-center justify-center transition-colors hover:border-green-500 hover:bg-green-50 cursor-pointer"
              onDragOver={handleDragOver}
              onDrop={handleDrop}
              onClick={() => fileInputRef.current?.click()}
            >
              <div className="p-4 bg-gray-100 rounded-full mb-4">
                <Upload className="h-8 w-8 text-gray-500" />
              </div>
              <p className="text-lg font-medium text-gray-700">Click to upload or drag and drop</p>
              <p className="text-sm text-gray-500 mt-1">PNG, JPG, WEBP up to 10MB</p>
              <input 
                type="file" 
                ref={fileInputRef} 
                className="hidden" 
                accept="image/*" 
                onChange={handleFileSelect} 
              />
            </div>
          ) : (
            <div className="flex flex-col md:flex-row h-full">
              {/* Left Side: Image Preview */}
              <div className="w-full md:w-1/2 bg-gray-100 p-6 flex flex-col items-center justify-center border-b md:border-b-0 md:border-r border-gray-200 relative">
                <img 
                  src={imagePreview} 
                  alt="Preview" 
                  className="max-h-[400px] w-auto object-contain rounded-lg shadow-sm" 
                />
                <button 
                  onClick={clearFile}
                  className="absolute top-4 right-4 p-2 bg-white rounded-full shadow-md hover:bg-red-50 text-gray-500 hover:text-red-500 transition-colors"
                  title="Remove image"
                >
                  <X className="h-5 w-5" />
                </button>
                <div className="mt-4 text-sm text-gray-500 font-medium flex items-center gap-2">
                  <ImageIcon className="w-4 h-4"/> 
                  {file?.name}
                </div>
              </div>

              {/* Right Side: Actions & Results */}
              <div className="w-full md:w-1/2 p-6 flex flex-col">

                {/* Initial Action State */}
                {!extractedData && !isAnalyzing && !error && (
                  <div className="flex-1 flex flex-col items-center justify-center text-center space-y-6">
                    <p className="text-gray-600">Ready to extract data from this image?</p>
                    <button
                      onClick={analyzeImage}
                      className="w-full max-w-xs bg-green-600 hover:bg-green-700 text-white font-semibold py-3 px-6 rounded-lg shadow-md transition-all flex items-center justify-center gap-2"
                    >
                      <FileSpreadsheet className="w-5 h-5" />
                      Convert to Excel
                    </button>
                  </div>
                )}

                {/* Loading State */}
                {isAnalyzing && (
                  <div className="flex-1 flex flex-col items-center justify-center text-center space-y-4">
                    <Loader2 className="h-10 w-10 text-green-600 animate-spin" />
                    <div>
                      <h3 className="text-lg font-medium text-gray-900">Analyzing Image...</h3>
                      <p className="text-sm text-gray-500">Extracting rows and columns with Gemini AI</p>
                    </div>
                  </div>
                )}

                {/* Error State */}
                {error && (
                  <div className="flex-1 flex flex-col items-center justify-center text-center space-y-4">
                    <div className="bg-red-50 p-3 rounded-full">
                      <AlertCircle className="h-8 w-8 text-red-500" />
                    </div>
                    <p className="text-red-600">{error}</p>
                    <button
                      onClick={analyzeImage}
                      className="text-sm font-medium text-gray-600 hover:text-gray-900 underline"
                    >
                      Try Again
                    </button>
                  </div>
                )}

                {/* Success/Result State */}
                {extractedData && (
                  <div className="flex flex-col h-full">
                    <div className="flex items-center justify-between mb-4">
                      <div className="flex items-center gap-2 text-green-700 font-medium">
                        <CheckCircle className="w-5 h-5" />
                        <span>Extraction Complete</span>
                      </div>
                      <span className="text-xs font-mono bg-gray-100 px-2 py-1 rounded text-gray-600">
                        {extractedData.length} rows found
                      </span>
                    </div>

                    {/* Simple Table Preview */}
                    <div className="flex-1 overflow-auto border border-gray-200 rounded-lg mb-4 bg-gray-50 relative scrollbar-hide">
                      <table className="min-w-full divide-y divide-gray-200 text-sm">
                        <thead className="bg-gray-100 sticky top-0">
                          <tr>
                            {extractedData.length > 0 && Object.keys(extractedData[0]).map((key) => (
                              <th key={key} className="px-3 py-2 text-left font-medium text-gray-500 uppercase tracking-wider whitespace-nowrap">
                                {key}
                              </th>
                            ))}
                          </tr>
                        </thead>
                        <tbody className="bg-white divide-y divide-gray-200">
                          {extractedData.map((row, idx) => (
                            <tr key={idx}>
                              {Object.values(row).map((val: any, i) => (
                                <td key={i} className="px-3 py-2 whitespace-nowrap text-gray-700">
                                  {typeof val === 'object' ? JSON.stringify(val) : String(val)}
                                </td>
                              ))}
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>

                    <button
                      onClick={downloadExcel}
                      className="w-full bg-green-600 hover:bg-green-700 text-white font-semibold py-3 px-6 rounded-lg shadow-md transition-all flex items-center justify-center gap-2"
                    >
                      <Download className="w-5 h-5" />
                      Download Excel File
                    </button>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

