许明月 Luna
季远兰 Mandy
吴飞Fiona（英语）
孙胜蓝 Sierra（英语）
汪苇 Winnie`);
  const [coTeachingNames, setCoTeachingNames] = useState<string>(`李苏粤Sibyl
谢淑平 Sherry
李臣亚 Linna
冯灿Sunny
张金慧 Emily
秦笑Sophie`);
  const [showSettings, setShowSettings] = useState(true);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const processFile = useCallback((selectedFile: File) => {
    if (!selectedFile.type.startsWith('image/')) {
      setError('Please select a valid image file (PNG, JPG, WEBP).');
      return;
    }

    setFile(selectedFile);
    setError(null);
    setExtractedData(null);

    const reader = new FileReader();
    reader.onload = (e) => {
      setImagePreview(e.target?.result as string);
    };
    reader.readAsDataURL(selectedFile);
  }, []);

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      processFile(e.target.files[0]);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      processFile(e.dataTransfer.files[0]);
    }
  };

  // Add Paste Event Listener
  useEffect(() => {
    const handlePaste = (e: ClipboardEvent) => {
      if (e.clipboardData && e.clipboardData.items) {
        for (let i = 0; i < e.clipboardData.items.length; i++) {
          const item = e.clipboardData.items[i];
          if (item.type.indexOf('image') !== -1) {
            const blob = item.getAsFile();
            if (blob) {
              processFile(blob);
              e.preventDefault();
              break;
            }
          }
        }
      }
    };

    document.addEventListener('paste', handlePaste);
    return () => {
      document.removeEventListener('paste', handlePaste);
    };
  }, [processFile]);

  const clearFile = () => {
    setFile(null);
    setImagePreview(null);
    setExtractedData(null);
    setError(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const calculateScore = (count: number, isCoTeaching: boolean) => {
    let score = 0;
    if (count <= 10) score = 0;
    else if (count <= 20) score = 1;
    else if (count <= 35) score = 3;
    else score = 5;

    // Co-teaching teachers are capped at 3 points
    if (isCoTeaching && score > 3) {
      return 3;
    }
    return score;
  };

  const analyzeImage = async () => {
    if (!file || !imagePreview) return;

    setIsAnalyzing(true);
    setError(null);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const base64Data = imagePreview.split(',')[1];

      let prompt = `
        Analyze this image to extract "Name" and "Column Count".

        The image contains rows with names (format: English name + last pinyin name, e.g., "Alice Z" or "Bob Zhang") and a numeric value representing "column count".
      `;

      if (referenceNames.trim()) {
        prompt += `

        CRITICAL INSTRUCTION:
        I have provided a "Standard Name List" below. 
        You MUST return a JSON array that maps EXACTLY to this Standard Name List, preserving its order.

        For each name in the Standard Name List:
        1. Find the corresponding person in the image. The name in the image might match fuzzy (e.g. "Alice Z" in image matches "Alice Zhang" in list).
        2. Extract their "count" value (number).
        3. If a person from the list is NOT found in the image, set "count" to 0.

        Standard Name List:
        ${referenceNames}

        Return format: JSON array of objects with keys "name" (from Standard List) and "count" (number).
        `;
      } else {
        prompt += `
        Extract all rows found. 
        Return format: JSON array of objects with keys "name" and "count" (number).
        `;
      }

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: {
          parts: [
            {
              inlineData: {
                mimeType: file.type,
                data: base64Data
              }
            },
            { text: prompt }
          ]
        },
        config: {
          responseMimeType: "application/json"
        }
      });

      const responseText = response.text;
      if (!responseText) throw new Error("No data returned from model.");

      const data = JSON.parse(responseText);

      let parsedData: any[] = [];
      if (Array.isArray(data)) {
        parsedData = data;
      } else if (typeof data === 'object' && data !== null) {
        const key = Object.keys(data).find(k => Array.isArray(data[k]));
        if (key) {
          parsedData = data[key];
        } else {
          parsedData = [data];
        }
      }

      // Create a set of normalized co-teaching names for easy lookup
      const coTeachingSet = new Set(
        coTeachingNames
          .split('\n')
          .map(n => n.trim().toLowerCase())
          .filter(n => n)
      );

      // Process data to add Score
      const processedData = parsedData.map(item => {
        const count = parseInt(item.count) || 0;
        const name = item.name || "";
        const isCoTeaching = coTeachingSet.has(name.trim().toLowerCase());

        return {
            "姓名": name,
            "column count": count,
            "分数": calculateScore(count, isCoTeaching)
        };
      });

      setExtractedData(processedData);

    } catch (err) {
      console.error(err);
      setError("Failed to extract data. Please ensure the image is clear and try again.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const downloadExcel = () => {
    if (!extractedData || extractedData.length === 0) return;

    const ws = XLSX.utils.json_to_sheet(extractedData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Scores");

    // Set column widths
    ws['!cols'] = [
        { wch: 20 }, // Name
        { wch: 15 }, // Count
        { wch: 10 }  // Score
    ];

    XLSX.writeFile(wb, "class_scores.xlsx");
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col items-center py-12 px-4 sm:px-6 lg:px-8 text-gray-800">
      <div className="max-w-4xl w-full space-y-6">

        {/* Header */}
        <div className="text-center">
          <div className="mx-auto h-16 w-16 bg-blue-100 rounded-full flex items-center justify-center mb-4">
            <FileSpreadsheet className="h-8 w-8 text-blue-600" />
          </div>
          <h1 className="text-3xl font-bold text-gray-900 tracking-tight">Score Calculator</h1>
          <p className="mt-2 text-lg text-gray-600">
            Upload/Paste an image of the column counts. We'll match them to your name list and calculate scores.
          </p>
        </div>

        {/* Settings Section for Name Lists */}
        <div className="bg-white shadow-md rounded-xl overflow-hidden border border-gray-100">
          <div 
            className="px-6 py-4 bg-gray-50 border-b border-gray-200 flex items-center justify-between cursor-pointer"
            onClick={() => setShowSettings(!showSettings)}
          >
            <div className="flex items-center gap-2 font-medium text-gray-700">
              <Settings className="w-5 h-5" />
              <span>Score Settings</span>
            </div>
            <span className="text-sm text-blue-600 hover:text-blue-800">
              {showSettings ? 'Hide' : 'Show'}
            </span>
          </div>

          {showSettings && (
            <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
               {/* Standard Names Input */}
               <div>
                   <div className="mb-2 text-sm text-gray-700 font-semibold flex items-center gap-2">
                     <Users className="w-4 h-4" />
                     Standard Name List (Required)
                   </div>
                   <div className="mb-2 text-xs text-gray-500">
                     Paste names here (one per line). The output will follow this exact order.
                   </div>
                   <textarea
                     value={referenceNames}
                     onChange={(e) => setReferenceNames(e.target.value)}
                     placeholder="Alice Zhang&#10;Bob Li&#10;Charlie Chen"
                     className="w-full h-48 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm font-mono"
                   />
                   <div className="mt-1 text-xs text-gray-400 text-right">
                     {referenceNames.split('\n').filter(n => n.trim()).length} names
                   </div>
               </div>

               {/* Co-teaching Names Input */}
               <div>
                   <div className="mb-2 text-sm text-gray-700 font-semibold flex items-center gap-2">
                     <Info className="w-4 h-4" />
                     Co-teaching Teachers (Max 3 pts)
                   </div>
                   <div className="mb-2 text-xs text-gray-500">
                     Paste Co-teaching names here. These teachers cannot exceed 3 points.
                   </div>
                   <textarea
                     value={coTeachingNames}
                     onChange={(e) => setCoTeachingNames(e.target.value)}
                     placeholder="Bob Li&#10;David Wang"
                     className="w-full h-48 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm font-mono"
                   />
                   <div className="mt-1 text-xs text-gray-400 text-right">
                     {coTeachingNames.split('\n').filter(n => n.trim()).length} names
                   </div>
               </div>
            </div>
          )}
        </div>

        {/* Main Content */}
        <div className="bg-white shadow-xl rounded-2xl overflow-hidden border border-gray-100">

          {/* File Upload Area */}
          {!imagePreview ? (
            <div 
              className="p-12 border-2 border-dashed border-gray-300 rounded-xl m-6 flex flex-col items-center justify-center transition-colors hover:border-blue-500 hover:bg-blue-50 cursor-pointer"
              onDragOver={handleDragOver}
              onDrop={handleDrop}
              onClick={() => fileInputRef.current?.click()}
            >
              <div className="p-4 bg-gray-100 rounded-full mb-4">
                <Upload className="h-8 w-8 text-gray-500" />
              </div>
              <p className="text-lg font-medium text-gray-700">Click to upload, drag & drop, or paste (Ctrl+V)</p>
              <p className="text-sm text-gray-500 mt-1">PNG, JPG, WEBP</p>
              <input 
                type="file" 
                ref={fileInputRef} 
                className="hidden" 
                accept="image/*" 
                onChange={handleFileSelect} 
              />
            </div>
          ) : (
            <div className="flex flex-col md:flex-row h-full min-h-[400px]">
              {/* Left Side: Image Preview */}
              <div className="w-full md:w-1/2 bg-gray-100 p-6 flex flex-col items-center justify-center border-b md:border-b-0 md:border-r border-gray-200 relative">
                <img 
                  src={imagePreview} 
                  alt="Preview" 
                  className="max-h-[400px] w-auto object-contain rounded-lg shadow-sm" 
                />
                <button 
                  onClick={clearFile}
                  className="absolute top-4 right-4 p-2 bg-white rounded-full shadow-md hover:bg-red-50 text-gray-500 hover:text-red-500 transition-colors"
                  title="Remove image"
                >
                  <X className="h-5 w-5" />
                </button>
                <div className="mt-4 text-sm text-gray-500 font-medium flex items-center gap-2">
                  <ImageIcon className="w-4 h-4"/> 
                  {file?.name}
                </div>
              </div>

              {/* Right Side: Actions & Results */}
              <div className="w-full md:w-1/2 p-6 flex flex-col">

                {/* Initial Action State */}
                {!extractedData && !isAnalyzing && !error && (
                  <div className="flex-1 flex flex-col items-center justify-center text-center space-y-6">
                    <p className="text-gray-600">
                      {referenceNames.trim() 
                        ? "Ready to match names and calculate scores?" 
                        : "Ready to extract data? (Tip: Add a reference list for better accuracy)"}
                    </p>
                    <button
                      onClick={analyzeImage}
                      className="w-full max-w-xs bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-6 rounded-lg shadow-md transition-all flex items-center justify-center gap-2"
                    >
                      <FileSpreadsheet className="w-5 h-5" />
                      Calculate Scores
                    </button>
                  </div>
                )}

                {/* Loading State */}
                {isAnalyzing && (
                  <div className="flex-1 flex flex-col items-center justify-center text-center space-y-4">
                    <Loader2 className="h-10 w-10 text-blue-600 animate-spin" />
                    <div>
                      <h3 className="text-lg font-medium text-gray-900">Processing...</h3>
                      <p className="text-sm text-gray-500">Matching names and calculating scores with Gemini AI</p>
                    </div>
                  </div>
                )}

                {/* Error State */}
                {error && (
                  <div className="flex-1 flex flex-col items-center justify-center text-center space-y-4">
                    <div className="bg-red-50 p-3 rounded-full">
                      <AlertCircle className="h-8 w-8 text-red-500" />
                    </div>
                    <p className="text-red-600">{error}</p>
                    <button
                      onClick={analyzeImage}
                      className="text-sm font-medium text-gray-600 hover:text-gray-900 underline"
                    >
                      Try Again
                    </button>
                  </div>
                )}

                {/* Success/Result State */}
                {extractedData && (
                  <div className="flex flex-col h-full w-full">
                    <div className="flex items-center justify-between mb-4">
                      <div className="flex items-center gap-2 text-green-700 font-medium">
                        <CheckCircle className="w-5 h-5" />
                        <span>Done</span>
                      </div>
                      <span className="text-xs font-mono bg-gray-100 px-2 py-1 rounded text-gray-600">
                        {extractedData.length} records
                      </span>
                    </div>

                    {/* Simple Table Preview */}
                    <div className="flex-1 overflow-auto border border-gray-200 rounded-lg mb-4 bg-gray-50 relative scrollbar-hide max-h-[300px]">
                      <table className="min-w-full divide-y divide-gray-200 text-sm">
                        <thead className="bg-gray-100 sticky top-0">
                          <tr>
                            <th className="px-3 py-2 text-left font-medium text-gray-500">姓名</th>
                            <th className="px-3 py-2 text-center font-medium text-gray-500">Count</th>
                            <th className="px-3 py-2 text-center font-medium text-gray-500">Score</th>
                          </tr>
                        </thead>
                        <tbody className="bg-white divide-y divide-gray-200">
                          {extractedData.map((row, idx) => (
                            <tr key={idx}>
                              <td className="px-3 py-2 whitespace-nowrap text-gray-900 font-medium">{row['姓名']}</td>
                              <td className="px-3 py-2 whitespace-nowrap text-gray-600 text-center">{row['column count']}</td>
                              <td className={`px-3 py-2 whitespace-nowrap text-center font-bold ${
                                row['分数'] >= 5 ? 'text-green-600' : 
                                row['分数'] >= 3 ? 'text-blue-600' : 'text-gray-500'
                              }`}>
                                {row['分数']}
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>

                    <button
                      onClick={downloadExcel}
                      className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-6 rounded-lg shadow-md transition-all flex items-center justify-center gap-2"
                    >
                      <Download className="w-5 h-5" />
                      Download Excel
                    </button>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

