      // 3. Calculate Final Data for each Standard Name
      const processedData = stdNamesList.map(stdName => {
          // Find all rows attributed to this teacher
          const teacherRows = rows.filter(r => r.standardName === stdName);

          const rawTotal = teacherRows.reduce((sum, r) => sum + (Number(r.count) || 0), 0);

          // Check if this teacher is in the Co-teaching list (Case insensitive check)
          const isCoTeaching = coTeachingList.some(ct => stdName.toLowerCase().includes(ct));

          let adjustedTotal = 0;

          if (isCoTeaching) {
              // Apply Co-teaching Logic:
              // For each subject, if it is shared (code used by >1 teacher), count is halved.
              teacherRows.forEach(r => {
                  const count = Number(r.count) || 0;
                  const code = r.subjectCode ? String(r.subjectCode).trim().toUpperCase() : "";

                  const teachersForCode = codeToTeachers.get(code);

                  // If subject code exists in map and has more than 1 teacher associated with it
                  if (teachersForCode && teachersForCode.size > 1) {
                      adjustedTotal += count / 2;
                  } else {
                      adjustedTotal += count;
                  }
              });
          } else {
              // Regular teacher: No deductions
              adjustedTotal = rawTotal;
          }

          return {
              "姓名": stdName,
              "Raw Count": rawTotal,
              "Adjusted Count": adjustedTotal,
              "分数": calculateScore(adjustedTotal)
          };
      });

      setExtractedData(processedData);

    } catch (err) {
      console.error(err);
      setError("Failed to extract data. Please ensure the image is clear and try again.");
    } finally {
      setIsAnalyzing(false);
    }
  };

