        {/* Settings Section for Name Lists */}
        <div className="bg-white shadow-md rounded-xl overflow-hidden border border-gray-100">
          <div 
            className="px-6 py-4 bg-gray-50 border-b border-gray-200 flex items-center justify-between cursor-pointer"
            onClick={() => setShowSettings(!showSettings)}
          >
            <div className="flex items-center gap-2 font-medium text-gray-700">
              <Settings className="w-5 h-5" />
              <span>Score Settings</span>
            </div>
            <span className="text-sm text-blue-600 hover:text-blue-800">
              {showSettings ? 'Hide' : 'Show'}
            </span>
          </div>

          {showSettings && (
            <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
               {/* Standard Names Input */}
               <div>
                   <div className="mb-2 text-sm text-gray-700 font-semibold flex items-center gap-2">
                     <Users className="w-4 h-4" />
                     Standard Name List (Required)
                   </div>
                   <div className="mb-2 text-xs text-gray-500">
                     Paste names here (one per line). The output will follow this exact order.
                   </div>
                   <textarea
                     value={referenceNames}
                     onChange={(e) => setReferenceNames(e.target.value)}
                     placeholder="Alice Zhang&#10;Bob Li&#10;Charlie Chen"
                     className="w-full h-48 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm font-mono"
