                    </p>
                    <button
                      onClick={analyzeImage}
                      className="w-full max-w-xs bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-6 rounded-lg shadow-md transition-all flex items-center justify-center gap-2"
                    >
                      <FileSpreadsheet className="w-5 h-5" />
                      Calculate Scores
                    </button>
                  </div>
                )}

                {/* Loading State */}
                {isAnalyzing && (
                  <div className="flex-1 flex flex-col items-center justify-center text-center space-y-4">
                    <Loader2 className="h-10 w-10 text-blue-600 animate-spin" />
                    <div>
                      <h3 className="text-lg font-medium text-gray-900">Processing...</h3>
                      <p className="text-sm text-gray-500">Extracting rows, checking for shared subjects...</p>
                    </div>
                  </div>
                )}

                {/* Error State */}
                {error && (
                  <div className="flex-1 flex flex-col items-center justify-center text-center space-y-4">
                    <div className="bg-red-50 p-3 rounded-full">
                      <AlertCircle className="h-8 w-8 text-red-500" />
                    </div>
                    <p className="text-red-600">{error}</p>
                    <button
                      onClick={analyzeImage}
                      className="text-sm font-medium text-gray-600 hover:text-gray-900 underline"
                    >
                      Try Again
                    </button>
                  </div>
                )}

                {/* Success/Result State */}
                {extractedData && (
                  <div className="flex flex-col h-full w-full">
                    <div className="flex items-center justify-between mb-4">
                      <div className="flex items-center gap-2 text-green-700 font-medium">
                        <CheckCircle className="w-5 h-5" />
                        <span>Done</span>
                      </div>
                      <span className="text-xs font-mono bg-gray-100 px-2 py-1 rounded text-gray-600">
                        {extractedData.length} records
                      </span>
                    </div>

                    {/* Simple Table Preview */}
                    <div className="flex-1 overflow-auto border border-gray-200 rounded-lg mb-4 bg-gray-50 relative scrollbar-hide max-h-[300px]">
                      <table className="min-w-full divide-y divide-gray-200 text-sm">
                        <thead className="bg-gray-100 sticky top-0">
                          <tr>
                            <th className="px-3 py-2 text-left font-medium text-gray-500">姓名</th>
                            <th className="px-3 py-2 text-center font-medium text-gray-500">Raw</th>
                            <th className="px-3 py-2 text-center font-medium text-gray-500">Adjusted</th>
                            <th className="px-3 py-2 text-center font-medium text-gray-500">Score</th>
                          </tr>
                        </thead>
                        <tbody className="bg-white divide-y divide-gray-200">
                          {extractedData.map((row, idx) => (
                            <tr key={idx}>
                              <td className="px-3 py-2 whitespace-nowrap text-gray-900 font-medium">{row['姓名']}</td>
                              <td className="px-3 py-2 whitespace-nowrap text-gray-400 text-center">{row['Raw Count']}</td>
                              <td className="px-3 py-2 whitespace-nowrap text-blue-600 text-center font-medium">{row['Adjusted Count']}</td>
                              <td className={`px-3 py-2 whitespace-nowrap text-center font-bold ${
                                row['分数'] >= 5 ? 'text-green-600' : 
                                row['分数'] >= 3 ? 'text-blue-600' : 'text-gray-500'
                              }`}>
                                {row['分数']}
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>

                    <button
                      onClick={downloadExcel}
                      className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-6 rounded-lg shadow-md transition-all flex items-center justify-center gap-2"
                    >
                      <Download className="w-5 h-5" />
                      Download Excel
                    </button>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI } from "@google/genai";
import * as XLSX from 'https://esm.sh/xlsx';
import { Upload, FileSpreadsheet, Loader2, CheckCircle, AlertCircle, X, Download, Image as ImageIcon, Settings, Info, Users } from 'lucide-react';

// Interfaces for type safety
interface RawRow {
  teacher: string;
  code: string;
  count: number;
}

interface ProcessedRow {
  "姓名": string;
  "Raw Count": number;
  "Adjusted Count": number;
  "分数": number;
}

const App = () => {
  const [file, setFile] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [extractedData, setExtractedData] = useState<ProcessedRow[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [referenceNames, setReferenceNames] = useState<string>(`杨晶晶 Jenny
徐育梅 Catherine
储晓栋 Amy
孟雅 Alice
陈蓉 Lotus
谢淑平 Sherry
郭晶晶 Joy
李臣亚 Linna
杨阳Sunny
詹和太James
曹阳Bill
任艳 Rebecca
王芸 Yun
樊澄 Claire
孟远 Krystal
谭颖Tenny
刘鹏宇Dean
张月明 Jasmine 
徐晓娜 Elina
赵茹怡Daicen
金辰昊Colin
张金慧 Emily
冯灿Sunny
李雪维 Nicole 
张国靖 Alicia 
秦笑Sophie 
刘家玮Jane
施璎真Serena
丁佐伊Zoe
宋吉 Merissa 
王楚怡phyllis
周筱妍Ollie
张颖 Yvonne 
李苏粤Sibyl
许明月 Luna
季远兰 Mandy
吴飞Fiona（英语）
孙胜蓝 Sierra（英语）
汪苇 Winnie`);
  const [coTeachingNames, setCoTeachingNames] = useState<string>(`Sibyl,Noku
Sherry,Linna
Sunny,Emily
Sophie,Superman
Lotus,Callum`);
  const [showSettings, setShowSettings] = useState(true);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const processFile = useCallback((selectedFile: File) => {
    if (!selectedFile.type.startsWith('image/')) {
      setError('Please select a valid image file (PNG, JPG, WEBP).');
      return;
    }

    setFile(selectedFile);
    setError(null);
    setExtractedData(null);

    const reader = new FileReader();
    reader.onload = (e) => {
      setImagePreview(e.target?.result as string);
    };
    reader.readAsDataURL(selectedFile);
  }, []);

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      processFile(e.target.files[0]);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      processFile(e.dataTransfer.files[0]);
    }
  };

  // Add Paste Event Listener
  useEffect(() => {
    const handlePaste = (e: ClipboardEvent) => {
      if (e.clipboardData && e.clipboardData.items) {
        for (let i = 0; i < e.clipboardData.items.length; i++) {
          const item = e.clipboardData.items[i];
          if (item.type.indexOf('image') !== -1) {
            const blob = item.getAsFile();
            if (blob) {
              processFile(blob);
              e.preventDefault();
              break;
            }
          }
        }
      }
    };

    document.addEventListener('paste', handlePaste);
    return () => {
      document.removeEventListener('paste', handlePaste);
    };
  }, [processFile]);

  const clearFile = () => {
    setFile(null);
    setImagePreview(null);
    setExtractedData(null);
    setError(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const calculateScore = (count: number) => {
    if (count <= 10) return 0;
    if (count <= 20) return 1;
    if (count <= 35) return 3;
    return 5;
  };

  // Helper to normalize subject codes (remove spaces, uppercase)
  const normalizeCode = (code: string) => {
    if (!code) return "";
    return code.replace(/\s+/g, '').toUpperCase();
  };

  // Helper to extract searchable keywords from a standard name line
  // e.g., "李苏粤Sibyl" -> ["李苏粤", "Sibyl"]
  const getKeywords = (standardNameLine: string) => {
    // Split by non-word characters but keep Chinese and English letters
    // A simple regex approach: match sequences of Chinese or English characters
    const parts = standardNameLine.match(/[\u4e00-\u9fa5]+|[a-zA-Z]+/g);
    return parts ? parts.map(p => p.toLowerCase()) : [];
  };

  const analyzeImage = async () => {
    if (!file || !imagePreview) return;

    setIsAnalyzing(true);
    setError(null);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const base64Data = imagePreview.split(',')[1];

      // Simplified Prompt: Ask for RAW data only. No matching logic in AI.
      let prompt = `
        Analyze this image containing a table.
        Columns are: "Teacher Name", "Subject Name", "Subject Code", "Number of Columns".

        Task:
        Extract EVERY data row (exclude "Total" rows).
        If "Teacher Name" is merged/empty for a row, use the teacher name from the row above it.

        Return a simple JSON array of objects:
        [
          { "teacher": "Exact string from image", "code": "Subject Code", "count": 123 },
          ...
        ]

        Output valid JSON only.
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: {
          parts: [
            {
              inlineData: {
                mimeType: file.type,
                data: base64Data
              }
            },
            { text: prompt }
          ]
        },
        config: {
          responseMimeType: "application/json"
        }
      });

      const responseText = response.text;
      if (!responseText) throw new Error("No data returned from model.");

      let rawRows: RawRow[] = [];
      try {
        const parsed = JSON.parse(responseText);
        if (Array.isArray(parsed)) {
            rawRows = parsed;
        } else if (typeof parsed === 'object') {
            const key = Object.keys(parsed).find(k => Array.isArray(parsed[k]));
            if (key) rawRows = parsed[key];
        }
      } catch (e) {
          throw new Error("Failed to parse AI response.");
      }

      // --- Client-Side Matching Algorithm ---

      // 1. Prepare Standard Names with Keywords
      const stdNamesList = referenceNames.split('\n').map(n => n.trim()).filter(n => n);
      const stdNameMatchers = stdNamesList.map(name => ({
          fullName: name,
          keywords: getKeywords(name)
      }));

      // 2. Assign each Raw Row to a Standard Name
      // We add a 'matchedStandardName' property to each row object
      const matchedRows = rawRows.map(row => {
          const rawTeacher = (row.teacher || "").toLowerCase();

          // Find best match: Check if any keyword of a standard name exists in the raw teacher name
          // Priority: Full match > Partial match. 
          // Since names are distinct, finding the first standard name where a keyword appears in rawTeacher is usually sufficient.
          const match = stdNameMatchers.find(matcher => {
              return matcher.keywords.some(keyword => {
                  // Keyword must be at least 2 chars to avoid matching initials too aggressively (unless name is short)
                  if (keyword.length < 2) return false; 
                  return rawTeacher.includes(keyword);
              });
          });

          return {
              ...row,
              matchedStandardName: match ? match.fullName : null,
              normalizedCode: normalizeCode(row.code)
          };
      });

      // 3. Co-teaching Logic
      const rowsToHalve = new Set<any>();

      const coTeachingGroups = coTeachingNames
        .split('\n')
        .map(line => line.split(/,|，/).map(n => n.trim().toLowerCase()).filter(n => n))
        .filter(group => group.length > 0);

      coTeachingGroups.forEach(groupKeywords => {
         // Find all matched rows that belong to this co-teaching group
         // A row belongs if its matchedStandardName contains one of the group keywords
         const groupRows = matchedRows.filter(row => {
             if (!row.matchedStandardName) return false;
             const nameLower = row.matchedStandardName.toLowerCase();
             return groupKeywords.some(k => nameLower.includes(k));
         });

         // Check for Shared Subject Codes within this group
         const codeMap = new Map<string, typeof matchedRows>();
         groupRows.forEach(row => {
             if (!row.normalizedCode) return;
             if (!codeMap.has(row.normalizedCode)) codeMap.set(row.normalizedCode, []);
             codeMap.get(row.normalizedCode)?.push(row);
         });

         codeMap.forEach((rowsInCode, code) => {
             // Get unique teachers for this subject code
             const uniqueTeachers = new Set(rowsInCode.map(r => r.matchedStandardName));

             // If >1 teacher in this group teaches this code, halve them all
             if (uniqueTeachers.size > 1) {
                 rowsInCode.forEach(r => rowsToHalve.add(r));
             }
         });
      });

      // 4. Final Aggregation
      const results: ProcessedRow[] = stdNamesList.map(stdName => {
          const teacherRows = matchedRows.filter(r => r.matchedStandardName === stdName);

          let rawTotal = 0;
          let adjustedTotal = 0;

          teacherRows.forEach(r => {
              const val = Number(r.count) || 0;
              rawTotal += val;
              if (rowsToHalve.has(r)) {
                  adjustedTotal += val / 2;
              } else {
                  adjustedTotal += val;
              }
          });

          return {
              "姓名": stdName,
              "Raw Count": rawTotal,
              "Adjusted Count": adjustedTotal,
              "分数": calculateScore(adjustedTotal)
          };
      });

      setExtractedData(results);

    } catch (err) {
      console.error(err);
      setError("Failed to process. Please ensure the image is clear.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const downloadExcel = () => {
    if (!extractedData || extractedData.length === 0) return;

    const ws = XLSX.utils.json_to_sheet(extractedData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Scores");

    ws['!cols'] = [{ wch: 20 }, { wch: 10 }, { wch: 15 }, { wch: 10 }];
    XLSX.writeFile(wb, "class_scores.xlsx");
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col items-center py-12 px-4 sm:px-6 lg:px-8 text-gray-800">
      <div className="max-w-4xl w-full space-y-6">

        {/* Header */}
        <div className="text-center">
          <div className="mx-auto h-16 w-16 bg-blue-100 rounded-full flex items-center justify-center mb-4">
            <FileSpreadsheet className="h-8 w-8 text-blue-600" />
          </div>
          <h1 className="text-3xl font-bold text-gray-900 tracking-tight">Score Calculator</h1>
          <p className="mt-2 text-lg text-gray-600">
            Upload an image of the column counts.
          </p>
        </div>

        {/* Settings */}
        <div className="bg-white shadow-md rounded-xl overflow-hidden border border-gray-100">
          <div 
            className="px-6 py-4 bg-gray-50 border-b border-gray-200 flex items-center justify-between cursor-pointer"
            onClick={() => setShowSettings(!showSettings)}
          >
            <div className="flex items-center gap-2 font-medium text-gray-700">
              <Settings className="w-5 h-5" />
              <span>Settings</span>
            </div>
            <span className="text-sm text-blue-600 hover:text-blue-800">
              {showSettings ? 'Hide' : 'Show'}
            </span>
          </div>

          {showSettings && (
            <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
               {/* Standard Names */}
               <div>
                   <div className="mb-2 text-sm text-gray-700 font-semibold flex items-center gap-2">
                     <Users className="w-4 h-4" />
                     Standard Name List (Required)
                   </div>
                   <textarea
                     value={referenceNames}
                     onChange={(e) => setReferenceNames(e.target.value)}
                     className="w-full h-48 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm font-mono"
                   />
               </div>

               {/* Co-teaching Groups */}
               <div>
                   <div className="mb-2 text-sm text-gray-700 font-semibold flex items-center gap-2">
                     <Info className="w-4 h-4" />
                     Co-teaching Groups
                   </div>
                   <div className="mb-2 text-xs text-gray-500">
                     One group per line, comma separated.<br/>
                     Example: <code>Sherry, Linna</code>
                   </div>
                   <textarea
                     value={coTeachingNames}
                     onChange={(e) => setCoTeachingNames(e.target.value)}
                     className="w-full h-48 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm font-mono"
                   />
               </div>
            </div>
          )}
        </div>

        {/* Main Area */}
        <div className="bg-white shadow-xl rounded-2xl overflow-hidden border border-gray-100">
          {!imagePreview ? (
            <div 
              className="p-12 border-2 border-dashed border-gray-300 rounded-xl m-6 flex flex-col items-center justify-center hover:border-blue-500 hover:bg-blue-50 cursor-pointer"
              onDragOver={handleDragOver}
              onDrop={handleDrop}
              onClick={() => fileInputRef.current?.click()}
            >
              <Upload className="h-8 w-8 text-gray-500 mb-4" />
              <p className="text-lg font-medium text-gray-700">Click to upload or Paste (Ctrl+V)</p>
              <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileSelect} />
            </div>
          ) : (
            <div className="flex flex-col md:flex-row h-full min-h-[400px]">
              {/* Preview */}
              <div className="w-full md:w-1/2 bg-gray-100 p-6 flex flex-col items-center justify-center relative">
                <img src={imagePreview} alt="Preview" className="max-h-[400px] w-auto object-contain rounded-lg shadow-sm" />
                <button onClick={clearFile} className="absolute top-4 right-4 p-2 bg-white rounded-full shadow hover:text-red-500">
                  <X className="h-5 w-5" />
                </button>
              </div>

              {/* Actions/Results */}
              <div className="w-full md:w-1/2 p-6 flex flex-col">
                {!extractedData && !isAnalyzing && !error && (
                  <div className="flex-1 flex flex-col items-center justify-center space-y-6">
                    <button onClick={analyzeImage} className="w-full max-w-xs bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-6 rounded-lg shadow-md flex items-center justify-center gap-2">
                      <FileSpreadsheet className="w-5 h-5" />
                      Calculate Scores
                    </button>
                  </div>
                )}

