interface RawRow {
  teacher: string;
  code: string;
  count: number;
  matchedStandardName?: string | null;
  normalizedCode?: string;
}

interface ProcessedRow {
  "姓名": string;
  "Raw Count": number;
  "Adjusted Count": number;
  "分数": number;
  "Halved Subjects": string;
}

const App = () => {
  const [file, setFile] = useState<File | null>(null);
