  const [coTeachingNames, setCoTeachingNames] = useState<string>(`李苏粤Sibyl, Noku
谢淑平 Sherry, 李臣亚 Linna
冯灿Sunny,张金慧 Emily
秦笑Sophie, Superman
陈蓉 Lotus, Callum`);
  const [showSettings, setShowSettings] = useState(true);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const processFile = useCallback((selectedFile: File) => {
    if (!selectedFile.type.startsWith('image/')) {
      setError('Please select a valid image file (PNG, JPG, WEBP).');
      return;
    }

    setFile(selectedFile);
    setError(null);
    setExtractedData(null);

    const reader = new FileReader();
    reader.onload = (e) => {
      setImagePreview(e.target?.result as string);
    };
    reader.readAsDataURL(selectedFile);
  }, []);

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      processFile(e.target.files[0]);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      processFile(e.dataTransfer.files[0]);
    }
  };

  // Add Paste Event Listener
  useEffect(() => {
    const handlePaste = (e: ClipboardEvent) => {
      if (e.clipboardData && e.clipboardData.items) {
        for (let i = 0; i < e.clipboardData.items.length; i++) {
          const item = e.clipboardData.items[i];
          if (item.type.indexOf('image') !== -1) {
            const blob = item.getAsFile();
            if (blob) {
              processFile(blob);
              e.preventDefault();
              break;
            }
          }
        }
      }
    };

    document.addEventListener('paste', handlePaste);
    return () => {
      document.removeEventListener('paste', handlePaste);
    };
  }, [processFile]);

  const clearFile = () => {
    setFile(null);
    setImagePreview(null);
    setExtractedData(null);
    setError(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const calculateScore = (count: number) => {
    if (count <= 10) return 0;
    if (count <= 20) return 1;
    if (count <= 35) return 3;
    return 5;
  };

  // Helper to normalize subject codes (remove spaces, uppercase)
  const normalizeCode = (code: string) => {
    if (!code) return "";
    return code.replace(/\s+/g, '').toUpperCase();
  };

  // Helper to extract searchable keywords from a standard name line
  // e.g., "李苏粤Sibyl" -> ["李苏粤", "Sibyl"]
  const getKeywords = (standardNameLine: string) => {
    // Split by non-word characters but keep Chinese and English letters
    const parts = standardNameLine.match(/[\u4e00-\u9fa5]+|[a-zA-Z]+/g);
    return parts ? parts.map(p => p.toLowerCase()) : [];
  };

  const analyzeImage = async () => {
    if (!file || !imagePreview) return;

    setIsAnalyzing(true);
    setError(null);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const base64Data = imagePreview.split(',')[1];

      // Prompt asking for raw data extraction only
      let prompt = `
        Analyze this image containing a table.
        Columns are: "Teacher Name", "Subject Name", "Subject Code", "Number of Columns".

        Task:
        Extract EVERY data row (exclude "Total" rows).
        If "Teacher Name" is merged/empty for a row, use the teacher name from the row above it.

        Return a simple JSON array of objects:
        [
          { "teacher": "Exact string from image", "code": "Subject Code", "count": 123 },
          ...
        ]

        Output valid JSON only.
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: {
          parts: [
            {
              inlineData: {
                mimeType: file.type,
                data: base64Data
              }
            },
            { text: prompt }
          ]
        },
        config: {
          responseMimeType: "application/json"
        }
      });

      const responseText = response.text;
      if (!responseText) throw new Error("No data returned from model.");

      let rawRows: RawRow[] = [];
      try {
        const parsed = JSON.parse(responseText);
        if (Array.isArray(parsed)) {
            rawRows = parsed;
        } else if (typeof parsed === 'object') {
            const key = Object.keys(parsed).find(k => Array.isArray(parsed[k]));
            if (key) rawRows = parsed[key];
        }
      } catch (e) {
          throw new Error("Failed to parse AI response.");
      }

      // --- Client-Side Matching Algorithm ---

      // 1. Prepare Standard Names with Keywords
      const stdNamesList = referenceNames.split('\n').map(n => n.trim()).filter(n => n);
      const stdNameMatchers = stdNamesList.map(name => ({
          fullName: name,
          keywords: getKeywords(name)
      }));

      // 2. Assign each Raw Row to a Standard Name
      const matchedRows: RawRow[] = rawRows.map(row => {
          const rawTeacher = (row.teacher || "").toLowerCase();

          // Find best match in Standard List
          const match = stdNameMatchers.find(matcher => {
              return matcher.keywords.some(keyword => {
                  if (keyword.length < 2) return false; 
                  return rawTeacher.includes(keyword);
              });
          });

          return {
              ...row,
              matchedStandardName: match ? match.fullName : null,
              normalizedCode: normalizeCode(row.code)
          };
      });

      // 3. Co-teaching Logic
      const rowsToHalve = new Set<RawRow>();
      const halvedCodesMap = new Map<string, Set<string>>(); // StandardName -> Set<SubjectCodes>

      const coTeachingGroups = coTeachingNames
        .split('\n')
        .map(line => line.split(/,|，/).map(n => n.trim().toLowerCase()).filter(n => n))
        .filter(group => group.length > 0);

      coTeachingGroups.forEach(groupKeywords => {
         // Filter rows that belong to this group (check Standard Name OR Raw Name)
         // This handles cases where a partner (e.g., Noku) is in the image but not in the Standard Name list.
         const groupRows = matchedRows.filter(row => {
             const standard = (row.matchedStandardName || "").toLowerCase();
             const raw = (row.teacher || "").toLowerCase();
             return groupKeywords.some(k => standard.includes(k) || raw.includes(k));
         });

         // Group by Subject Code within this co-teaching circle
         const codeMap = new Map<string, typeof matchedRows>();
         groupRows.forEach(row => {
             if (!row.normalizedCode) return;
             if (!codeMap.has(row.normalizedCode)) codeMap.set(row.normalizedCode, []);
             codeMap.get(row.normalizedCode)?.push(row);
         });

         codeMap.forEach((rowsInCode, code) => {
             // Check if multiple teachers (Standard OR Raw) are teaching this code
             const uniqueTeachers = new Set(rowsInCode.map(r => r.matchedStandardName || r.teacher));

             if (uniqueTeachers.size > 1) {
                 // Mark all rows for this subject code as "Shared"
                 rowsInCode.forEach(r => {
                     rowsToHalve.add(r);

                     // Record for reporting
                     const ownerName = r.matchedStandardName;
                     if (ownerName) {
                         if (!halvedCodesMap.has(ownerName)) halvedCodesMap.set(ownerName, new Set());
                         halvedCodesMap.get(ownerName)?.add(code);
                     }
                 });
             }
         });
      });

      // 4. Final Aggregation
      // Formula: Adjusted Total = Raw Total - (Shared Count / 2)
      const results: ProcessedRow[] = stdNamesList.map(stdName => {
          const teacherRows = matchedRows.filter(r => r.matchedStandardName === stdName);

          let rawTotal = 0;
          let adjustedTotal = 0;

          teacherRows.forEach(r => {
              const val = Number(r.count) || 0;
              rawTotal += val;

              if (rowsToHalve.has(r)) {
                  // Shared subject: count counts as half
                  adjustedTotal += val / 2;
              } else {
                  // Normal subject: count counts as full
                  adjustedTotal += val;
              }
          });

          // Format halved codes for display
          const halvedSubjects = Array.from(halvedCodesMap.get(stdName) || []).join(', ');

          return {
              "姓名": stdName,
              "Raw Count": rawTotal,
              "Adjusted Count": adjustedTotal,
              "分数": calculateScore(adjustedTotal),
              "Halved Subjects": halvedSubjects
          };
      });

      setExtractedData(results);

    } catch (err) {
      console.error(err);
      setError("Failed to process. Please ensure the image is clear.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const downloadExcel = () => {
    if (!extractedData || extractedData.length === 0) return;

    const ws = XLSX.utils.json_to_sheet(extractedData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Scores");

    ws['!cols'] = [
        { wch: 20 }, // Name
        { wch: 10 }, // Raw
        { wch: 15 }, // Adjusted
        { wch: 10 }, // Score
        { wch: 30 }  // Halved Subjects
    ];
    XLSX.writeFile(wb, "class_scores.xlsx");
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col items-center py-12 px-4 sm:px-6 lg:px-8 text-gray-800">
