                )}

                {isAnalyzing && (
                  <div className="flex-1 flex flex-col items-center justify-center text-center space-y-4">
                    <Loader2 className="h-10 w-10 text-blue-600 animate-spin" />
                    <p className="text-gray-500">Extracting data...</p>
                  </div>
                )}

                {error && (
                  <div className="flex-1 flex flex-col items-center justify-center text-center space-y-4">
                    <p className="text-red-600">{error}</p>
                    <button onClick={analyzeImage} className="underline text-gray-600">Try Again</button>
                  </div>
                )}

                {extractedData && (
                  <div className="flex flex-col h-full w-full">
                    <div className="flex justify-between items-center mb-4">
                        <span className="text-green-700 font-medium flex items-center gap-2"><CheckCircle className="w-5 h-5"/> Done</span>
                        <span className="text-xs bg-gray-100 px-2 py-1 rounded">{extractedData.filter(r => r["Raw Count"] > 0).length} matched</span>
                    </div>
                    <div className="flex-1 overflow-auto border rounded-lg mb-4 bg-gray-50 scrollbar-hide max-h-[300px]">
                      <table className="min-w-full divide-y divide-gray-200 text-sm">
                        <thead className="bg-gray-100 sticky top-0">
                          <tr>
                            <th className="px-3 py-2 text-left text-gray-500">Name</th>
                            <th className="px-3 py-2 text-center text-gray-500">Raw</th>
                            <th className="px-3 py-2 text-center text-gray-500">Adj</th>
                            <th className="px-3 py-2 text-center text-gray-500">Score</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-200 bg-white">
                          {extractedData.map((row, idx) => (
                            <tr key={idx} className={row["Raw Count"] === 0 ? "opacity-50" : ""}>
                              <td className="px-3 py-2 whitespace-nowrap font-medium">{row['姓名']}</td>
                              <td className="px-3 py-2 text-center text-gray-400">{row['Raw Count']}</td>
                              <td className="px-3 py-2 text-center text-blue-600 font-medium group relative cursor-help">
                                {row['Adjusted Count']}
                                {row['Halved Subjects'] && (
                                  <div className="hidden group-hover:block absolute bottom-full left-1/2 -translate-x-1/2 mb-2 p-2 bg-gray-800 text-white text-xs rounded shadow-lg whitespace-normal min-w-[150px] z-10">
                                    Halved: {row['Halved Subjects']}
                                  </div>
                                )}
                              </td>
                              <td className={`px-3 py-2 text-center font-bold ${row['分数'] >= 5 ? 'text-green-600' : row['分数'] >= 3 ? 'text-blue-600' : 'text-gray-500'}`}>{row['分数']}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                    <button onClick={downloadExcel} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-6 rounded-lg shadow-md flex items-center justify-center gap-2">
                      <Download className="w-5 h-5" /> Download Excel
                    </button>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI } from "@google/genai";
import * as XLSX from 'https://esm.sh/xlsx';
import { Upload, FileSpreadsheet, Loader2, CheckCircle, AlertCircle, X, Download, Image as ImageIcon, Settings, Info, Users, HelpCircle, Eye, EyeOff } from 'lucide-react';

// Interfaces for type safety
interface RawRow {
  teacher: string;
  code: string;
  count: number;
  matchedStandardName?: string | null;
  normalizedCode?: string;
}

interface ProcessedRow {
  "姓名": string;
  "Raw Count": number;
  "Adjusted Count": number;
  "分数": number;
  "Halved Subjects": string;
}

const App = () => {
  const [file, setFile] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [extractedData, setExtractedData] = useState<ProcessedRow[] | null>(null);
  const [unmatchedRows, setUnmatchedRows] = useState<RawRow[]>([]);
  const [showUnmatched, setShowUnmatched] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [referenceNames, setReferenceNames] = useState<string>(`杨晶晶 Jenny
徐育梅 Catherine
储晓栋 Amy
孟雅 Alice
陈蓉 Lotus
谢淑平 Sherry
郭晶晶 Joy
李臣亚 Linna
杨阳Sunny
詹和太James
曹阳Bill
任艳 Rebecca
王芸 Yun
樊澄 Claire
孟远 Krystal
谭颖Tenny
刘鹏宇Dean
张月明 Jasmine 
徐晓娜 Elina
赵茹怡Daicen
金辰昊Colin
张金慧 Emily
冯灿Sunny
李雪维 Nicole 
张国靖 Alicia 
秦笑Sophie 
刘家玮Jane
施璎真Serena
丁佐伊Zoe
宋吉 Merissa 
王楚怡phyllis
周筱妍Ollie
张颖 Yvonne 
李苏粤Sibyl
许明月 Luna
季远兰 Mandy
吴飞Fiona（英语）
孙胜蓝 Sierra（英语）
汪苇 Winnie`);
  const [coTeachingNames, setCoTeachingNames] = useState<string>(`李苏粤Sibyl, Noku
谢淑平 Sherry, 李臣亚 Linna
冯灿Sunny,张金慧 Emily
秦笑Sophie, Superman
陈蓉 Lotus, Callum`);
  const [showSettings, setShowSettings] = useState(true);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const processFile = useCallback((selectedFile: File) => {
    if (!selectedFile.type.startsWith('image/')) {
      setError('Please select a valid image file (PNG, JPG, WEBP).');
      return;
    }

    setFile(selectedFile);
    setError(null);
    setExtractedData(null);
    setUnmatchedRows([]);

    const reader = new FileReader();
    reader.onload = (e) => {
      setImagePreview(e.target?.result as string);
    };
    reader.readAsDataURL(selectedFile);
  }, []);

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      processFile(e.target.files[0]);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      processFile(e.dataTransfer.files[0]);
    }
  };

  // Add Paste Event Listener
  useEffect(() => {
    const handlePaste = (e: ClipboardEvent) => {
      if (e.clipboardData && e.clipboardData.items) {
        for (let i = 0; i < e.clipboardData.items.length; i++) {
          const item = e.clipboardData.items[i];
          if (item.type.indexOf('image') !== -1) {
            const blob = item.getAsFile();
            if (blob) {
              processFile(blob);
              e.preventDefault();
              break;
            }
          }
        }
      }
    };

    document.addEventListener('paste', handlePaste);
    return () => {
      document.removeEventListener('paste', handlePaste);
    };
  }, [processFile]);

  const clearFile = () => {
    setFile(null);
    setImagePreview(null);
    setExtractedData(null);
    setUnmatchedRows([]);
    setError(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const calculateScore = (count: number) => {
    if (count <= 10) return 0;
    if (count <= 20) return 1;
    if (count <= 35) return 3;
    return 5;
  };

  // Helper to normalize subject codes (remove spaces, uppercase)
  const normalizeCode = (code: string) => {
    if (!code) return "";
    return code.replace(/\s+/g, '').toUpperCase();
  };

  // Helper to extract searchable keywords from a standard name line
  // e.g., "李苏粤Sibyl" -> ["李苏粤", "Sibyl"]
  const getKeywords = (standardNameLine: string) => {
    // Split by non-word characters but keep Chinese and English letters
    const parts = standardNameLine.match(/[\u4e00-\u9fa5]+|[a-zA-Z]+/g);
    return parts ? parts.map(p => p.toLowerCase()) : [];
  };

  const analyzeImage = async () => {
    if (!file || !imagePreview) return;

    setIsAnalyzing(true);
    setError(null);
    setUnmatchedRows([]);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const base64Data = imagePreview.split(',')[1];

      // Prompt asking for raw data extraction only
      let prompt = `
        Analyze this image containing a table.
        Columns are: "Teacher Name", "Subject Name", "Subject Code", "Number of Columns".

        Task:
        Extract EVERY data row (exclude "Total" rows).
        If "Teacher Name" is merged/empty for a row, use the teacher name from the row above it.

        Return a simple JSON array of objects:
        [
          { "teacher": "Exact string from image", "code": "Subject Code", "count": 123 },
          ...
        ]

        Output valid JSON only.
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: {
          parts: [
            {
              inlineData: {
                mimeType: file.type,
                data: base64Data
              }
            },
            { text: prompt }
          ]
        },
        config: {
          responseMimeType: "application/json"
        }
      });

      const responseText = response.text;
      if (!responseText) throw new Error("No data returned from model.");

      let rawRows: RawRow[] = [];
      try {
        const parsed = JSON.parse(responseText);
        if (Array.isArray(parsed)) {
            rawRows = parsed;
        } else if (typeof parsed === 'object') {
            const key = Object.keys(parsed).find(k => Array.isArray(parsed[k]));
            if (key) rawRows = parsed[key];
        }
      } catch (e) {
          throw new Error("Failed to parse AI response.");
      }

      // --- Client-Side Matching Algorithm ---

      // 1. Prepare Standard Names with Keywords
      const stdNamesList = referenceNames.split('\n').map(n => n.trim()).filter(n => n);
      const stdNameMatchers = stdNamesList.map(name => ({
          fullName: name,
          keywords: getKeywords(name)
      }));

      // 2. Assign each Raw Row to a Standard Name
      const matchedRows: RawRow[] = rawRows.map(row => {
          const rawTeacher = (row.teacher || "").toLowerCase();

          // Find best match in Standard List
          const match = stdNameMatchers.find(matcher => {
              return matcher.keywords.some(keyword => {
                  if (keyword.length < 2) return false; 
                  return rawTeacher.includes(keyword);
              });
          });

          return {
              ...row,
              matchedStandardName: match ? match.fullName : null,
              normalizedCode: normalizeCode(row.code)
          };
      });

      // Capture unmatched rows for debugging
      const unmatched = matchedRows.filter(r => !r.matchedStandardName);
      setUnmatchedRows(unmatched);

      // 3. Co-teaching Logic
      const rowsToHalve = new Set<RawRow>();
      const halvedCodesMap = new Map<string, Set<string>>(); // StandardName -> Set<SubjectCodes>

      const coTeachingGroups = coTeachingNames
        .split('\n')
        .map(line => line.split(/,|，/).map(n => n.trim().toLowerCase()).filter(n => n))
        .filter(group => group.length > 0);

      coTeachingGroups.forEach(groupKeywords => {
         // Filter rows that belong to this group (check Standard Name OR Raw Name)
         // This handles cases where a partner (e.g., Noku) is in the image but not in the Standard Name list.
         const groupRows = matchedRows.filter(row => {
             const standard = (row.matchedStandardName || "").toLowerCase();
             const raw = (row.teacher || "").toLowerCase();
             return groupKeywords.some(k => standard.includes(k) || raw.includes(k));
         });

         // Group by Subject Code within this co-teaching circle
         const codeMap = new Map<string, typeof matchedRows>();
         groupRows.forEach(row => {
             if (!row.normalizedCode) return;
             if (!codeMap.has(row.normalizedCode)) codeMap.set(row.normalizedCode, []);
             codeMap.get(row.normalizedCode)?.push(row);
         });

         codeMap.forEach((rowsInCode, code) => {
             // Check if multiple teachers (Standard OR Raw) are teaching this code
             const uniqueTeachers = new Set(rowsInCode.map(r => r.matchedStandardName || r.teacher));

             // In the group context, if we found > 1 teacher entity (e.g. Sibyl and Noku), we halve.
             if (uniqueTeachers.size > 1) {
                 // Mark all rows for this subject code as "Shared"
                 rowsInCode.forEach(r => {
                     rowsToHalve.add(r);

                     // Record for reporting
                     const ownerName = r.matchedStandardName;
                     if (ownerName) {
                         if (!halvedCodesMap.has(ownerName)) halvedCodesMap.set(ownerName, new Set());
                         halvedCodesMap.get(ownerName)?.add(code);
                     }
                 });
             }
         });
      });

      // 4. Final Aggregation
      // Formula: Adjusted Total = Raw Total - (Shared Count / 2)
      const results: ProcessedRow[] = stdNamesList.map(stdName => {
          const teacherRows = matchedRows.filter(r => r.matchedStandardName === stdName);

          let rawTotal = 0;
          let adjustedTotal = 0;

          teacherRows.forEach(r => {
              const val = Number(r.count) || 0;
              rawTotal += val;

              if (rowsToHalve.has(r)) {
                  // Shared subject: count counts as half
                  adjustedTotal += val / 2;
              } else {
                  // Normal subject: count counts as full
                  adjustedTotal += val;
              }
          });

          // Format halved codes for display
          const halvedSubjects = Array.from(halvedCodesMap.get(stdName) || []).join(', ');

          return {
              "姓名": stdName,
              "Raw Count": rawTotal,
              "Adjusted Count": adjustedTotal,
              "分数": calculateScore(adjustedTotal),
              "Halved Subjects": halvedSubjects
          };
      });

      setExtractedData(results);

    } catch (err) {
      console.error(err);
      setError("Failed to process. Please ensure the image is clear.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const downloadExcel = () => {
    if (!extractedData || extractedData.length === 0) return;

    const ws = XLSX.utils.json_to_sheet(extractedData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Scores");

    ws['!cols'] = [
        { wch: 20 }, // Name
        { wch: 10 }, // Raw
        { wch: 15 }, // Adjusted
        { wch: 10 }, // Score
        { wch: 30 }  // Halved Subjects
    ];
    XLSX.writeFile(wb, "class_scores.xlsx");
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col items-center py-12 px-4 sm:px-6 lg:px-8 text-gray-800">
      <div className="max-w-4xl w-full space-y-6">

        {/* Header */}
        <div className="text-center">
          <div className="mx-auto h-16 w-16 bg-blue-100 rounded-full flex items-center justify-center mb-4">
            <FileSpreadsheet className="h-8 w-8 text-blue-600" />
          </div>
          <h1 className="text-3xl font-bold text-gray-900 tracking-tight">Score Calculator</h1>
          <p className="mt-2 text-lg text-gray-600">
            Upload an image of the column counts.
          </p>
        </div>

        {/* Settings */}
        <div className="bg-white shadow-md rounded-xl overflow-hidden border border-gray-100">
          <div 
            className="px-6 py-4 bg-gray-50 border-b border-gray-200 flex items-center justify-between cursor-pointer"
            onClick={() => setShowSettings(!showSettings)}
          >
            <div className="flex items-center gap-2 font-medium text-gray-700">
              <Settings className="w-5 h-5" />
              <span>Settings</span>
            </div>
            <span className="text-sm text-blue-600 hover:text-blue-800">
              {showSettings ? 'Hide' : 'Show'}
            </span>
          </div>

          {showSettings && (
            <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
               {/* Standard Names */}
               <div>
                   <div className="mb-2 text-sm text-gray-700 font-semibold flex items-center gap-2">
                     <Users className="w-4 h-4" />
                     Standard Name List (Required)
                   </div>
                   <textarea
                     value={referenceNames}
                     onChange={(e) => setReferenceNames(e.target.value)}
                     className="w-full h-48 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm font-mono"
                   />
               </div>

               {/* Co-teaching Groups */}
               <div>
                   <div className="mb-2 text-sm text-gray-700 font-semibold flex items-center gap-2">
                     <Info className="w-4 h-4" />
                     Co-teaching Groups
                   </div>
                   <div className="mb-2 text-xs text-gray-500">
                     One group per line, comma separated.<br/>
                     Example: <code>Sherry, Linna</code>
                   </div>
                   <textarea
                     value={coTeachingNames}
                     onChange={(e) => setCoTeachingNames(e.target.value)}
                     className="w-full h-48 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm font-mono"
                   />
               </div>
            </div>
          )}
        </div>

        {/* Scoring Legend */}
        <div className="bg-blue-50 border border-blue-200 rounded-xl p-4 flex items-start gap-3">
            <HelpCircle className="w-5 h-5 text-blue-600 shrink-0 mt-0.5" />
            <div>
                <h3 className="text-sm font-semibold text-blue-900">Scoring Rules</h3>
                <div className="mt-1 flex flex-wrap gap-4 text-sm text-blue-800">
                    <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-gray-400"></span> Count ≤ 10: <b>0 pts</b></span>
                    <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-blue-400"></span> 11-20: <b>1 pt</b></span>
                    <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-blue-600"></span> 21-35: <b>3 pts</b></span>
                    <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-green-500"></span> > 35: <b>5 pts</b></span>
                </div>
            </div>
        </div>

        {/* Main Area */}
        <div className="bg-white shadow-xl rounded-2xl overflow-hidden border border-gray-100">
          {!imagePreview ? (
            <div 
              className="p-12 border-2 border-dashed border-gray-300 rounded-xl m-6 flex flex-col items-center justify-center hover:border-blue-500 hover:bg-blue-50 cursor-pointer"
              onDragOver={handleDragOver}
              onDrop={handleDrop}
              onClick={() => fileInputRef.current?.click()}
            >
              <Upload className="h-8 w-8 text-gray-500 mb-4" />
              <p className="text-lg font-medium text-gray-700">Click to upload or Paste (Ctrl+V)</p>
              <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileSelect} />
            </div>
          ) : (
            <div className="flex flex-col md:flex-row h-full min-h-[400px]">
              {/* Preview */}
              <div className="w-full md:w-1/2 bg-gray-100 p-6 flex flex-col items-center justify-center relative">
                <img src={imagePreview} alt="Preview" className="max-h-[400px] w-auto object-contain rounded-lg shadow-sm" />
                <button onClick={clearFile} className="absolute top-4 right-4 p-2 bg-white rounded-full shadow hover:text-red-500">
                  <X className="h-5 w-5" />
                </button>
              </div>

              {/* Actions/Results */}
              <div className="w-full md:w-1/2 p-6 flex flex-col">
                {!extractedData && !isAnalyzing && !error && (
                  <div className="flex-1 flex flex-col items-center justify-center space-y-6">
                    <button onClick={analyzeImage} className="w-full max-w-xs bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-6 rounded-lg shadow-md flex items-center justify-center gap-2">
                      <FileSpreadsheet className="w-5 h-5" />
                      Calculate Scores
                    </button>
                  </div>
                )}

                {isAnalyzing && (
                  <div className="flex-1 flex flex-col items-center justify-center text-center space-y-4">
                    <Loader2 className="h-10 w-10 text-blue-600 animate-spin" />
                    <p className="text-gray-500">Extracting data...</p>
                  </div>
                )}

                {error && (
                  <div className="flex-1 flex flex-col items-center justify-center text-center space-y-4">
                    <p className="text-red-600">{error}</p>
                    <button onClick={analyzeImage} className="underline text-gray-600">Try Again</button>
                  </div>
                )}

                {extractedData && (
                  <div className="flex flex-col h-full w-full">
                    <div className="flex justify-between items-center mb-4">
                        <span className="text-green-700 font-medium flex items-center gap-2"><CheckCircle className="w-5 h-5"/> Done</span>
                        <div className="flex gap-2">
                             {unmatchedRows.length > 0 && (
                                <button 
                                    onClick={() => setShowUnmatched(!showUnmatched)}
                                    className={`text-xs px-2 py-1 rounded flex items-center gap-1 ${showUnmatched ? 'bg-orange-100 text-orange-700' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
                                >
                                    {showUnmatched ? <EyeOff className="w-3 h-3"/> : <Eye className="w-3 h-3"/>}
                                    {unmatchedRows.length} Unmatched
                                </button>
                             )}
                            <span className="text-xs bg-gray-100 px-2 py-1 rounded">{extractedData.filter(r => r["Raw Count"] > 0).length} matched</span>
                        </div>
                    </div>

                    {/* Unmatched Rows Warning */}
                    {showUnmatched && unmatchedRows.length > 0 && (
                        <div className="mb-4 bg-orange-50 border border-orange-200 rounded-lg p-3 text-xs overflow-auto max-h-[150px]">
                            <h4 className="font-semibold text-orange-800 mb-2">Data found in image but not in Standard List:</h4>
                            <table className="w-full text-left text-orange-900">
                                <thead>
                                    <tr>
                                        <th className="pb-1">Teacher Found</th>
                                        <th className="pb-1">Count</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {unmatchedRows.map((r, i) => (
                                        <tr key={i} className="border-t border-orange-100">
                                            <td className="py-1 pr-2">{r.teacher}</td>
                                            <td className="py-1">{r.count}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                            <p className="mt-2 text-orange-600 italic">Check if names in "Settings" match these exact spellings.</p>
                        </div>
                    )}

                    <div className="flex-1 overflow-auto border rounded-lg mb-4 bg-gray-50 scrollbar-hide max-h-[300px]">
                      <table className="min-w-full divide-y divide-gray-200 text-sm">
                        <thead className="bg-gray-100 sticky top-0">
                          <tr>
                            <th className="px-3 py-2 text-left text-gray-500">Name</th>
                            <th className="px-3 py-2 text-center text-gray-500">Raw</th>
                            <th className="px-3 py-2 text-center text-gray-500">Adj</th>
                            <th className="px-3 py-2 text-center text-gray-500">Score</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-200 bg-white">
                          {extractedData.map((row, idx) => (
                            <tr key={idx} className={row["Raw Count"] === 0 ? "opacity-50" : ""}>
                              <td className="px-3 py-2 whitespace-nowrap font-medium">{row['姓名']}</td>
                              <td className="px-3 py-2 text-center text-gray-400">{row['Raw Count']}</td>
                              <td className="px-3 py-2 text-center text-blue-600 font-medium group relative cursor-help">
                                {row['Adjusted Count']}
                                {row['Halved Subjects'] && (
                                  <div className="hidden group-hover:block absolute bottom-full left-1/2 -translate-x-1/2 mb-2 p-2 bg-gray-800 text-white text-xs rounded shadow-lg whitespace-normal min-w-[150px] z-10">
                                    Halved: {row['Halved Subjects']}
                                  </div>
                                )}
                              </td>
                              <td className={`px-3 py-2 text-center font-bold ${row['分数'] >= 5 ? 'text-green-600' : row['分数'] >= 3 ? 'text-blue-600' : 'text-gray-500'}`}>{row['分数']}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                    <button onClick={downloadExcel} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-6 rounded-lg shadow-md flex items-center justify-center gap-2">
                      <Download className="w-5 h-5" /> Download Excel
                    </button>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI } from "@google/genai";
import * as XLSX from 'https://esm.sh/xlsx';
import { Upload, FileSpreadsheet, Loader2, CheckCircle, AlertCircle, X, Download, Image as ImageIcon, Settings, Info, Users, HelpCircle, Eye, EyeOff, FileText } from 'lucide-react';

// Interfaces for type safety
interface RawRow {
  teacher: string;
  code: string;
  count: number;
  matchedStandardName?: string | null;
  normalizedCode?: string;
}

interface ProcessedRow {
  "姓名": string;
  "Raw Count": number;
  "Adjusted Count": number;
  "分数": number;
  "Halved Subjects": string;
}

const App = () => {
  const [file, setFile] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [extractedData, setExtractedData] = useState<ProcessedRow[] | null>(null);
  const [unmatchedRows, setUnmatchedRows] = useState<RawRow[]>([]);
  const [showUnmatched, setShowUnmatched] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [referenceNames, setReferenceNames] = useState<string>(`杨晶晶 Jenny
徐育梅 Catherine
储晓栋 Amy
孟雅 Alice
陈蓉 Lotus
谢淑平 Sherry
郭晶晶 Joy
李臣亚 Linna
杨阳Sunny
詹和太James
曹阳Bill
任艳 Rebecca
王芸 Yun
樊澄 Claire
孟远 Krystal
谭颖Tenny
刘鹏宇Dean
张月明 Jasmine 
徐晓娜 Elina
赵茹怡Daicen
金辰昊Colin
张金慧 Emily
冯灿Sunny
李雪维 Nicole 
张国靖 Alicia 
秦笑Sophie 
刘家玮Jane
施璎真Serena
丁佐伊Zoe
宋吉 Merissa 
王楚怡phyllis
周筱妍Ollie
张颖 Yvonne 
李苏粤Sibyl
许明月 Luna
季远兰 Mandy
吴飞Fiona（英语）
孙胜蓝 Sierra（英语）
汪苇 Winnie`);
  const [coTeachingNames, setCoTeachingNames] = useState<string>(`李苏粤Sibyl, Noku
谢淑平 Sherry, 李臣亚 Linna
冯灿Sunny,张金慧 Emily
秦笑Sophie, Superman
陈蓉 Lotus, Callum`);
  const [showSettings, setShowSettings] = useState(true);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const processFile = useCallback((selectedFile: File) => {
    // Validate file type (Image OR Excel)
    const isImage = selectedFile.type.startsWith('image/');
    const isExcel = selectedFile.type === 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' || 
                    selectedFile.type === 'application/vnd.ms-excel' ||
                    selectedFile.name.endsWith('.xlsx') || 
                    selectedFile.name.endsWith('.xls');

    if (!isImage && !isExcel) {
      setError('Please select a valid Image (PNG, JPG) or Excel file (.xlsx, .xls).');
      return;
    }

    setFile(selectedFile);
    setError(null);
    setExtractedData(null);
    setUnmatchedRows([]);
    setImagePreview(null); // Reset preview

    if (isImage) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setImagePreview(e.target?.result as string);
      };
      reader.readAsDataURL(selectedFile);
    } 
    // For Excel, we don't generate an image preview, we just keep the file
  }, []);

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      processFile(e.target.files[0]);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      processFile(e.dataTransfer.files[0]);
    }
  };

  // Add Paste Event Listener
  useEffect(() => {
    const handlePaste = (e: ClipboardEvent) => {
      if (e.clipboardData && e.clipboardData.items) {
        for (let i = 0; i < e.clipboardData.items.length; i++) {
          const item = e.clipboardData.items[i];
          if (item.type.indexOf('image') !== -1) {
            const blob = item.getAsFile();
            if (blob) {
              processFile(blob);
              e.preventDefault();
              break;
            }
          }
        }
      }
    };

    document.addEventListener('paste', handlePaste);
    return () => {
      document.removeEventListener('paste', handlePaste);
    };
  }, [processFile]);

  const clearFile = () => {
    setFile(null);
    setImagePreview(null);
    setExtractedData(null);
    setUnmatchedRows([]);
    setError(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const calculateScore = (count: number) => {
    if (count <= 10) return 0;
    if (count <= 20) return 1;
    if (count <= 35) return 3;
    return 5;
  };

  // Helper to normalize subject codes (remove spaces, uppercase)
  const normalizeCode = (code: string) => {
    if (!code) return "";
    return code.replace(/\s+/g, '').toUpperCase();
  };

  // Helper to extract searchable keywords from a standard name line
  // e.g., "李苏粤Sibyl" -> ["李苏粤", "Sibyl"]
  const getKeywords = (standardNameLine: string) => {
    // Split by non-word characters but keep Chinese and English letters
    const parts = standardNameLine.match(/[\u4e00-\u9fa5]+|[a-zA-Z]+/g);
    return parts ? parts.map(p => p.toLowerCase()) : [];
  };

  const analyzeData = async () => {
    if (!file) return;

    setIsAnalyzing(true);
    setError(null);
    setUnmatchedRows([]);

    try {
      let rawRows: RawRow[] = [];

      // BRANCH 1: IMAGE PROCESSING (AI)
      if (file.type.startsWith('image/') && imagePreview) {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const base64Data = imagePreview.split(',')[1];

        // Prompt asking for raw data extraction only
        let prompt = `
          Analyze this image containing a table.
          Columns are: "Teacher Name", "Subject Name", "Subject Code", "Number of Columns".

          Task:
          Extract EVERY data row (exclude "Total" rows).
          If "Teacher Name" is merged/empty for a row, use the teacher name from the row above it.

          Return a simple JSON array of objects:
          [
            { "teacher": "Exact string from image", "code": "Subject Code", "count": 123 },
            ...
          ]

          Output valid JSON only.
        `;

        const response = await ai.models.generateContent({
          model: 'gemini-2.5-flash',
          contents: {
            parts: [
              {
                inlineData: {
                  mimeType: file.type,
                  data: base64Data
                }
              },
              { text: prompt }
            ]
          },
          config: {
            responseMimeType: "application/json"
          }
        });

        const responseText = response.text;
        if (!responseText) throw new Error("No data returned from model.");

        try {
          const parsed = JSON.parse(responseText);
          if (Array.isArray(parsed)) {
              rawRows = parsed;
          } else if (typeof parsed === 'object') {
              const key = Object.keys(parsed).find(k => Array.isArray(parsed[k]));
              if (key) rawRows = parsed[key];
          }
        } catch (e) {
            throw new Error("Failed to parse AI response.");
        }
      } 
      // BRANCH 2: EXCEL PROCESSING (LOCAL)
      else {
        const arrayBuffer = await file.arrayBuffer();
        const workbook = XLSX.read(arrayBuffer);
        const firstSheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[firstSheetName];

        // Convert sheet to JSON, treating first row as header
        const jsonData = XLSX.utils.sheet_to_json(worksheet, { defval: "" });

        // Logic to map columns and fill down teacher names (handle merged cells equivalent)
        let lastTeacher = "";

        rawRows = jsonData.map((row: any) => {
            // Attempt to find columns loosely matching the expected headers
            // Keys in 'row' depend on the Excel header strings
            const teacherKey = Object.keys(row).find(k => k.toLowerCase().includes('teacher') || k.toLowerCase().includes('name') || k.includes('姓名'));
            const codeKey = Object.keys(row).find(k => k.toLowerCase().includes('code') || k.includes('代码'));
            const countKey = Object.keys(row).find(k => k.toLowerCase().includes('column') || k.toLowerCase().includes('count') || k.includes('节数') || k.includes('数量'));

            let teacher = teacherKey ? String(row[teacherKey]).trim() : "";
            let code = codeKey ? String(row[codeKey]).trim() : "";
            let countStr = countKey ? String(row[countKey]) : "0";
            let count = parseFloat(countStr) || 0;

            // Simple Fill-Down Logic for Merged Cells (where only top cell has value)
            if (!teacher && lastTeacher) {
                teacher = lastTeacher;
            } else if (teacher) {
                lastTeacher = teacher;
            }

            return {
                teacher: teacher,
                code: code,
                count: count
            };
        }).filter(r => {
            // Filter out empty rows or rows that look like "Total" rows
            if (!r.teacher || r.teacher.toLowerCase().includes('total')) return false;
            if (r.count <= 0) return false;
            return true;
        });
      }

      // --- Client-Side Matching Algorithm (Shared logic for Image & Excel) ---

      // 1. Prepare Standard Names with Keywords
      const stdNamesList = referenceNames.split('\n').map(n => n.trim()).filter(n => n);
      const stdNameMatchers = stdNamesList.map(name => ({
          fullName: name,
          keywords: getKeywords(name)
      }));

      // 2. Assign each Raw Row to a Standard Name
      const matchedRows: RawRow[] = rawRows.map(row => {
          const rawTeacher = (row.teacher || "").toLowerCase();

          // Find best match in Standard List
          const match = stdNameMatchers.find(matcher => {
              return matcher.keywords.some(keyword => {
                  if (keyword.length < 2) return false; 
                  return rawTeacher.includes(keyword);
              });
          });

          return {
              ...row,
              matchedStandardName: match ? match.fullName : null,
              normalizedCode: normalizeCode(row.code)
          };
      });

      // Capture unmatched rows for debugging
      const unmatched = matchedRows.filter(r => !r.matchedStandardName);
      setUnmatchedRows(unmatched);

      // 3. Co-teaching Logic
      const rowsToHalve = new Set<RawRow>();
      const halvedCodesMap = new Map<string, Set<string>>(); // StandardName -> Set<SubjectCodes>

      const coTeachingGroups = coTeachingNames
        .split('\n')
        .map(line => line.split(/,|，/).map(n => n.trim().toLowerCase()).filter(n => n))
        .filter(group => group.length > 0);

      coTeachingGroups.forEach(groupKeywords => {
         // Filter rows that belong to this group (check Standard Name OR Raw Name)
         // This handles cases where a partner (e.g., Noku) is in the image but not in the Standard Name list.
         const groupRows = matchedRows.filter(row => {
             const standard = (row.matchedStandardName || "").toLowerCase();
             const raw = (row.teacher || "").toLowerCase();
             return groupKeywords.some(k => standard.includes(k) || raw.includes(k));
         });

         // Group by Subject Code within this co-teaching circle
         const codeMap = new Map<string, typeof matchedRows>();
         groupRows.forEach(row => {
             if (!row.normalizedCode) return;
             if (!codeMap.has(row.normalizedCode)) codeMap.set(row.normalizedCode, []);
             codeMap.get(row.normalizedCode)?.push(row);
         });

         codeMap.forEach((rowsInCode, code) => {
             // Check if multiple teachers (Standard OR Raw) are teaching this code
             const uniqueTeachers = new Set(rowsInCode.map(r => r.matchedStandardName || r.teacher));

             // In the group context, if we found > 1 teacher entity (e.g. Sibyl and Noku), we halve.
             if (uniqueTeachers.size > 1) {
                 // Mark all rows for this subject code as "Shared"
                 rowsInCode.forEach(r => {
                     rowsToHalve.add(r);

                     // Record for reporting
                     const ownerName = r.matchedStandardName;
                     if (ownerName) {
                         if (!halvedCodesMap.has(ownerName)) halvedCodesMap.set(ownerName, new Set());
                         halvedCodesMap.get(ownerName)?.add(code);
                     }
                 });
             }
         });
      });

      // 4. Final Aggregation
      // Formula: Adjusted Total = Raw Total - (Shared Count / 2)
      const results: ProcessedRow[] = stdNamesList.map(stdName => {
          const teacherRows = matchedRows.filter(r => r.matchedStandardName === stdName);

          let rawTotal = 0;
          let adjustedTotal = 0;

          teacherRows.forEach(r => {
              const val = Number(r.count) || 0;
              rawTotal += val;

              if (rowsToHalve.has(r)) {
                  // Shared subject: count counts as half
                  adjustedTotal += val / 2;
              } else {
                  // Normal subject: count counts as full
                  adjustedTotal += val;
              }
          });

          // Format halved codes for display
          const halvedSubjects = Array.from(halvedCodesMap.get(stdName) || []).join(', ');

          return {
              "姓名": stdName,
              "Raw Count": rawTotal,
              "Adjusted Count": adjustedTotal,
              "分数": calculateScore(adjustedTotal),
              "Halved Subjects": halvedSubjects
          };
      });

      setExtractedData(results);

    } catch (err) {
      console.error(err);
      setError("Failed to process. " + (err as Error).message);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const downloadExcel = () => {
    if (!extractedData || extractedData.length === 0) return;

    const ws = XLSX.utils.json_to_sheet(extractedData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Scores");

    ws['!cols'] = [
        { wch: 20 }, // Name
        { wch: 10 }, // Raw
        { wch: 15 }, // Adjusted
        { wch: 10 }, // Score
        { wch: 30 }  // Halved Subjects
    ];
    XLSX.writeFile(wb, "class_scores.xlsx");
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col items-center py-12 px-4 sm:px-6 lg:px-8 text-gray-800">
      <div className="max-w-4xl w-full space-y-6">

        {/* Header */}
        <div className="text-center">
          <div className="mx-auto h-16 w-16 bg-blue-100 rounded-full flex items-center justify-center mb-4">
            <FileSpreadsheet className="h-8 w-8 text-blue-600" />
          </div>
          <h1 className="text-3xl font-bold text-gray-900 tracking-tight">Score Calculator</h1>
          <p className="mt-2 text-lg text-gray-600">
            Upload an Image or Excel file of the column counts.
          </p>
        </div>

        {/* Settings */}
        <div className="bg-white shadow-md rounded-xl overflow-hidden border border-gray-100">
          <div 
            className="px-6 py-4 bg-gray-50 border-b border-gray-200 flex items-center justify-between cursor-pointer"
            onClick={() => setShowSettings(!showSettings)}
          >
            <div className="flex items-center gap-2 font-medium text-gray-700">
              <Settings className="w-5 h-5" />
              <span>Settings</span>
            </div>
            <span className="text-sm text-blue-600 hover:text-blue-800">
              {showSettings ? 'Hide' : 'Show'}
            </span>
          </div>

          {showSettings && (
            <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
               {/* Standard Names */}
               <div>
                   <div className="mb-2 text-sm text-gray-700 font-semibold flex items-center gap-2">
                     <Users className="w-4 h-4" />
                     Standard Name List (Required)
                   </div>
                   <textarea
                     value={referenceNames}
                     onChange={(e) => setReferenceNames(e.target.value)}
                     className="w-full h-48 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm font-mono"
                   />
               </div>

               {/* Co-teaching Groups */}
               <div>
                   <div className="mb-2 text-sm text-gray-700 font-semibold flex items-center gap-2">
                     <Info className="w-4 h-4" />
                     Co-teaching Groups
                   </div>
                   <div className="mb-2 text-xs text-gray-500">
                     One group per line, comma separated.<br/>
                     Example: <code>Sherry, Linna</code>
                   </div>
                   <textarea
                     value={coTeachingNames}
                     onChange={(e) => setCoTeachingNames(e.target.value)}
                     className="w-full h-48 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm font-mono"
                   />
               </div>
            </div>
          )}
        </div>

        {/* Scoring Legend */}
        <div className="bg-blue-50 border border-blue-200 rounded-xl p-4 flex items-start gap-3">
            <HelpCircle className="w-5 h-5 text-blue-600 shrink-0 mt-0.5" />
            <div>
                <h3 className="text-sm font-semibold text-blue-900">Scoring Rules</h3>
                <div className="mt-1 flex flex-wrap gap-4 text-sm text-blue-800">
                    <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-gray-400"></span> Count ≤ 10: <b>0 pts</b></span>
                    <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-blue-400"></span> 11-20: <b>1 pt</b></span>
                    <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-blue-600"></span> 21-35: <b>3 pts</b></span>
                    <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-green-500"></span> > 35: <b>5 pts</b></span>
                </div>
            </div>
        </div>

        {/* Main Area */}
        <div className="bg-white shadow-xl rounded-2xl overflow-hidden border border-gray-100">
          {!file ? (
            <div 
              className="p-12 border-2 border-dashed border-gray-300 rounded-xl m-6 flex flex-col items-center justify-center hover:border-blue-500 hover:bg-blue-50 cursor-pointer"
              onDragOver={handleDragOver}
              onDrop={handleDrop}
              onClick={() => fileInputRef.current?.click()}
            >
              <Upload className="h-8 w-8 text-gray-500 mb-4" />
              <p className="text-lg font-medium text-gray-700">Upload Image or Excel (Ctrl+V)</p>
              <p className="text-sm text-gray-500 mt-2">Supports .png, .jpg, .xlsx, .xls</p>
              <input type="file" ref={fileInputRef} className="hidden" accept="image/*,.xlsx,.xls,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel" onChange={handleFileSelect} />
            </div>
          ) : (
            <div className="flex flex-col md:flex-row h-full min-h-[400px]">
              {/* Preview */}
              <div className="w-full md:w-1/2 bg-gray-100 p-6 flex flex-col items-center justify-center relative">
                {imagePreview ? (
                   <img src={imagePreview} alt="Preview" className="max-h-[400px] w-auto object-contain rounded-lg shadow-sm" />
                ) : (
                   <div className="flex flex-col items-center justify-center text-gray-500">
                      <FileSpreadsheet className="w-24 h-24 text-green-600 mb-4" />
                      <p className="text-xl font-medium text-gray-700 text-center break-all">{file.name}</p>
                      <p className="text-sm">Excel File Loaded</p>
                   </div>
                )}

                <button onClick={clearFile} className="absolute top-4 right-4 p-2 bg-white rounded-full shadow hover:text-red-500">
                  <X className="h-5 w-5" />
                </button>
              </div>

              {/* Actions/Results */}
              <div className="w-full md:w-1/2 p-6 flex flex-col">
                {!extractedData && !isAnalyzing && !error && (
                  <div className="flex-1 flex flex-col items-center justify-center space-y-6">
                    <button onClick={analyzeData} className="w-full max-w-xs bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-6 rounded-lg shadow-md flex items-center justify-center gap-2">
                      <FileSpreadsheet className="w-5 h-5" />
                      Calculate Scores
                    </button>
                  </div>
                )}

                {isAnalyzing && (
                  <div className="flex-1 flex flex-col items-center justify-center text-center space-y-4">
                    <Loader2 className="h-10 w-10 text-blue-600 animate-spin" />
                    <p className="text-gray-500">Processing data...</p>
                  </div>
                )}

                {error && (
                  <div className="flex-1 flex flex-col items-center justify-center text-center space-y-4">
                    <p className="text-red-600">{error}</p>
                    <button onClick={analyzeData} className="underline text-gray-600">Try Again</button>
                  </div>
                )}

                {extractedData && (
                  <div className="flex flex-col h-full w-full">
                    <div className="flex justify-between items-center mb-4">
                        <span className="text-green-700 font-medium flex items-center gap-2"><CheckCircle className="w-5 h-5"/> Done</span>
                        <div className="flex gap-2">
                             {unmatchedRows.length > 0 && (
                                <button 
                                    onClick={() => setShowUnmatched(!showUnmatched)}
                                    className={`text-xs px-2 py-1 rounded flex items-center gap-1 ${showUnmatched ? 'bg-orange-100 text-orange-700' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
                                >
                                    {showUnmatched ? <EyeOff className="w-3 h-3"/> : <Eye className="w-3 h-3"/>}
                                    {unmatchedRows.length} Unmatched
                                </button>
                             )}
                            <span className="text-xs bg-gray-100 px-2 py-1 rounded">{extractedData.filter(r => r["Raw Count"] > 0).length} matched</span>
                        </div>
                    </div>

                    {/* Unmatched Rows Warning */}
                    {showUnmatched && unmatchedRows.length > 0 && (
                        <div className="mb-4 bg-orange-50 border border-orange-200 rounded-lg p-3 text-xs overflow-auto max-h-[150px]">
                            <h4 className="font-semibold text-orange-800 mb-2">Data found but not in Standard List:</h4>
                            <table className="w-full text-left text-orange-900">
                                <thead>
                                    <tr>
                                        <th className="pb-1">Teacher Found</th>
                                        <th className="pb-1">Count</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {unmatchedRows.map((r, i) => (
                                        <tr key={i} className="border-t border-orange-100">
                                            <td className="py-1 pr-2">{r.teacher}</td>
                                            <td className="py-1">{r.count}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                            <p className="mt-2 text-orange-600 italic">Check if names in "Settings" match these exact spellings.</p>
                        </div>
                    )}

                    <div className="flex-1 overflow-auto border rounded-lg mb-4 bg-gray-50 scrollbar-hide max-h-[300px]">
                      <table className="min-w-full divide-y divide-gray-200 text-sm">
                        <thead className="bg-gray-100 sticky top-0">
                          <tr>
                            <th className="px-3 py-2 text-left text-gray-500">Name</th>
                            <th className="px-3 py-2 text-center text-gray-500">Raw</th>
                            <th className="px-3 py-2 text-center text-gray-500">Adj</th>
                            <th className="px-3 py-2 text-center text-gray-500">Score</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-200 bg-white">
                          {extractedData.map((row, idx) => (
                            <tr key={idx} className={row["Raw Count"] === 0 ? "opacity-50" : ""}>
                              <td className="px-3 py-2 whitespace-nowrap font-medium">{row['姓名']}</td>
                              <td className="px-3 py-2 text-center text-gray-400">{row['Raw Count']}</td>
                              <td className="px-3 py-2 text-center text-blue-600 font-medium group relative cursor-help">
                                {row['Adjusted Count']}
                                {row['Halved Subjects'] && (
                                  <div className="hidden group-hover:block absolute bottom-full left-1/2 -translate-x-1/2 mb-2 p-2 bg-gray-800 text-white text-xs rounded shadow-lg whitespace-normal min-w-[150px] z-10">
                                    Halved: {row['Halved Subjects']}
                                  </div>
                                )}
                              </td>
                              <td className={`px-3 py-2 text-center font-bold ${row['分数'] >= 5 ? 'text-green-600' : row['分数'] >= 3 ? 'text-blue-600' : 'text-gray-500'}`}>{row['分数']}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                    <button onClick={downloadExcel} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-6 rounded-lg shadow-md flex items-center justify-center gap-2">
                      <Download className="w-5 h-5" /> Download Excel
                    </button>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI } from "@google/genai";
import * as XLSX from 'https://esm.sh/xlsx';
import { Upload, FileSpreadsheet, Loader2, CheckCircle, AlertCircle, X, Download, Image as ImageIcon, Settings, Info, Users, HelpCircle, Eye, EyeOff, FileText } from 'lucide-react';

// Interfaces for type safety
interface RawRow {
  teacher: string;
  code: string;
  count: number;
  matchedStandardName?: string | null;
  normalizedCode?: string;
}

interface ProcessedRow {
  "姓名": string;
  "Raw Count": number;
  "Adjusted Count": number;
  "分数": number;
  "Halved Subjects": string;
}

const App = () => {
  const [file, setFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null); // Base64 data for API (Image/PDF)
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [extractedData, setExtractedData] = useState<ProcessedRow[] | null>(null);
  const [unmatchedRows, setUnmatchedRows] = useState<RawRow[]>([]);
  const [showUnmatched, setShowUnmatched] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [referenceNames, setReferenceNames] = useState<string>(`杨晶晶 Jenny
徐育梅 Catherine
储晓栋 Amy
孟雅 Alice
陈蓉 Lotus
谢淑平 Sherry
郭晶晶 Joy
李臣亚 Linna
杨阳Sunny
詹和太James
曹阳Bill
任艳 Rebecca
王芸 Yun
樊澄 Claire
孟远 Krystal
谭颖Tenny
刘鹏宇Dean
张月明 Jasmine 
徐晓娜 Elina
赵茹怡Daicen
金辰昊Colin
张金慧 Emily
冯灿Sunny
李雪维 Nicole 
张国靖 Alicia 
秦笑Sophie 
刘家玮Jane
施璎真Serena
丁佐伊Zoe
宋吉 Merissa 
王楚怡phyllis
周筱妍Ollie
张颖 Yvonne 
李苏粤Sibyl
许明月 Luna
季远兰 Mandy
吴飞Fiona（英语）
孙胜蓝 Sierra（英语）
汪苇 Winnie`);
  const [coTeachingNames, setCoTeachingNames] = useState<string>(`李苏粤Sibyl, Noku
谢淑平 Sherry, 李臣亚 Linna
冯灿Sunny,张金慧 Emily
秦笑Sophie, Superman
陈蓉 Lotus, Callum`);
  const [showSettings, setShowSettings] = useState(true);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const processFile = useCallback((selectedFile: File) => {
    // Validate file type (Image OR Excel OR PDF)
    const isImage = selectedFile.type.startsWith('image/');
    const isPdf = selectedFile.type === 'application/pdf';
    const isExcel = selectedFile.type === 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' || 
                    selectedFile.type === 'application/vnd.ms-excel' ||
                    selectedFile.name.endsWith('.xlsx') || 
                    selectedFile.name.endsWith('.xls');

    if (!isImage && !isExcel && !isPdf) {
      setError('Please select a valid Image (PNG, JPG), PDF, or Excel file.');
      return;
    }

    setFile(selectedFile);
    setError(null);
    setExtractedData(null);
    setUnmatchedRows([]);
    setPreviewUrl(null);

    // Read file for preview/API (Images and PDFs need base64)
    if (isImage || isPdf) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setPreviewUrl(e.target?.result as string);
      };
      reader.readAsDataURL(selectedFile);
    } 
    // Excel files are read using ArrayBuffer in analyzeData
  }, []);

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      processFile(e.target.files[0]);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      processFile(e.dataTransfer.files[0]);
    }
  };

  // Add Paste Event Listener
  useEffect(() => {
    const handlePaste = (e: ClipboardEvent) => {
      if (e.clipboardData && e.clipboardData.items) {
        for (let i = 0; i < e.clipboardData.items.length; i++) {
          const item = e.clipboardData.items[i];
          if (item.type.indexOf('image') !== -1) {
            const blob = item.getAsFile();
            if (blob) {
              processFile(blob);
              e.preventDefault();
              break;
            }
          }
        }
      }
    };

    document.addEventListener('paste', handlePaste);
    return () => {
      document.removeEventListener('paste', handlePaste);
    };
  }, [processFile]);

  const clearFile = () => {
    setFile(null);
    setPreviewUrl(null);
    setExtractedData(null);
    setUnmatchedRows([]);
    setError(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const calculateScore = (count: number) => {
    if (count <= 10) return 0;
    if (count <= 20) return 1;
    if (count <= 35) return 3;
    return 5;
  };

  // Helper to normalize subject codes (remove spaces, uppercase)
  const normalizeCode = (code: string) => {
    if (!code) return "";
    return code.replace(/\s+/g, '').toUpperCase();
  };

  // Helper to extract searchable keywords from a standard name line
  const getKeywords = (standardNameLine: string) => {
    const parts = standardNameLine.match(/[\u4e00-\u9fa5]+|[a-zA-Z]+/g);
    return parts ? parts.map(p => p.toLowerCase()) : [];
  };

  const analyzeData = async () => {
    if (!file) return;

    setIsAnalyzing(true);
    setError(null);
    setUnmatchedRows([]);

    try {
      let rawRows: RawRow[] = [];

      // BRANCH 1: AI PROCESSING (IMAGE OR PDF)
      if ((file.type.startsWith('image/') || file.type === 'application/pdf') && previewUrl) {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const base64Data = previewUrl.split(',')[1];

        // Prompt optimization for full data extraction
        let prompt = `
          Analyze this ${file.type === 'application/pdf' ? 'PDF document' : 'image'} containing a table.
          The document may contain multiple pages or long lists. You MUST extract data from ALL pages/sections.

          Columns usually are: "Teacher Name", "Subject Name", "Subject Code", "Number of Columns" (Count).

          Task:
          1. Extract EVERY SINGLE data row. Do NOT summarize. Do NOT truncate. 
          2. Exclude "Total" rows.
          3. Handle Merged Cells: If "Teacher Name" is empty/merged, assume it is the same as the row above it.

          Return a JSON array of objects:
          [
            { "teacher": "Exact string from doc", "code": "Subject Code", "count": 123 },
            ...
          ]

          Output valid JSON only. Ensure you output the COMPLETE list.
        `;

        const response = await ai.models.generateContent({
          model: 'gemini-2.5-flash',
          contents: {
            parts: [
              {
                inlineData: {
                  mimeType: file.type,
                  data: base64Data
                }
              },
              { text: prompt }
            ]
          },
          config: {
            responseMimeType: "application/json"
          }
        });

        const responseText = response.text;
        if (!responseText) throw new Error("No data returned from model.");

        try {
          const parsed = JSON.parse(responseText);
          if (Array.isArray(parsed)) {
              rawRows = parsed;
          } else if (typeof parsed === 'object') {
              const key = Object.keys(parsed).find(k => Array.isArray(parsed[k]));
              if (key) rawRows = parsed[key];
          }
        } catch (e) {
            throw new Error("Failed to parse AI response. " + responseText.substring(0, 100));
        }
      } 
      // BRANCH 2: EXCEL PROCESSING (LOCAL)
      else {
        const arrayBuffer = await file.arrayBuffer();
        const workbook = XLSX.read(arrayBuffer);
        const firstSheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[firstSheetName];

        const jsonData = XLSX.utils.sheet_to_json(worksheet, { defval: "" });

        let lastTeacher = "";

        rawRows = jsonData.map((row: any) => {
            const teacherKey = Object.keys(row).find(k => k.toLowerCase().includes('teacher') || k.toLowerCase().includes('name') || k.includes('姓名'));
            const codeKey = Object.keys(row).find(k => k.toLowerCase().includes('code') || k.includes('代码'));
            const countKey = Object.keys(row).find(k => k.toLowerCase().includes('column') || k.toLowerCase().includes('count') || k.includes('节数') || k.includes('数量'));

            let teacher = teacherKey ? String(row[teacherKey]).trim() : "";
            let code = codeKey ? String(row[codeKey]).trim() : "";
            let countStr = countKey ? String(row[countKey]) : "0";
            let count = parseFloat(countStr) || 0;

            if (!teacher && lastTeacher) {
                teacher = lastTeacher;
            } else if (teacher) {
                lastTeacher = teacher;
            }

            return {
                teacher: teacher,
                code: code,
                count: count
            };
        }).filter(r => {
            if (!r.teacher || r.teacher.toLowerCase().includes('total')) return false;
            if (r.count <= 0) return false;
            return true;
        });
      }

      // --- Client-Side Matching Algorithm ---

      // 1. Prepare Standard Names
      const stdNamesList = referenceNames.split('\n').map(n => n.trim()).filter(n => n);
      const stdNameMatchers = stdNamesList.map(name => ({
          fullName: name,
          keywords: getKeywords(name)
      }));

      // 2. Match Rows
      const matchedRows: RawRow[] = rawRows.map(row => {
          const rawTeacher = (row.teacher || "").toLowerCase();

          const match = stdNameMatchers.find(matcher => {
              return matcher.keywords.some(keyword => {
                  if (keyword.length < 2) return false; 
                  return rawTeacher.includes(keyword);
              });
          });

          return {
              ...row,
              matchedStandardName: match ? match.fullName : null,
              normalizedCode: normalizeCode(row.code)
          };
      });

      setUnmatchedRows(matchedRows.filter(r => !r.matchedStandardName));

      // 3. Co-teaching Logic
      const rowsToHalve = new Set<RawRow>();
      const halvedCodesMap = new Map<string, Set<string>>();

      const coTeachingGroups = coTeachingNames
        .split('\n')
        .map(line => line.split(/,|，/).map(n => n.trim().toLowerCase()).filter(n => n))
        .filter(group => group.length > 0);

      coTeachingGroups.forEach(groupKeywords => {
         const groupRows = matchedRows.filter(row => {
             const standard = (row.matchedStandardName || "").toLowerCase();
             const raw = (row.teacher || "").toLowerCase();
             return groupKeywords.some(k => standard.includes(k) || raw.includes(k));
         });

         const codeMap = new Map<string, typeof matchedRows>();
         groupRows.forEach(row => {
             if (!row.normalizedCode) return;
             if (!codeMap.has(row.normalizedCode)) codeMap.set(row.normalizedCode, []);
             codeMap.get(row.normalizedCode)?.push(row);
         });

         codeMap.forEach((rowsInCode, code) => {
             const uniqueTeachers = new Set(rowsInCode.map(r => r.matchedStandardName || r.teacher));
             if (uniqueTeachers.size > 1) {
                 rowsInCode.forEach(r => {
                     rowsToHalve.add(r);
                     const ownerName = r.matchedStandardName;
                     if (ownerName) {
                         if (!halvedCodesMap.has(ownerName)) halvedCodesMap.set(ownerName, new Set());
                         halvedCodesMap.get(ownerName)?.add(code);
                     }
                 });
             }
         });
      });

      // 4. Aggregation
      const results: ProcessedRow[] = stdNamesList.map(stdName => {
          const teacherRows = matchedRows.filter(r => r.matchedStandardName === stdName);

          let rawTotal = 0;
          let adjustedTotal = 0;

          teacherRows.forEach(r => {
              const val = Number(r.count) || 0;
              rawTotal += val;

              if (rowsToHalve.has(r)) {
                  adjustedTotal += val / 2;
              } else {
                  adjustedTotal += val;
              }
          });

          const halvedSubjects = Array.from(halvedCodesMap.get(stdName) || []).join(', ');

          return {
              "姓名": stdName,
              "Raw Count": rawTotal,
              "Adjusted Count": adjustedTotal,
              "分数": calculateScore(adjustedTotal),
              "Halved Subjects": halvedSubjects
          };
      });

      setExtractedData(results);

    } catch (err) {
      console.error(err);
      setError("Failed to process. " + (err as Error).message);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const downloadExcel = () => {
    if (!extractedData || extractedData.length === 0) return;

    const ws = XLSX.utils.json_to_sheet(extractedData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Scores");

    ws['!cols'] = [
        { wch: 20 }, 
        { wch: 10 }, 
        { wch: 15 }, 
        { wch: 10 }, 
        { wch: 30 }
    ];
    XLSX.writeFile(wb, "class_scores.xlsx");
  };

  // Helper to determine preview content
  const renderPreview = () => {
    if (!file) return null;

    // Image Preview
    if (file.type.startsWith('image/') && previewUrl) {
        return <img src={previewUrl} alt="Preview" className="max-h-[400px] w-auto object-contain rounded-lg shadow-sm" />;
    }

    // PDF or Excel Icon Preview
    return (
       <div className="flex flex-col items-center justify-center text-gray-500">
          {file.type.includes('pdf') ? (
              <FileText className="w-24 h-24 text-red-600 mb-4" />
          ) : (
              <FileSpreadsheet className="w-24 h-24 text-green-600 mb-4" />
          )}
          <p className="text-xl font-medium text-gray-700 text-center break-all px-4">{file.name}</p>
          <p className="text-sm font-medium mt-2 uppercase tracking-wide">
             {file.type.includes('pdf') ? 'PDF Document' : 'Excel Spreadsheet'}
          </p>
       </div>
    );
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col items-center py-12 px-4 sm:px-6 lg:px-8 text-gray-800">
      <div className="max-w-4xl w-full space-y-6">

        {/* Header */}
        <div className="text-center">
          <div className="mx-auto h-16 w-16 bg-blue-100 rounded-full flex items-center justify-center mb-4">
            <FileSpreadsheet className="h-8 w-8 text-blue-600" />
          </div>
          <h1 className="text-3xl font-bold text-gray-900 tracking-tight">Score Calculator</h1>
          <p className="mt-2 text-lg text-gray-600">
            Upload an Image, PDF, or Excel file of the column counts.
          </p>
        </div>

        {/* Settings */}
        <div className="bg-white shadow-md rounded-xl overflow-hidden border border-gray-100">
          <div 
            className="px-6 py-4 bg-gray-50 border-b border-gray-200 flex items-center justify-between cursor-pointer"
            onClick={() => setShowSettings(!showSettings)}
          >
            <div className="flex items-center gap-2 font-medium text-gray-700">
              <Settings className="w-5 h-5" />
              <span>Settings</span>
            </div>
            <span className="text-sm text-blue-600 hover:text-blue-800">
              {showSettings ? 'Hide' : 'Show'}
            </span>
          </div>

          {showSettings && (
            <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
               {/* Standard Names */}
               <div>
                   <div className="mb-2 text-sm text-gray-700 font-semibold flex items-center gap-2">
                     <Users className="w-4 h-4" />
                     Standard Name List (Required)
                   </div>
                   <textarea
                     value={referenceNames}
                     onChange={(e) => setReferenceNames(e.target.value)}
                     className="w-full h-48 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm font-mono"
                   />
               </div>

               {/* Co-teaching Groups */}
               <div>
                   <div className="mb-2 text-sm text-gray-700 font-semibold flex items-center gap-2">
                     <Info className="w-4 h-4" />
                     Co-teaching Groups
                   </div>
                   <div className="mb-2 text-xs text-gray-500">
                     One group per line, comma separated.<br/>
                     Example: <code>Sherry, Linna</code>
                   </div>
                   <textarea
                     value={coTeachingNames}
                     onChange={(e) => setCoTeachingNames(e.target.value)}
                     className="w-full h-48 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm font-mono"
                   />
               </div>
            </div>
          )}
        </div>

        {/* Scoring Legend */}
        <div className="bg-blue-50 border border-blue-200 rounded-xl p-4 flex items-start gap-3">
            <HelpCircle className="w-5 h-5 text-blue-600 shrink-0 mt-0.5" />
            <div>
                <h3 className="text-sm font-semibold text-blue-900">Scoring Rules</h3>
                <div className="mt-1 flex flex-wrap gap-4 text-sm text-blue-800">
                    <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-gray-400"></span> Count ≤ 10: <b>0 pts</b></span>
                    <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-blue-400"></span> 11-20: <b>1 pt</b></span>
                    <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-blue-600"></span> 21-35: <b>3 pts</b></span>
                    <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-green-500"></span> > 35: <b>5 pts</b></span>
                </div>
            </div>
        </div>

        {/* Main Area */}
        <div className="bg-white shadow-xl rounded-2xl overflow-hidden border border-gray-100">
          {!file ? (
            <div 
              className="p-12 border-2 border-dashed border-gray-300 rounded-xl m-6 flex flex-col items-center justify-center hover:border-blue-500 hover:bg-blue-50 cursor-pointer"
              onDragOver={handleDragOver}
              onDrop={handleDrop}
              onClick={() => fileInputRef.current?.click()}
            >
              <Upload className="h-8 w-8 text-gray-500 mb-4" />
              <p className="text-lg font-medium text-gray-700">Upload Image, PDF or Excel (Ctrl+V)</p>
              <p className="text-sm text-gray-500 mt-2">Supports .png, .jpg, .pdf, .xlsx</p>
              <input type="file" ref={fileInputRef} className="hidden" accept="image/*,.pdf,.xlsx,.xls,application/pdf,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel" onChange={handleFileSelect} />
            </div>
          ) : (
            <div className="flex flex-col md:flex-row h-full min-h-[400px]">
              {/* Preview */}
              <div className="w-full md:w-1/2 bg-gray-100 p-6 flex flex-col items-center justify-center relative">
                {renderPreview()}

                <button onClick={clearFile} className="absolute top-4 right-4 p-2 bg-white rounded-full shadow hover:text-red-500">
                  <X className="h-5 w-5" />
                </button>
              </div>

              {/* Actions/Results */}
              <div className="w-full md:w-1/2 p-6 flex flex-col">
                {!extractedData && !isAnalyzing && !error && (
                  <div className="flex-1 flex flex-col items-center justify-center space-y-6">
                    <button onClick={analyzeData} className="w-full max-w-xs bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-6 rounded-lg shadow-md flex items-center justify-center gap-2">
                      <FileSpreadsheet className="w-5 h-5" />
                      Calculate Scores
                    </button>
                  </div>
                )}

                {isAnalyzing && (
                  <div className="flex-1 flex flex-col items-center justify-center text-center space-y-4">
                    <Loader2 className="h-10 w-10 text-blue-600 animate-spin" />
                    <p className="text-gray-500">Processing entire document...</p>
                  </div>
                )}

                {error && (
                  <div className="flex-1 flex flex-col items-center justify-center text-center space-y-4">
                    <p className="text-red-600">{error}</p>
                    <button onClick={analyzeData} className="underline text-gray-600">Try Again</button>
                  </div>
                )}

                {extractedData && (
                  <div className="flex flex-col h-full w-full">
                    <div className="flex justify-between items-center mb-4">
                        <span className="text-green-700 font-medium flex items-center gap-2"><CheckCircle className="w-5 h-5"/> Done</span>
                        <div className="flex gap-2">
                             {unmatchedRows.length > 0 && (
                                <button 
                                    onClick={() => setShowUnmatched(!showUnmatched)}
                                    className={`text-xs px-2 py-1 rounded flex items-center gap-1 ${showUnmatched ? 'bg-orange-100 text-orange-700' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
                                >
                                    {showUnmatched ? <EyeOff className="w-3 h-3"/> : <Eye className="w-3 h-3"/>}
                                    {unmatchedRows.length} Unmatched
                                </button>
                             )}
                            <span className="text-xs bg-gray-100 px-2 py-1 rounded">{extractedData.filter(r => r["Raw Count"] > 0).length} matched</span>
                        </div>
                    </div>

                    {/* Unmatched Rows Warning */}
                    {showUnmatched && unmatchedRows.length > 0 && (
                        <div className="mb-4 bg-orange-50 border border-orange-200 rounded-lg p-3 text-xs overflow-auto max-h-[150px]">
                            <h4 className="font-semibold text-orange-800 mb-2">Data found but not in Standard List:</h4>
                            <table className="w-full text-left text-orange-900">
                                <thead>
                                    <tr>
                                        <th className="pb-1">Teacher Found</th>
                                        <th className="pb-1">Count</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {unmatchedRows.map((r, i) => (
                                        <tr key={i} className="border-t border-orange-100">
                                            <td className="py-1 pr-2">{r.teacher}</td>
                                            <td className="py-1">{r.count}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                            <p className="mt-2 text-orange-600 italic">Check if names in "Settings" match these exact spellings.</p>
                        </div>
                    )}

                    <div className="flex-1 overflow-auto border rounded-lg mb-4 bg-gray-50 scrollbar-hide max-h-[300px]">
                      <table className="min-w-full divide-y divide-gray-200 text-sm">
                        <thead className="bg-gray-100 sticky top-0">
                          <tr>
                            <th className="px-3 py-2 text-left text-gray-500">Name</th>
                            <th className="px-3 py-2 text-center text-gray-500">Raw</th>
                            <th className="px-3 py-2 text-center text-gray-500">Adj</th>
                            <th className="px-3 py-2 text-center text-gray-500">Score</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-200 bg-white">
                          {extractedData.map((row, idx) => (
                            <tr key={idx} className={row["Raw Count"] === 0 ? "opacity-50" : ""}>
                              <td className="px-3 py-2 whitespace-nowrap font-medium">{row['姓名']}</td>
                              <td className="px-3 py-2 text-center text-gray-400">{row['Raw Count']}</td>
                              <td className="px-3 py-2 text-center text-blue-600 font-medium group relative cursor-help">
                                {row['Adjusted Count']}
                                {row['Halved Subjects'] && (
                                  <div className="hidden group-hover:block absolute bottom-full left-1/2 -translate-x-1/2 mb-2 p-2 bg-gray-800 text-white text-xs rounded shadow-lg whitespace-normal min-w-[150px] z-10">
                                    Halved: {row['Halved Subjects']}
                                  </div>
                                )}
                              </td>
                              <td className={`px-3 py-2 text-center font-bold ${row['分数'] >= 5 ? 'text-green-600' : row['分数'] >= 3 ? 'text-blue-600' : 'text-gray-500'}`}>{row['分数']}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                    <button onClick={downloadExcel} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-6 rounded-lg shadow-md flex items-center justify-center gap-2">
                      <Download className="w-5 h-5" /> Download Excel
                    </button>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI } from "@google/genai";
import * as XLSX from 'https://esm.sh/xlsx';
import { Upload, FileSpreadsheet, Loader2, CheckCircle, AlertCircle, X, Download, Image as ImageIcon, Settings, Info, Users, HelpCircle, Eye, EyeOff, FileText } from 'lucide-react';

// Interfaces for type safety
interface RawRow {
  teacher: string;
  code: string;
  count: number;
  matchedStandardName?: string | null;
  normalizedCode?: string;
}

interface ProcessedRow {
  "姓名": string;
  "Raw Count": number;
  "Adjusted Count": number;
  "分数": number;
  "Halved Subjects": string;
}

const App = () => {
  const [file, setFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null); // Base64 data for API (Image/PDF)
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [extractedData, setExtractedData] = useState<ProcessedRow[] | null>(null);
  const [unmatchedRows, setUnmatchedRows] = useState<RawRow[]>([]);
  const [showUnmatched, setShowUnmatched] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [referenceNames, setReferenceNames] = useState<string>(`杨晶晶 Jenny
徐育梅 Catherine
储晓栋 Amy
孟雅 Alice
陈蓉 Lotus
谢淑平 Sherry
郭晶晶 Joy
李臣亚 Linna
杨阳Sunny Yang
詹和太James
曹阳Bill
任艳 Rebecca
王芸 Yun
樊澄 Claire
孟远 Krystal
谭颖Tenny
刘鹏宇Dean
张月明 Jasmine
徐晓娜 Elina
赵茹怡Daicen
金辰昊Colin
张金慧 Emily
冯灿Sunny Feng
李雪维 Nicole
张国靖 Alicia
秦笑Sophie
刘家玮Jane
施璎真Serena
丁佐伊Zoe
宋吉 Merissa
王楚怡phyllis
周筱妍Ollie
张颖 Yvonne
李苏粤Sibyl
许明月 Luna
季远兰 Mandy
吴飞Fiona（英语）
孙胜蓝 Sierra（英语）
汪苇 Winnie`);
  const [coTeachingNames, setCoTeachingNames] = useState<string>(`李苏粤Sibyl, Noku
谢淑平 Sherry, 李臣亚 Linna
冯灿Sunny,张金慧 Emily
秦笑Sophie, Superman
陈蓉 Lotus, Callum`);
  const [showSettings, setShowSettings] = useState(true);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const processFile = useCallback((selectedFile: File) => {
    // Validate file type (Image OR Excel OR PDF)
    const isImage = selectedFile.type.startsWith('image/');
    const isPdf = selectedFile.type === 'application/pdf';
    const isExcel = selectedFile.type === 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' || 
                    selectedFile.type === 'application/vnd.ms-excel' ||
                    selectedFile.name.endsWith('.xlsx') || 
                    selectedFile.name.endsWith('.xls');

    if (!isImage && !isExcel && !isPdf) {
      setError('Please select a valid Image (PNG, JPG), PDF, or Excel file.');
      return;
    }

    setFile(selectedFile);
    setError(null);
    setExtractedData(null);
    setUnmatchedRows([]);
    setPreviewUrl(null);

    // Read file for preview/API (Images and PDFs need base64)
    if (isImage || isPdf) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setPreviewUrl(e.target?.result as string);
      };
      reader.readAsDataURL(selectedFile);
    } 
    // Excel files are read using ArrayBuffer in analyzeData
  }, []);

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      processFile(e.target.files[0]);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      processFile(e.dataTransfer.files[0]);
    }
  };

  // Add Paste Event Listener
  useEffect(() => {
    const handlePaste = (e: ClipboardEvent) => {
      if (e.clipboardData && e.clipboardData.items) {
        for (let i = 0; i < e.clipboardData.items.length; i++) {
          const item = e.clipboardData.items[i];
          if (item.type.indexOf('image') !== -1) {
            const blob = item.getAsFile();
            if (blob) {
              processFile(blob);
              e.preventDefault();
              break;
            }
          }
        }
      }
    };

    document.addEventListener('paste', handlePaste);
    return () => {
      document.removeEventListener('paste', handlePaste);
    };
  }, [processFile]);

  const clearFile = () => {
    setFile(null);
    setPreviewUrl(null);
    setExtractedData(null);
    setUnmatchedRows([]);
    setError(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const calculateScore = (count: number) => {
    if (count <= 10) return 0;
    if (count <= 20) return 1;
    if (count <= 35) return 3;
    return 5;
  };

  // Helper to normalize subject codes (remove spaces, uppercase)
  const normalizeCode = (code: string) => {
    if (!code) return "";
    return code.replace(/\s+/g, '').toUpperCase();
  };

  // Helper to extract searchable keywords from a standard name line
  const getKeywords = (standardNameLine: string) => {
    const parts = standardNameLine.match(/[\u4e00-\u9fa5]+|[a-zA-Z]+/g);
    return parts ? parts.map(p => p.toLowerCase()) : [];
  };

  const analyzeData = async () => {
    if (!file) return;

    setIsAnalyzing(true);
    setError(null);
    setUnmatchedRows([]);

    try {
      let rawRows: RawRow[] = [];

      // BRANCH 1: AI PROCESSING (IMAGE OR PDF)
      if ((file.type.startsWith('image/') || file.type === 'application/pdf') && previewUrl) {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const base64Data = previewUrl.split(',')[1];

        // Prompt optimization for full data extraction
        let prompt = `
          Analyze this ${file.type === 'application/pdf' ? 'PDF document' : 'image'} containing a table.
          The document may contain multiple pages or long lists. You MUST extract data from ALL pages/sections.

          Columns usually are: "Teacher Name", "Subject Name", "Subject Code", "Number of Columns" (Count).

          Task:
          1. Extract EVERY SINGLE data row. Do NOT summarize. Do NOT truncate. 
          2. Exclude "Total" rows.
          3. Handle Merged Cells: If "Teacher Name" is empty/merged, assume it is the same as the row above it.

          Return a JSON array of objects:
          [
            { "teacher": "Exact string from doc", "code": "Subject Code", "count": 123 },
            ...
          ]

          Output valid JSON only. Ensure you output the COMPLETE list.
        `;

        const response = await ai.models.generateContent({
          model: 'gemini-2.5-flash',
          contents: {
            parts: [
              {
                inlineData: {
                  mimeType: file.type,
                  data: base64Data
                }
              },
              { text: prompt }
            ]
          },
          config: {
            responseMimeType: "application/json"
          }
        });

        const responseText = response.text;
        if (!responseText) throw new Error("No data returned from model.");

        try {
          const parsed = JSON.parse(responseText);
          if (Array.isArray(parsed)) {
              rawRows = parsed;
          } else if (typeof parsed === 'object') {
              const key = Object.keys(parsed).find(k => Array.isArray(parsed[k]));
              if (key) rawRows = parsed[key];
          }
        } catch (e) {
            throw new Error("Failed to parse AI response. " + responseText.substring(0, 100));
        }
      } 
      // BRANCH 2: EXCEL PROCESSING (LOCAL)
      else {
        const arrayBuffer = await file.arrayBuffer();
        const workbook = XLSX.read(arrayBuffer);
        const firstSheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[firstSheetName];

        const jsonData = XLSX.utils.sheet_to_json(worksheet, { defval: "" });

        let lastTeacher = "";

        rawRows = jsonData.map((row: any) => {
            const teacherKey = Object.keys(row).find(k => k.toLowerCase().includes('teacher') || k.toLowerCase().includes('name') || k.includes('姓名'));
            const codeKey = Object.keys(row).find(k => k.toLowerCase().includes('code') || k.includes('代码'));
            const countKey = Object.keys(row).find(k => k.toLowerCase().includes('column') || k.toLowerCase().includes('count') || k.includes('节数') || k.includes('数量'));

            let teacher = teacherKey ? String(row[teacherKey]).trim() : "";
            let code = codeKey ? String(row[codeKey]).trim() : "";
            let countStr = countKey ? String(row[countKey]) : "0";
            let count = parseFloat(countStr) || 0;

            if (!teacher && lastTeacher) {
                teacher = lastTeacher;
            } else if (teacher) {
                lastTeacher = teacher;
            }

            return {
                teacher: teacher,
                code: code,
                count: count
            };
        }).filter(r => {
            if (!r.teacher || r.teacher.toLowerCase().includes('total')) return false;
            if (r.count <= 0) return false;
            return true;
        });
      }

      // --- Client-Side Matching Algorithm ---

      // 1. Prepare Standard Names
      const stdNamesList = referenceNames.split('\n').map(n => n.trim()).filter(n => n);
      const stdNameMatchers = stdNamesList.map(name => ({
          fullName: name,
          keywords: getKeywords(name)
      }));

      // 2. Match Rows
      const matchedRows: RawRow[] = rawRows.map(row => {
          const rawTeacher = (row.teacher || "").toLowerCase();

          const match = stdNameMatchers.find(matcher => {
              return matcher.keywords.some(keyword => {
                  if (keyword.length < 2) return false; 
                  return rawTeacher.includes(keyword);
              });
          });

          return {
              ...row,
              matchedStandardName: match ? match.fullName : null,
              normalizedCode: normalizeCode(row.code)
          };
      });

      setUnmatchedRows(matchedRows.filter(r => !r.matchedStandardName));

      // 3. Co-teaching Logic
      const rowsToHalve = new Set<RawRow>();
      const halvedCodesMap = new Map<string, Set<string>>();

      const coTeachingGroups = coTeachingNames
        .split('\n')
        .map(line => line.split(/,|，/).map(n => n.trim().toLowerCase()).filter(n => n))
        .filter(group => group.length > 0);

      coTeachingGroups.forEach(groupKeywords => {
         const groupRows = matchedRows.filter(row => {
             const standard = (row.matchedStandardName || "").toLowerCase();
             const raw = (row.teacher || "").toLowerCase();
             return groupKeywords.some(k => standard.includes(k) || raw.includes(k));
         });

         const codeMap = new Map<string, typeof matchedRows>();
         groupRows.forEach(row => {
             if (!row.normalizedCode) return;
             if (!codeMap.has(row.normalizedCode)) codeMap.set(row.normalizedCode, []);
             codeMap.get(row.normalizedCode)?.push(row);
         });

         codeMap.forEach((rowsInCode, code) => {
             const uniqueTeachers = new Set(rowsInCode.map(r => r.matchedStandardName || r.teacher));
             if (uniqueTeachers.size > 1) {
                 rowsInCode.forEach(r => {
                     rowsToHalve.add(r);
                     const ownerName = r.matchedStandardName;
                     if (ownerName) {
                         if (!halvedCodesMap.has(ownerName)) halvedCodesMap.set(ownerName, new Set());
                         halvedCodesMap.get(ownerName)?.add(code);
                     }
                 });
             }
         });
      });

      // 4. Aggregation
      const results: ProcessedRow[] = stdNamesList.map(stdName => {
          const teacherRows = matchedRows.filter(r => r.matchedStandardName === stdName);

          let rawTotal = 0;
          let adjustedTotal = 0;

          teacherRows.forEach(r => {
              const val = Number(r.count) || 0;
              rawTotal += val;

              if (rowsToHalve.has(r)) {
                  adjustedTotal += val / 2;
              } else {
                  adjustedTotal += val;
              }
          });

          const halvedSubjects = Array.from(halvedCodesMap.get(stdName) || []).join(', ');

          return {
              "姓名": stdName,
              "Raw Count": rawTotal,
              "Adjusted Count": adjustedTotal,
              "分数": calculateScore(adjustedTotal),
              "Halved Subjects": halvedSubjects
          };
      });

      setExtractedData(results);

    } catch (err) {
      console.error(err);
      setError("Failed to process. " + (err as Error).message);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const downloadExcel = () => {
    if (!extractedData || extractedData.length === 0) return;

    const ws = XLSX.utils.json_to_sheet(extractedData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Scores");

    ws['!cols'] = [
        { wch: 20 }, 
        { wch: 10 }, 
        { wch: 15 }, 
        { wch: 10 }, 
        { wch: 30 }
    ];
    XLSX.writeFile(wb, "class_scores.xlsx");
  };

  // Helper to determine preview content
  const renderPreview = () => {
    if (!file) return null;

    // Image Preview
    if (file.type.startsWith('image/') && previewUrl) {
        return <img src={previewUrl} alt="Preview" className="max-h-[400px] w-auto object-contain rounded-lg shadow-sm" />;
    }

    // PDF or Excel Icon Preview
    return (
       <div className="flex flex-col items-center justify-center text-gray-500">
          {file.type.includes('pdf') ? (
              <FileText className="w-24 h-24 text-red-600 mb-4" />
          ) : (
              <FileSpreadsheet className="w-24 h-24 text-green-600 mb-4" />
          )}
          <p className="text-xl font-medium text-gray-700 text-center break-all px-4">{file.name}</p>
          <p className="text-sm font-medium mt-2 uppercase tracking-wide">
             {file.type.includes('pdf') ? 'PDF Document' : 'Excel Spreadsheet'}
          </p>
       </div>
    );
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col items-center py-12 px-4 sm:px-6 lg:px-8 text-gray-800">
      <div className="max-w-4xl w-full space-y-6">

        {/* Header */}
        <div className="text-center">
          <div className="mx-auto h-16 w-16 bg-blue-100 rounded-full flex items-center justify-center mb-4">
            <FileSpreadsheet className="h-8 w-8 text-blue-600" />
          </div>
          <h1 className="text-3xl font-bold text-gray-900 tracking-tight">Score Calculator</h1>
          <p className="mt-2 text-lg text-gray-600">
            Upload an Image, PDF, or Excel file of the column counts.
          </p>
        </div>

        {/* Settings */}
        <div className="bg-white shadow-md rounded-xl overflow-hidden border border-gray-100">
          <div 
            className="px-6 py-4 bg-gray-50 border-b border-gray-200 flex items-center justify-between cursor-pointer"
            onClick={() => setShowSettings(!showSettings)}
          >
            <div className="flex items-center gap-2 font-medium text-gray-700">
              <Settings className="w-5 h-5" />
              <span>Settings</span>
            </div>
            <span className="text-sm text-blue-600 hover:text-blue-800">
              {showSettings ? 'Hide' : 'Show'}
            </span>
          </div>

          {showSettings && (
            <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
               {/* Standard Names */}
               <div>
                   <div className="mb-2 text-sm text-gray-700 font-semibold flex items-center gap-2">
                     <Users className="w-4 h-4" />
                     Standard Name List (Required)
                   </div>
                   <textarea
                     value={referenceNames}
                     onChange={(e) => setReferenceNames(e.target.value)}
                     className="w-full h-48 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm font-mono"
                   />
               </div>

               {/* Co-teaching Groups */}
               <div>
                   <div className="mb-2 text-sm text-gray-700 font-semibold flex items-center gap-2">
                     <Info className="w-4 h-4" />
                     Co-teaching Groups
                   </div>
                   <div className="mb-2 text-xs text-gray-500">
                     One group per line, comma separated.<br/>
                     Example: <code>Sherry, Linna</code>
                   </div>
                   <textarea
                     value={coTeachingNames}
                     onChange={(e) => setCoTeachingNames(e.target.value)}
                     className="w-full h-48 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm font-mono"
                   />
               </div>
            </div>
          )}
        </div>

        {/* Scoring Legend */}
        <div className="bg-blue-50 border border-blue-200 rounded-xl p-4 flex items-start gap-3">
            <HelpCircle className="w-5 h-5 text-blue-600 shrink-0 mt-0.5" />
            <div>
                <h3 className="text-sm font-semibold text-blue-900">Scoring Rules</h3>
                <div className="mt-1 flex flex-wrap gap-4 text-sm text-blue-800">
                    <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-gray-400"></span> Count ≤ 10: <b>0 pts</b></span>
                    <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-blue-400"></span> 11-20: <b>1 pt</b></span>
                    <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-blue-600"></span> 21-35: <b>3 pts</b></span>
                    <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-green-500"></span> > 35: <b>5 pts</b></span>
                </div>
            </div>
        </div>

        {/* Main Area */}
        <div className="bg-white shadow-xl rounded-2xl overflow-hidden border border-gray-100">
          {!file ? (
            <div 
              className="p-12 border-2 border-dashed border-gray-300 rounded-xl m-6 flex flex-col items-center justify-center hover:border-blue-500 hover:bg-blue-50 cursor-pointer"
              onDragOver={handleDragOver}
              onDrop={handleDrop}
              onClick={() => fileInputRef.current?.click()}
            >
              <Upload className="h-8 w-8 text-gray-500 mb-4" />
              <p className="text-lg font-medium text-gray-700">Upload Image, PDF or Excel (Ctrl+V)</p>
              <p className="text-sm text-gray-500 mt-2">Supports .png, .jpg, .pdf, .xlsx</p>
              <input type="file" ref={fileInputRef} className="hidden" accept="image/*,.pdf,.xlsx,.xls,application/pdf,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel" onChange={handleFileSelect} />
            </div>
          ) : (
            <div className="flex flex-col md:flex-row h-full min-h-[400px]">
              {/* Preview */}
              <div className="w-full md:w-1/2 bg-gray-100 p-6 flex flex-col items-center justify-center relative">
                {renderPreview()}

                <button onClick={clearFile} className="absolute top-4 right-4 p-2 bg-white rounded-full shadow hover:text-red-500">
                  <X className="h-5 w-5" />
                </button>
              </div>

              {/* Actions/Results */}
              <div className="w-full md:w-1/2 p-6 flex flex-col">
                {!extractedData && !isAnalyzing && !error && (
                  <div className="flex-1 flex flex-col items-center justify-center space-y-6">
                    <button onClick={analyzeData} className="w-full max-w-xs bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-6 rounded-lg shadow-md flex items-center justify-center gap-2">
                      <FileSpreadsheet className="w-5 h-5" />
                      Calculate Scores
                    </button>
                  </div>
                )}

                {isAnalyzing && (
                  <div className="flex-1 flex flex-col items-center justify-center text-center space-y-4">
                    <Loader2 className="h-10 w-10 text-blue-600 animate-spin" />
                    <p className="text-gray-500">Processing entire document...</p>
                  </div>
                )}

                {error && (
                  <div className="flex-1 flex flex-col items-center justify-center text-center space-y-4">
                    <p className="text-red-600">{error}</p>
                    <button onClick={analyzeData} className="underline text-gray-600">Try Again</button>
                  </div>
                )}

                {extractedData && (
                  <div className="flex flex-col h-full w-full">
                    <div className="flex justify-between items-center mb-4">
                        <span className="text-green-700 font-medium flex items-center gap-2"><CheckCircle className="w-5 h-5"/> Done</span>
                        <div className="flex gap-2">
                             {unmatchedRows.length > 0 && (
                                <button 
                                    onClick={() => setShowUnmatched(!showUnmatched)}
                                    className={`text-xs px-2 py-1 rounded flex items-center gap-1 ${showUnmatched ? 'bg-orange-100 text-orange-700' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
                                >
                                    {showUnmatched ? <EyeOff className="w-3 h-3"/> : <Eye className="w-3 h-3"/>}
                                    {unmatchedRows.length} Unmatched
                                </button>
                             )}
                            <span className="text-xs bg-gray-100 px-2 py-1 rounded">{extractedData.filter(r => r["Raw Count"] > 0).length} matched</span>
                        </div>
                    </div>

                    {/* Unmatched Rows Warning */}
                    {showUnmatched && unmatchedRows.length > 0 && (
                        <div className="mb-4 bg-orange-50 border border-orange-200 rounded-lg p-3 text-xs overflow-auto max-h-[150px]">
                            <h4 className="font-semibold text-orange-800 mb-2">Data found but not in Standard List:</h4>
                            <table className="w-full text-left text-orange-900">
                                <thead>
                                    <tr>
                                        <th className="pb-1">Teacher Found</th>
                                        <th className="pb-1">Count</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {unmatchedRows.map((r, i) => (
                                        <tr key={i} className="border-t border-orange-100">
                                            <td className="py-1 pr-2">{r.teacher}</td>
                                            <td className="py-1">{r.count}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                            <p className="mt-2 text-orange-600 italic">Check if names in "Settings" match these exact spellings.</p>
                        </div>
                    )}

                    <div className="flex-1 overflow-auto border rounded-lg mb-4 bg-gray-50 scrollbar-hide max-h-[300px]">
                      <table className="min-w-full divide-y divide-gray-200 text-sm">
                        <thead className="bg-gray-100 sticky top-0">
                          <tr>
                            <th className="px-3 py-2 text-left text-gray-500">Name</th>
                            <th className="px-3 py-2 text-center text-gray-500">Raw</th>
                            <th className="px-3 py-2 text-center text-gray-500">Adj</th>
                            <th className="px-3 py-2 text-center text-gray-500">Score</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-200 bg-white">
                          {extractedData.map((row, idx) => (
                            <tr key={idx} className={row["Raw Count"] === 0 ? "opacity-50" : ""}>
                              <td className="px-3 py-2 whitespace-nowrap font-medium">{row['姓名']}</td>
                              <td className="px-3 py-2 text-center text-gray-400">{row['Raw Count']}</td>
                              <td className="px-3 py-2 text-center text-blue-600 font-medium group relative cursor-help">
                                {row['Adjusted Count']}
                                {row['Halved Subjects'] && (
                                  <div className="hidden group-hover:block absolute bottom-full left-1/2 -translate-x-1/2 mb-2 p-2 bg-gray-800 text-white text-xs rounded shadow-lg whitespace-normal min-w-[150px] z-10">
                                    Halved: {row['Halved Subjects']}
                                  </div>
                                )}
                              </td>
                              <td className={`px-3 py-2 text-center font-bold ${row['分数'] >= 5 ? 'text-green-600' : row['分数'] >= 3 ? 'text-blue-600' : 'text-gray-500'}`}>{row['分数']}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                    <button onClick={downloadExcel} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-6 rounded-lg shadow-md flex items-center justify-center gap-2">
                      <Download className="w-5 h-5" /> Download Excel
                    </button>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI } from "@google/genai";
import * as XLSX from 'https://esm.sh/xlsx';
import { Upload, FileSpreadsheet, Loader2, CheckCircle, AlertCircle, X, Download, Image as ImageIcon, Settings, Info, Users, HelpCircle, Eye, EyeOff, FileText } from 'lucide-react';

// Interfaces for type safety
interface RawRow {
  teacher: string;
  code: string;
  count: number;
  matchedStandardName?: string | null;
  normalizedCode?: string;
}

interface ProcessedRow {
  "姓名": string;
  "Raw Count": number;
  "Adjusted Count": number;
  "分数": number;
  "Halved Subjects": string;
}

const App = () => {
  const [file, setFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null); // Base64 data for API (Image/PDF)
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [extractedData, setExtractedData] = useState<ProcessedRow[] | null>(null);
  const [unmatchedRows, setUnmatchedRows] = useState<RawRow[]>([]);
  const [showUnmatched, setShowUnmatched] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [referenceNames, setReferenceNames] = useState<string>(`杨晶晶 Jenny
徐育梅 Catherine
储晓栋 Amy
孟雅 Alice
陈蓉 Lotus
谢淑平 Sherry
郭晶晶 Joy
李臣亚 Linna
杨阳Sunny Yang
詹和太James
曹阳Bill
任艳 Rebecca
王芸 Yun
樊澄 Claire
孟远 Krystal
谭颖Tenny
刘鹏宇Dean
张月明 Jasmine
徐晓娜 Elina
赵茹怡Daicen
金辰昊Colin
张金慧 Emily
冯灿Sunny Feng
李雪维 Nicole
张国靖 Alicia
秦笑Sophie
刘家玮Jane
施璎真Serena
丁佐伊Zoe
宋吉 Merissa
王楚怡phyllis
周筱妍Ollie
张颖 Yvonne
李苏粤Sibyl
许明月 Luna
季远兰 Mandy
吴飞Fiona（英语）
孙胜蓝 Sierra（英语）
汪苇 Winnie`);
  const [coTeachingNames, setCoTeachingNames] = useState<string>(`李苏粤Sibyl, Noku
谢淑平 Sherry, 李臣亚 Linna
冯灿Sunny Feng,张金慧 Emily
秦笑Sophie, Superman
陈蓉 Lotus, Callum`);
  const [showSettings, setShowSettings] = useState(true);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const processFile = useCallback((selectedFile: File) => {
    // Validate file type (Image OR Excel OR PDF)
    const isImage = selectedFile.type.startsWith('image/');
    const isPdf = selectedFile.type === 'application/pdf';
    const isExcel = selectedFile.type === 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' || 
                    selectedFile.type === 'application/vnd.ms-excel' ||
                    selectedFile.name.endsWith('.xlsx') || 
                    selectedFile.name.endsWith('.xls');

    if (!isImage && !isExcel && !isPdf) {
      setError('Please select a valid Image (PNG, JPG), PDF, or Excel file.');
      return;
    }

    setFile(selectedFile);
    setError(null);
    setExtractedData(null);
    setUnmatchedRows([]);
    setPreviewUrl(null);

    // Read file for preview/API (Images and PDFs need base64)
    if (isImage || isPdf) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setPreviewUrl(e.target?.result as string);
      };
      reader.readAsDataURL(selectedFile);
    } 
    // Excel files are read using ArrayBuffer in analyzeData
  }, []);

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      processFile(e.target.files[0]);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      processFile(e.dataTransfer.files[0]);
    }
  };

  // Add Paste Event Listener
  useEffect(() => {
    const handlePaste = (e: ClipboardEvent) => {
      if (e.clipboardData && e.clipboardData.items) {
        for (let i = 0; i < e.clipboardData.items.length; i++) {
          const item = e.clipboardData.items[i];
          if (item.type.indexOf('image') !== -1) {
            const blob = item.getAsFile();
            if (blob) {
              processFile(blob);
              e.preventDefault();
              break;
            }
          }
        }
      }
    };

    document.addEventListener('paste', handlePaste);
    return () => {
      document.removeEventListener('paste', handlePaste);
    };
  }, [processFile]);

  const clearFile = () => {
    setFile(null);
    setPreviewUrl(null);
    setExtractedData(null);
    setUnmatchedRows([]);
    setError(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const calculateScore = (count: number) => {
    if (count <= 10) return 0;
    if (count <= 20) return 1;
    if (count <= 35) return 3;
    return 5;
  };

  // Helper to normalize subject codes (remove spaces, uppercase)
  const normalizeCode = (code: string) => {
    if (!code) return "";
    return code.replace(/\s+/g, '').toUpperCase();
  };

  // Helper to extract searchable keywords from a standard name line
  const getKeywords = (standardNameLine: string) => {
    const parts = standardNameLine.match(/[\u4e00-\u9fa5]+|[a-zA-Z]+/g);
    return parts ? parts.map(p => p.toLowerCase()) : [];
  };

  const analyzeData = async () => {
    if (!file) return;

    setIsAnalyzing(true);
    setError(null);
    setUnmatchedRows([]);

    try {
      let rawRows: RawRow[] = [];

      // BRANCH 1: AI PROCESSING (IMAGE OR PDF)
      if ((file.type.startsWith('image/') || file.type === 'application/pdf') && previewUrl) {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const base64Data = previewUrl.split(',')[1];

        // Prompt optimization for full data extraction
        let prompt = `
          Analyze this ${file.type === 'application/pdf' ? 'PDF document' : 'image'} containing a table.
          The document may contain multiple pages or long lists. You MUST extract data from ALL pages/sections.

          Columns usually are: "Teacher Name", "Subject Name", "Subject Code", "Number of Columns" (Count).

          Task:
          1. Extract EVERY SINGLE data row. Do NOT summarize. Do NOT truncate. 
          2. Exclude "Total" rows.
          3. Handle Merged Cells: If "Teacher Name" is empty/merged, assume it is the same as the row above it.

          Return a JSON array of objects:
          [
            { "teacher": "Exact string from doc", "code": "Subject Code", "count": 123 },
            ...
          ]

          Output valid JSON only. Ensure you output the COMPLETE list.
        `;

        const response = await ai.models.generateContent({
          model: 'gemini-2.5-flash',
          contents: {
            parts: [
              {
                inlineData: {
                  mimeType: file.type,
                  data: base64Data
                }
              },
              { text: prompt }
            ]
          },
          config: {
            responseMimeType: "application/json"
          }
        });

        const responseText = response.text;
        if (!responseText) throw new Error("No data returned from model.");

        try {
          const parsed = JSON.parse(responseText);
          if (Array.isArray(parsed)) {
              rawRows = parsed;
          } else if (typeof parsed === 'object') {
              const key = Object.keys(parsed).find(k => Array.isArray(parsed[k]));
              if (key) rawRows = parsed[key];
          }
        } catch (e) {
            throw new Error("Failed to parse AI response. " + responseText.substring(0, 100));
        }
      } 
      // BRANCH 2: EXCEL PROCESSING (LOCAL)
      else {
        const arrayBuffer = await file.arrayBuffer();
        const workbook = XLSX.read(arrayBuffer);
        const firstSheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[firstSheetName];

        const jsonData = XLSX.utils.sheet_to_json(worksheet, { defval: "" });

        let lastTeacher = "";

        rawRows = jsonData.map((row: any) => {
            const teacherKey = Object.keys(row).find(k => k.toLowerCase().includes('teacher') || k.toLowerCase().includes('name') || k.includes('姓名'));
            const codeKey = Object.keys(row).find(k => k.toLowerCase().includes('code') || k.includes('代码'));
            const countKey = Object.keys(row).find(k => k.toLowerCase().includes('column') || k.toLowerCase().includes('count') || k.includes('节数') || k.includes('数量'));

            let teacher = teacherKey ? String(row[teacherKey]).trim() : "";
            let code = codeKey ? String(row[codeKey]).trim() : "";
            let countStr = countKey ? String(row[countKey]) : "0";
            let count = parseFloat(countStr) || 0;

            if (!teacher && lastTeacher) {
                teacher = lastTeacher;
            } else if (teacher) {
                lastTeacher = teacher;
            }

            return {
                teacher: teacher,
                code: code,
                count: count
            };
        }).filter(r => {
            if (!r.teacher || r.teacher.toLowerCase().includes('total')) return false;
            if (r.count <= 0) return false;
            return true;
        });
      }

      // --- Client-Side Matching Algorithm ---

      // 1. Prepare Standard Names
      const stdNamesList = referenceNames.split('\n').map(n => n.trim()).filter(n => n);
      const stdNameMatchers = stdNamesList.map(name => ({
          fullName: name,
          keywords: getKeywords(name)
      }));

      // 2. Match Rows
      const matchedRows: RawRow[] = rawRows.map(row => {
          const rawTeacher = (row.teacher || "").toLowerCase();

          const match = stdNameMatchers.find(matcher => {
              return matcher.keywords.some(keyword => {
                  if (keyword.length < 2) return false; 
                  return rawTeacher.includes(keyword);
              });
          });

          return {
              ...row,
              matchedStandardName: match ? match.fullName : null,
              normalizedCode: normalizeCode(row.code)
          };
      });

      setUnmatchedRows(matchedRows.filter(r => !r.matchedStandardName));

      // 3. Co-teaching Logic
      const rowsToHalve = new Set<RawRow>();
      const halvedCodesMap = new Map<string, Set<string>>();

      const coTeachingGroups = coTeachingNames
        .split('\n')
        .map(line => line.split(/,|，/).map(n => n.trim().toLowerCase()).filter(n => n))
        .filter(group => group.length > 0);

      coTeachingGroups.forEach(groupKeywords => {
         const groupRows = matchedRows.filter(row => {
             const standard = (row.matchedStandardName || "").toLowerCase();
             const raw = (row.teacher || "").toLowerCase();
             return groupKeywords.some(k => standard.includes(k) || raw.includes(k));
         });

         const codeMap = new Map<string, typeof matchedRows>();
         groupRows.forEach(row => {
             if (!row.normalizedCode) return;
             if (!codeMap.has(row.normalizedCode)) codeMap.set(row.normalizedCode, []);
             codeMap.get(row.normalizedCode)?.push(row);
         });

         codeMap.forEach((rowsInCode, code) => {
             const uniqueTeachers = new Set(rowsInCode.map(r => r.matchedStandardName || r.teacher));
             if (uniqueTeachers.size > 1) {
                 rowsInCode.forEach(r => {
                     rowsToHalve.add(r);
                     const ownerName = r.matchedStandardName;
                     if (ownerName) {
                         if (!halvedCodesMap.has(ownerName)) halvedCodesMap.set(ownerName, new Set());
                         halvedCodesMap.get(ownerName)?.add(code);
                     }
                 });
             }
         });
      });

      // 4. Aggregation
      const results: ProcessedRow[] = stdNamesList.map(stdName => {
          const teacherRows = matchedRows.filter(r => r.matchedStandardName === stdName);

          let rawTotal = 0;
          let adjustedTotal = 0;

          teacherRows.forEach(r => {
              const val = Number(r.count) || 0;
              rawTotal += val;

              if (rowsToHalve.has(r)) {
                  adjustedTotal += val / 2;
              } else {
                  adjustedTotal += val;
              }
          });

          const halvedSubjects = Array.from(halvedCodesMap.get(stdName) || []).join(', ');

          return {
              "姓名": stdName,
              "Raw Count": rawTotal,
              "Adjusted Count": adjustedTotal,
              "分数": calculateScore(adjustedTotal),
              "Halved Subjects": halvedSubjects
          };
      });

      setExtractedData(results);

    } catch (err) {
      console.error(err);
      setError("Failed to process. " + (err as Error).message);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const downloadExcel = () => {
    if (!extractedData || extractedData.length === 0) return;

    const ws = XLSX.utils.json_to_sheet(extractedData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Scores");

    ws['!cols'] = [
        { wch: 20 }, 
        { wch: 10 }, 
        { wch: 15 }, 
        { wch: 10 }, 
        { wch: 30 }
    ];
    XLSX.writeFile(wb, "class_scores.xlsx");
  };

  // Helper to determine preview content
  const renderPreview = () => {
    if (!file) return null;

    // Image Preview
    if (file.type.startsWith('image/') && previewUrl) {
        return <img src={previewUrl} alt="Preview" className="max-h-[400px] w-auto object-contain rounded-lg shadow-sm" />;
    }

    // PDF or Excel Icon Preview
    return (
       <div className="flex flex-col items-center justify-center text-gray-500">
          {file.type.includes('pdf') ? (
              <FileText className="w-24 h-24 text-red-600 mb-4" />
          ) : (
              <FileSpreadsheet className="w-24 h-24 text-green-600 mb-4" />
          )}
          <p className="text-xl font-medium text-gray-700 text-center break-all px-4">{file.name}</p>
          <p className="text-sm font-medium mt-2 uppercase tracking-wide">
             {file.type.includes('pdf') ? 'PDF Document' : 'Excel Spreadsheet'}
          </p>
       </div>
    );
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col items-center py-12 px-4 sm:px-6 lg:px-8 text-gray-800">
      <div className="max-w-4xl w-full space-y-6">

        {/* Header */}
        <div className="text-center">
          <div className="mx-auto h-16 w-16 bg-blue-100 rounded-full flex items-center justify-center mb-4">
            <FileSpreadsheet className="h-8 w-8 text-blue-600" />
          </div>
          <h1 className="text-3xl font-bold text-gray-900 tracking-tight">Score Calculator</h1>
          <p className="mt-2 text-lg text-gray-600">
            Upload an Image, PDF, or Excel file of the column counts.
          </p>
        </div>

        {/* Settings */}
        <div className="bg-white shadow-md rounded-xl overflow-hidden border border-gray-100">
          <div 
            className="px-6 py-4 bg-gray-50 border-b border-gray-200 flex items-center justify-between cursor-pointer"
            onClick={() => setShowSettings(!showSettings)}
          >
            <div className="flex items-center gap-2 font-medium text-gray-700">
              <Settings className="w-5 h-5" />
              <span>Settings</span>
            </div>
            <span className="text-sm text-blue-600 hover:text-blue-800">
              {showSettings ? 'Hide' : 'Show'}
            </span>
          </div>

          {showSettings && (
            <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
               {/* Standard Names */}
               <div>
                   <div className="mb-2 text-sm text-gray-700 font-semibold flex items-center gap-2">
                     <Users className="w-4 h-4" />
                     Standard Name List (Required)
                   </div>
                   <textarea
                     value={referenceNames}
                     onChange={(e) => setReferenceNames(e.target.value)}
                     className="w-full h-48 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm font-mono"
                   />
               </div>

               {/* Co-teaching Groups */}
               <div>
                   <div className="mb-2 text-sm text-gray-700 font-semibold flex items-center gap-2">
                     <Info className="w-4 h-4" />
                     Co-teaching Groups
                   </div>
                   <div className="mb-2 text-xs text-gray-500">
                     One group per line, comma separated.<br/>
                     Example: <code>Sherry, Linna</code>
                   </div>
                   <textarea
                     value={coTeachingNames}
                     onChange={(e) => setCoTeachingNames(e.target.value)}
                     className="w-full h-48 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm font-mono"
                   />
               </div>
            </div>
          )}
        </div>

        {/* Scoring Legend */}
        <div className="bg-blue-50 border border-blue-200 rounded-xl p-4 flex items-start gap-3">
            <HelpCircle className="w-5 h-5 text-blue-600 shrink-0 mt-0.5" />
            <div>
                <h3 className="text-sm font-semibold text-blue-900">Scoring Rules</h3>
                <div className="mt-1 flex flex-wrap gap-4 text-sm text-blue-800">
                    <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-gray-400"></span> Count ≤ 10: <b>0 pts</b></span>
                    <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-blue-400"></span> 11-20: <b>1 pt</b></span>
                    <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-blue-600"></span> 21-35: <b>3 pts</b></span>
                    <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-green-500"></span> > 35: <b>5 pts</b></span>
                </div>
            </div>
        </div>

        {/* Main Area */}
        <div className="bg-white shadow-xl rounded-2xl overflow-hidden border border-gray-100">
          {!file ? (
            <div 
              className="p-12 border-2 border-dashed border-gray-300 rounded-xl m-6 flex flex-col items-center justify-center hover:border-blue-500 hover:bg-blue-50 cursor-pointer"
              onDragOver={handleDragOver}
              onDrop={handleDrop}
              onClick={() => fileInputRef.current?.click()}
            >
              <Upload className="h-8 w-8 text-gray-500 mb-4" />
              <p className="text-lg font-medium text-gray-700">Upload Image, PDF or Excel (Ctrl+V)</p>
              <p className="text-sm text-gray-500 mt-2">Supports .png, .jpg, .pdf, .xlsx</p>
              <input type="file" ref={fileInputRef} className="hidden" accept="image/*,.pdf,.xlsx,.xls,application/pdf,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel" onChange={handleFileSelect} />
            </div>
          ) : (
            <div className="flex flex-col md:flex-row h-full min-h-[400px]">
              {/* Preview */}
              <div className="w-full md:w-1/2 bg-gray-100 p-6 flex flex-col items-center justify-center relative">
                {renderPreview()}

                <button onClick={clearFile} className="absolute top-4 right-4 p-2 bg-white rounded-full shadow hover:text-red-500">
                  <X className="h-5 w-5" />
                </button>
              </div>

              {/* Actions/Results */}
              <div className="w-full md:w-1/2 p-6 flex flex-col">
                {!extractedData && !isAnalyzing && !error && (
                  <div className="flex-1 flex flex-col items-center justify-center space-y-6">
                    <button onClick={analyzeData} className="w-full max-w-xs bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-6 rounded-lg shadow-md flex items-center justify-center gap-2">
                      <FileSpreadsheet className="w-5 h-5" />
                      Calculate Scores
                    </button>
                  </div>
                )}

                {isAnalyzing && (
                  <div className="flex-1 flex flex-col items-center justify-center text-center space-y-4">
                    <Loader2 className="h-10 w-10 text-blue-600 animate-spin" />
                    <p className="text-gray-500">Processing entire document...</p>
                  </div>
                )}

                {error && (
                  <div className="flex-1 flex flex-col items-center justify-center text-center space-y-4">
                    <p className="text-red-600">{error}</p>
                    <button onClick={analyzeData} className="underline text-gray-600">Try Again</button>
                  </div>
                )}

                {extractedData && (
                  <div className="flex flex-col h-full w-full">
                    <div className="flex justify-between items-center mb-4">
                        <span className="text-green-700 font-medium flex items-center gap-2"><CheckCircle className="w-5 h-5"/> Done</span>
                        <div className="flex gap-2">
                             {unmatchedRows.length > 0 && (
                                <button 
                                    onClick={() => setShowUnmatched(!showUnmatched)}
                                    className={`text-xs px-2 py-1 rounded flex items-center gap-1 ${showUnmatched ? 'bg-orange-100 text-orange-700' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
                                >
                                    {showUnmatched ? <EyeOff className="w-3 h-3"/> : <Eye className="w-3 h-3"/>}
                                    {unmatchedRows.length} Unmatched
                                </button>
                             )}
                            <span className="text-xs bg-gray-100 px-2 py-1 rounded">{extractedData.filter(r => r["Raw Count"] > 0).length} matched</span>
                        </div>
                    </div>

                    {/* Unmatched Rows Warning */}
                    {showUnmatched && unmatchedRows.length > 0 && (
                        <div className="mb-4 bg-orange-50 border border-orange-200 rounded-lg p-3 text-xs overflow-auto max-h-[150px]">
                            <h4 className="font-semibold text-orange-800 mb-2">Data found but not in Standard List:</h4>
                            <table className="w-full text-left text-orange-900">
                                <thead>
                                    <tr>
                                        <th className="pb-1">Teacher Found</th>
                                        <th className="pb-1">Count</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {unmatchedRows.map((r, i) => (
                                        <tr key={i} className="border-t border-orange-100">
                                            <td className="py-1 pr-2">{r.teacher}</td>
                                            <td className="py-1">{r.count}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                            <p className="mt-2 text-orange-600 italic">Check if names in "Settings" match these exact spellings.</p>
                        </div>
                    )}

                    <div className="flex-1 overflow-auto border rounded-lg mb-4 bg-gray-50 scrollbar-hide max-h-[300px]">
                      <table className="min-w-full divide-y divide-gray-200 text-sm">
                        <thead className="bg-gray-100 sticky top-0">
                          <tr>
                            <th className="px-3 py-2 text-left text-gray-500">Name</th>
                            <th className="px-3 py-2 text-center text-gray-500">Raw</th>
                            <th className="px-3 py-2 text-center text-gray-500">Adj</th>
                            <th className="px-3 py-2 text-center text-gray-500">Score</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-200 bg-white">
                          {extractedData.map((row, idx) => (
                            <tr key={idx} className={row["Raw Count"] === 0 ? "opacity-50" : ""}>
                              <td className="px-3 py-2 whitespace-nowrap font-medium">{row['姓名']}</td>
                              <td className="px-3 py-2 text-center text-gray-400">{row['Raw Count']}</td>
                              <td className="px-3 py-2 text-center text-blue-600 font-medium group relative cursor-help">
                                {row['Adjusted Count']}
                                {row['Halved Subjects'] && (
                                  <div className="hidden group-hover:block absolute bottom-full left-1/2 -translate-x-1/2 mb-2 p-2 bg-gray-800 text-white text-xs rounded shadow-lg whitespace-normal min-w-[150px] z-10">
                                    Halved: {row['Halved Subjects']}
                                  </div>
                                )}
                              </td>
                              <td className={`px-3 py-2 text-center font-bold ${row['分数'] >= 5 ? 'text-green-600' : row['分数'] >= 3 ? 'text-blue-600' : 'text-gray-500'}`}>{row['分数']}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                    <button onClick={downloadExcel} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-6 rounded-lg shadow-md flex items-center justify-center gap-2">
                      <Download className="w-5 h-5" /> Download Excel
                    </button>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI } from "@google/genai";
import * as XLSX from 'https://esm.sh/xlsx';
import { Upload, FileSpreadsheet, Loader2, CheckCircle, AlertCircle, X, Download, Image as ImageIcon, Settings, Info, Users, HelpCircle, Eye, EyeOff, FileText } from 'lucide-react';

// Interfaces for type safety
interface RawRow {
  teacher: string;
  code: string;
  count: number;
  matchedStandardName?: string | null;
  normalizedCode?: string;
}

interface ProcessedRow {
  "姓名": string;
  "Raw Count": number;
  "Adjusted Count": number;
  "分数": number;
  "Halved Subjects": string;
}

const App = () => {
  const [file, setFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null); // Base64 data for API (Image/PDF)
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [extractedData, setExtractedData] = useState<ProcessedRow[] | null>(null);
  const [unmatchedRows, setUnmatchedRows] = useState<RawRow[]>([]);
  const [showUnmatched, setShowUnmatched] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [referenceNames, setReferenceNames] = useState<string>(`杨晶晶 Jenny
徐育梅 Catherine
储晓栋 Amy
孟雅 Alice
陈蓉 Lotus
谢淑平 Sherry
郭晶晶 Joy
李臣亚 Linna
杨阳Sunny Yang
詹和太James
曹阳Bill
任艳 Rebecca
王芸 Yun
樊澄 Claire
孟远 Krystal
谭颖Tenny
刘鹏宇Dean
张月明 Jasmine
徐晓娜 Elina
赵茹怡Daicen
金辰昊Colin
张金慧 Emily
冯灿Sunny Feng
李雪维 Nicole
张国靖 Alicia
秦笑Sophie
刘家玮Jane
施璎真Serena
丁佐伊Zoe
宋吉 Merissa
王楚怡phyllis
周筱妍Ollie
张颖 Yvonne
李苏粤Sibyl
许明月 Luna
季远兰 Mandy
吴飞Fiona（英语）
孙胜蓝 Sierra（英语）
汪苇 Winnie`);
  const [coTeachingNames, setCoTeachingNames] = useState<string>(`李苏粤Sibyl, Noku
谢淑平 Sherry, 李臣亚 Linna
冯灿Sunny Feng,张金慧 Emily
秦笑Sophie, Superman
陈蓉 Lotus, Callum`);
  const [showSettings, setShowSettings] = useState(true);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const processFile = useCallback((selectedFile: File) => {
    // Validate file type (Image OR Excel OR PDF)
    const isImage = selectedFile.type.startsWith('image/');
    const isPdf = selectedFile.type === 'application/pdf';
    const isExcel = selectedFile.type === 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' || 
                    selectedFile.type === 'application/vnd.ms-excel' ||
                    selectedFile.name.endsWith('.xlsx') || 
                    selectedFile.name.endsWith('.xls');

    if (!isImage && !isExcel && !isPdf) {
      setError('Please select a valid Image (PNG, JPG), PDF, or Excel file.');
      return;
    }

    setFile(selectedFile);
    setError(null);
    setExtractedData(null);
    setUnmatchedRows([]);
    setPreviewUrl(null);

    // Read file for preview/API (Images and PDFs need base64)
    if (isImage || isPdf) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setPreviewUrl(e.target?.result as string);
      };
      reader.readAsDataURL(selectedFile);
    } 
    // Excel files are read using ArrayBuffer in analyzeData
  }, []);

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      processFile(e.target.files[0]);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      processFile(e.dataTransfer.files[0]);
    }
  };

  // Add Paste Event Listener
  useEffect(() => {
    const handlePaste = (e: ClipboardEvent) => {
      if (e.clipboardData && e.clipboardData.items) {
        for (let i = 0; i < e.clipboardData.items.length; i++) {
          const item = e.clipboardData.items[i];
          if (item.type.indexOf('image') !== -1) {
            const blob = item.getAsFile();
            if (blob) {
              processFile(blob);
              e.preventDefault();
              break;
            }
          }
        }
      }
    };

    document.addEventListener('paste', handlePaste);
    return () => {
      document.removeEventListener('paste', handlePaste);
    };
  }, [processFile]);

  const clearFile = () => {
    setFile(null);
    setPreviewUrl(null);
    setExtractedData(null);
    setUnmatchedRows([]);
    setError(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const calculateScore = (count: number) => {
    if (count <= 10) return 0;
    if (count <= 20) return 1;
    if (count <= 35) return 3;
    return 5;
  };

  // Helper to normalize subject codes (remove spaces, uppercase)
  const normalizeCode = (code: string) => {
    if (!code) return "";
    return code.replace(/\s+/g, '').toUpperCase();
  };

  // Helper to extract searchable keywords from a standard name line
  const getKeywords = (standardNameLine: string) => {
    const parts = standardNameLine.match(/[\u4e00-\u9fa5]+|[a-zA-Z]+/g);
    return parts ? parts.map(p => p.toLowerCase()) : [];
  };

  const analyzeData = async () => {
    if (!file) return;

    setIsAnalyzing(true);
    setError(null);
    setUnmatchedRows([]);

    try {
      let rawRows: RawRow[] = [];

      // BRANCH 1: AI PROCESSING (IMAGE OR PDF)
      if ((file.type.startsWith('image/') || file.type === 'application/pdf') && previewUrl) {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const base64Data = previewUrl.split(',')[1];

        // Prompt optimization for full data extraction
        let prompt = `
          Analyze this ${file.type === 'application/pdf' ? 'PDF document' : 'image'} containing a table.
          The document may contain multiple pages or long lists. You MUST extract data from ALL pages/sections.

          Columns usually are: "Teacher Name", "Subject Name", "Subject Code", "Number of Columns" (Count).

          Task:
          1. Extract EVERY SINGLE data row. Do NOT summarize. Do NOT truncate. 
          2. Exclude "Total" rows.
          3. Handle Merged Cells: If "Teacher Name" is empty/merged, assume it is the same as the row above it.

          Return a JSON array of objects:
          [
            { "teacher": "Exact string from doc", "code": "Subject Code", "count": 123 },
            ...
          ]

          Output valid JSON only. Ensure you output the COMPLETE list.
        `;

        const response = await ai.models.generateContent({
          model: 'gemini-2.5-flash',
          contents: {
            parts: [
              {
                inlineData: {
                  mimeType: file.type,
                  data: base64Data
                }
              },
              { text: prompt }
            ]
          },
          config: {
            responseMimeType: "application/json"
          }
        });

        const responseText = response.text;
        if (!responseText) throw new Error("No data returned from model.");

        try {
          const parsed = JSON.parse(responseText);
          if (Array.isArray(parsed)) {
              rawRows = parsed;
          } else if (typeof parsed === 'object') {
              const key = Object.keys(parsed).find(k => Array.isArray(parsed[k]));
              if (key) rawRows = parsed[key];
          }
        } catch (e) {
            throw new Error("Failed to parse AI response. " + responseText.substring(0, 100));
        }
      } 
      // BRANCH 2: EXCEL PROCESSING (LOCAL)
      else {
        const arrayBuffer = await file.arrayBuffer();
        const workbook = XLSX.read(arrayBuffer);
        const firstSheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[firstSheetName];

        const jsonData = XLSX.utils.sheet_to_json(worksheet, { defval: "" });

        let lastTeacher = "";

        rawRows = jsonData.map((row: any) => {
            const teacherKey = Object.keys(row).find(k => k.toLowerCase().includes('teacher') || k.toLowerCase().includes('name') || k.includes('姓名'));
            const codeKey = Object.keys(row).find(k => k.toLowerCase().includes('code') || k.includes('代码'));
            const countKey = Object.keys(row).find(k => k.toLowerCase().includes('column') || k.toLowerCase().includes('count') || k.includes('节数') || k.includes('数量'));

            let teacher = teacherKey ? String(row[teacherKey]).trim() : "";
            let code = codeKey ? String(row[codeKey]).trim() : "";
            let countStr = countKey ? String(row[countKey]) : "0";
            let count = parseFloat(countStr) || 0;

            if (!teacher && lastTeacher) {
                teacher = lastTeacher;
            } else if (teacher) {
                lastTeacher = teacher;
            }

            return {
                teacher: teacher,
                code: code,
                count: count
            };
        }).filter(r => {
            if (!r.teacher || r.teacher.toLowerCase().includes('total')) return false;
            if (r.count <= 0) return false;
            return true;
        });
      }

      // --- Client-Side Matching Algorithm ---

      // 1. Prepare Standard Names
      const stdNamesList = referenceNames.split('\n').map(n => n.trim()).filter(n => n);
      const stdNameMatchers = stdNamesList.map(name => ({
          fullName: name,
          keywords: getKeywords(name)
      }));

      // 2. Match Rows - Updated to Best Match Strategy
      const matchedRows: RawRow[] = rawRows.map(row => {
          const rawTeacher = (row.teacher || "").toLowerCase();

          let bestMatch: { name: string, score: number } | null = null;

          stdNameMatchers.forEach(matcher => {
              let currentScore = 0;
              matcher.keywords.forEach(keyword => {
                  if (keyword.length < 2) return; // Skip very short keywords

                  if (rawTeacher.includes(keyword)) {
                       // High priority for Chinese characters (Unique ID)
                       if (/[\u4e00-\u9fa5]/.test(keyword)) {
                           currentScore += 50;
                       } else {
                           // Priority by length for English (e.g. "Sunny" = 5, "Feng" = 4)
                           // This helps distinguish "Sunny Feng" (Score 9) from "Sunny Yang" (Score 5) when input is "Sunny Feng"
                           currentScore += keyword.length;
                       }
                  }
              });

              // Update best match if score is higher
              if (currentScore > 0) {
                  if (!bestMatch || currentScore > bestMatch.score) {
                      bestMatch = { name: matcher.fullName, score: currentScore };
                  }
              }
          });

          return {
              ...row,
              matchedStandardName: bestMatch ? bestMatch.name : null,
              normalizedCode: normalizeCode(row.code)
          };
      });

      setUnmatchedRows(matchedRows.filter(r => !r.matchedStandardName));

      // 3. Co-teaching Logic
      const rowsToHalve = new Set<RawRow>();
      const halvedCodesMap = new Map<string, Set<string>>();

      const coTeachingGroups = coTeachingNames
        .split('\n')
        .map(line => line.split(/,|，/).map(n => n.trim().toLowerCase()).filter(n => n))
        .filter(group => group.length > 0);

      coTeachingGroups.forEach(groupKeywords => {
         const groupRows = matchedRows.filter(row => {
             const standard = (row.matchedStandardName || "").toLowerCase();
             const raw = (row.teacher || "").toLowerCase();
             return groupKeywords.some(k => standard.includes(k) || raw.includes(k));
         });

         const codeMap = new Map<string, typeof matchedRows>();
         groupRows.forEach(row => {
             if (!row.normalizedCode) return;
             if (!codeMap.has(row.normalizedCode)) codeMap.set(row.normalizedCode, []);
             codeMap.get(row.normalizedCode)?.push(row);
         });

         codeMap.forEach((rowsInCode, code) => {
             const uniqueTeachers = new Set(rowsInCode.map(r => r.matchedStandardName || r.teacher));
             if (uniqueTeachers.size > 1) {
                 rowsInCode.forEach(r => {
                     rowsToHalve.add(r);
                     const ownerName = r.matchedStandardName;
                     if (ownerName) {
                         if (!halvedCodesMap.has(ownerName)) halvedCodesMap.set(ownerName, new Set());
                         halvedCodesMap.get(ownerName)?.add(code);
                     }
                 });
             }
         });
      });

      // 4. Aggregation
      const results: ProcessedRow[] = stdNamesList.map(stdName => {
          const teacherRows = matchedRows.filter(r => r.matchedStandardName === stdName);

          let rawTotal = 0;
          let adjustedTotal = 0;

          teacherRows.forEach(r => {
              const val = Number(r.count) || 0;
              rawTotal += val;

              if (rowsToHalve.has(r)) {
                  adjustedTotal += val / 2;
              } else {
                  adjustedTotal += val;
              }
          });

          const halvedSubjects = Array.from(halvedCodesMap.get(stdName) || []).join(', ');

          return {
              "姓名": stdName,
              "Raw Count": rawTotal,
              "Adjusted Count": adjustedTotal,
              "分数": calculateScore(adjustedTotal),
              "Halved Subjects": halvedSubjects
          };
      });

      setExtractedData(results);

    } catch (err) {
      console.error(err);
      setError("Failed to process. " + (err as Error).message);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const downloadExcel = () => {
    if (!extractedData || extractedData.length === 0) return;

    const ws = XLSX.utils.json_to_sheet(extractedData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Scores");

    ws['!cols'] = [
        { wch: 20 }, 
        { wch: 10 }, 
        { wch: 15 }, 
        { wch: 10 }, 
        { wch: 30 }
    ];
    XLSX.writeFile(wb, "class_scores.xlsx");
  };

  // Helper to determine preview content
  const renderPreview = () => {
    if (!file) return null;

    // Image Preview
    if (file.type.startsWith('image/') && previewUrl) {
        return <img src={previewUrl} alt="Preview" className="max-h-[400px] w-auto object-contain rounded-lg shadow-sm" />;
    }

    // PDF or Excel Icon Preview
    return (
       <div className="flex flex-col items-center justify-center text-gray-500">
          {file.type.includes('pdf') ? (
              <FileText className="w-24 h-24 text-red-600 mb-4" />
          ) : (
              <FileSpreadsheet className="w-24 h-24 text-green-600 mb-4" />
          )}
          <p className="text-xl font-medium text-gray-700 text-center break-all px-4">{file.name}</p>
          <p className="text-sm font-medium mt-2 uppercase tracking-wide">
             {file.type.includes('pdf') ? 'PDF Document' : 'Excel Spreadsheet'}
          </p>
       </div>
    );
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col items-center py-12 px-4 sm:px-6 lg:px-8 text-gray-800">
      <div className="max-w-4xl w-full space-y-6">

        {/* Header */}
        <div className="text-center">
          <div className="mx-auto h-16 w-16 bg-blue-100 rounded-full flex items-center justify-center mb-4">
            <FileSpreadsheet className="h-8 w-8 text-blue-600" />
          </div>
          <h1 className="text-3xl font-bold text-gray-900 tracking-tight">Score Calculator</h1>
          <p className="mt-2 text-lg text-gray-600">
            Upload an Image, PDF, or Excel file of the column counts.
          </p>
        </div>

        {/* Settings */}
        <div className="bg-white shadow-md rounded-xl overflow-hidden border border-gray-100">
          <div 
            className="px-6 py-4 bg-gray-50 border-b border-gray-200 flex items-center justify-between cursor-pointer"
            onClick={() => setShowSettings(!showSettings)}
          >
            <div className="flex items-center gap-2 font-medium text-gray-700">
              <Settings className="w-5 h-5" />
              <span>Settings</span>
            </div>
            <span className="text-sm text-blue-600 hover:text-blue-800">
              {showSettings ? 'Hide' : 'Show'}
            </span>
          </div>

          {showSettings && (
            <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
               {/* Standard Names */}
               <div>
                   <div className="mb-2 text-sm text-gray-700 font-semibold flex items-center gap-2">
                     <Users className="w-4 h-4" />
                     Standard Name List (Required)
                   </div>
                   <textarea
                     value={referenceNames}
                     onChange={(e) => setReferenceNames(e.target.value)}
                     className="w-full h-48 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm font-mono"
                   />
               </div>

               {/* Co-teaching Groups */}
               <div>
                   <div className="mb-2 text-sm text-gray-700 font-semibold flex items-center gap-2">
                     <Info className="w-4 h-4" />
                     Co-teaching Groups
                   </div>
                   <div className="mb-2 text-xs text-gray-500">
                     One group per line, comma separated.<br/>
                     Example: <code>Sherry, Linna</code>
                   </div>
                   <textarea
                     value={coTeachingNames}
                     onChange={(e) => setCoTeachingNames(e.target.value)}
                     className="w-full h-48 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm font-mono"
                   />
               </div>
            </div>
          )}
        </div>

        {/* Scoring Legend */}
        <div className="bg-blue-50 border border-blue-200 rounded-xl p-4 flex items-start gap-3">
            <HelpCircle className="w-5 h-5 text-blue-600 shrink-0 mt-0.5" />
            <div>
                <h3 className="text-sm font-semibold text-blue-900">Scoring Rules</h3>
                <div className="mt-1 flex flex-wrap gap-4 text-sm text-blue-800">
                    <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-gray-400"></span> Count ≤ 10: <b>0 pts</b></span>
                    <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-blue-400"></span> 11-20: <b>1 pt</b></span>
                    <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-blue-600"></span> 21-35: <b>3 pts</b></span>
                    <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-green-500"></span> > 35: <b>5 pts</b></span>
                </div>
            </div>
        </div>

        {/* Main Area */}
        <div className="bg-white shadow-xl rounded-2xl overflow-hidden border border-gray-100">
          {!file ? (
            <div 
              className="p-12 border-2 border-dashed border-gray-300 rounded-xl m-6 flex flex-col items-center justify-center hover:border-blue-500 hover:bg-blue-50 cursor-pointer"
              onDragOver={handleDragOver}
              onDrop={handleDrop}
              onClick={() => fileInputRef.current?.click()}
            >
              <Upload className="h-8 w-8 text-gray-500 mb-4" />
              <p className="text-lg font-medium text-gray-700">Upload Image, PDF or Excel (Ctrl+V)</p>
              <p className="text-sm text-gray-500 mt-2">Supports .png, .jpg, .pdf, .xlsx</p>
              <input type="file" ref={fileInputRef} className="hidden" accept="image/*,.pdf,.xlsx,.xls,application/pdf,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel" onChange={handleFileSelect} />
            </div>
          ) : (
            <div className="flex flex-col md:flex-row h-full min-h-[400px]">
              {/* Preview */}
              <div className="w-full md:w-1/2 bg-gray-100 p-6 flex flex-col items-center justify-center relative">
                {renderPreview()}

                <button onClick={clearFile} className="absolute top-4 right-4 p-2 bg-white rounded-full shadow hover:text-red-500">
                  <X className="h-5 w-5" />
                </button>
              </div>

              {/* Actions/Results */}
              <div className="w-full md:w-1/2 p-6 flex flex-col">
                {!extractedData && !isAnalyzing && !error && (
                  <div className="flex-1 flex flex-col items-center justify-center space-y-6">
                    <button onClick={analyzeData} className="w-full max-w-xs bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-6 rounded-lg shadow-md flex items-center justify-center gap-2">
                      <FileSpreadsheet className="w-5 h-5" />
                      Calculate Scores
                    </button>
                  </div>
                )}

                {isAnalyzing && (
                  <div className="flex-1 flex flex-col items-center justify-center text-center space-y-4">
                    <Loader2 className="h-10 w-10 text-blue-600 animate-spin" />
                    <p className="text-gray-500">Processing entire document...</p>
                  </div>
                )}

                {error && (
                  <div className="flex-1 flex flex-col items-center justify-center text-center space-y-4">
                    <p className="text-red-600">{error}</p>
                    <button onClick={analyzeData} className="underline text-gray-600">Try Again</button>
                  </div>
                )}

                {extractedData && (
                  <div className="flex flex-col h-full w-full">
                    <div className="flex justify-between items-center mb-4">
                        <span className="text-green-700 font-medium flex items-center gap-2"><CheckCircle className="w-5 h-5"/> Done</span>
                        <div className="flex gap-2">
                             {unmatchedRows.length > 0 && (
                                <button 
                                    onClick={() => setShowUnmatched(!showUnmatched)}
                                    className={`text-xs px-2 py-1 rounded flex items-center gap-1 ${showUnmatched ? 'bg-orange-100 text-orange-700' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
                                >
                                    {showUnmatched ? <EyeOff className="w-3 h-3"/> : <Eye className="w-3 h-3"/>}
                                    {unmatchedRows.length} Unmatched
                                </button>
                             )}
                            <span className="text-xs bg-gray-100 px-2 py-1 rounded">{extractedData.filter(r => r["Raw Count"] > 0).length} matched</span>
                        </div>
                    </div>

                    {/* Unmatched Rows Warning */}
                    {showUnmatched && unmatchedRows.length > 0 && (
                        <div className="mb-4 bg-orange-50 border border-orange-200 rounded-lg p-3 text-xs overflow-auto max-h-[150px]">
                            <h4 className="font-semibold text-orange-800 mb-2">Data found but not in Standard List:</h4>
                            <table className="w-full text-left text-orange-900">
                                <thead>
                                    <tr>
                                        <th className="pb-1">Teacher Found</th>
                                        <th className="pb-1">Count</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {unmatchedRows.map((r, i) => (
                                        <tr key={i} className="border-t border-orange-100">
                                            <td className="py-1 pr-2">{r.teacher}</td>
                                            <td className="py-1">{r.count}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                            <p className="mt-2 text-orange-600 italic">Check if names in "Settings" match these exact spellings.</p>
                        </div>
                    )}

                    <div className="flex-1 overflow-auto border rounded-lg mb-4 bg-gray-50 scrollbar-hide max-h-[300px]">
                      <table className="min-w-full divide-y divide-gray-200 text-sm">
                        <thead className="bg-gray-100 sticky top-0">
                          <tr>
                            <th className="px-3 py-2 text-left text-gray-500">Name</th>
                            <th className="px-3 py-2 text-center text-gray-500">Raw</th>
                            <th className="px-3 py-2 text-center text-gray-500">Adj</th>
                            <th className="px-3 py-2 text-center text-gray-500">Score</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-200 bg-white">
                          {extractedData.map((row, idx) => (
                            <tr key={idx} className={row["Raw Count"] === 0 ? "opacity-50" : ""}>
                              <td className="px-3 py-2 whitespace-nowrap font-medium">{row['姓名']}</td>
                              <td className="px-3 py-2 text-center text-gray-400">{row['Raw Count']}</td>
                              <td className="px-3 py-2 text-center text-blue-600 font-medium group relative cursor-help">
                                {row['Adjusted Count']}
                                {row['Halved Subjects'] && (
                                  <div className="hidden group-hover:block absolute bottom-full left-1/2 -translate-x-1/2 mb-2 p-2 bg-gray-800 text-white text-xs rounded shadow-lg whitespace-normal min-w-[150px] z-10">
                                    Halved: {row['Halved Subjects']}
                                  </div>
                                )}
                              </td>
                              <td className={`px-3 py-2 text-center font-bold ${row['分数'] >= 5 ? 'text-green-600' : row['分数'] >= 3 ? 'text-blue-600' : 'text-gray-500'}`}>{row['分数']}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                    <button onClick={downloadExcel} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-6 rounded-lg shadow-md flex items-center justify-center gap-2">
                      <Download className="w-5 h-5" /> Download Excel
                    </button>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI } from "@google/genai";
import * as XLSX from 'https://esm.sh/xlsx';
import { Upload, FileSpreadsheet, Loader2, CheckCircle, AlertCircle, X, Download, Image as ImageIcon, Settings, Info, Users, HelpCircle, Eye, EyeOff, FileText, Trash2, Plus } from 'lucide-react';

// Interfaces for type safety
interface RawRow {
  teacher: string;
  code: string;
  count: number;
  matchedStandardName?: string | null;
  normalizedCode?: string;
  sourceFile?: string; // Track which file the data came from
}

interface ProcessedRow {
  "姓名": string;
  "Raw Count": number;
  "Adjusted Count": number;
  "分数": number;
  "Halved Subjects": string;
}

interface UploadedFile {
  id: string;
  file: File;
  previewUrl: string | null;
}

const App = () => {
  const [uploadedFiles, setUploadedFiles] = useState<UploadedFile[]>([]);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [extractedData, setExtractedData] = useState<ProcessedRow[] | null>(null);
  const [unmatchedRows, setUnmatchedRows] = useState<RawRow[]>([]);
  const [showUnmatched, setShowUnmatched] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [referenceNames, setReferenceNames] = useState<string>(`杨晶晶 Jenny
徐育梅 Catherine
储晓栋 Amy
孟雅 Alice
陈蓉 Lotus
谢淑平 Sherry
