                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                    <button onClick={downloadExcel} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-6 rounded-lg shadow-md flex items-center justify-center gap-2">
                      <Download className="w-5 h-5" /> Download Excel
