张金慧 Emily
冯灿Sunny Feng
李雪维 Nicole
张国靖 Alicia
秦笑Sophie
刘家玮Jane
施璎真Serena
丁佐伊Zoe
宋吉 Merissa
王楚怡phyllis
周筱妍Ollie
张颖 Yvonne
李苏粤Sibyl
许明月 Luna
季远兰 Mandy
吴飞Fiona（英语）
孙胜蓝 Sierra（英语）
汪苇 Winnie`;

const App = () => {
  const [uploadedFiles, setUploadedFiles] = useState<UploadedFile[]>([]);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [extractedData, setExtractedData] = useState<ProcessedRow[] | null>(null);
  const [unmatchedRows, setUnmatchedRows] = useState<RawRow[]>([]);
  const [showUnmatched, setShowUnmatched] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [referenceNames, setReferenceNames] = useState<string>(DEFAULT_REFERENCE_NAMES);
  const [coTeachingNames, setCoTeachingNames] = useState<string>(`李苏粤Sibyl, Noku
谢淑平 Sherry, 李臣亚 Linna
冯灿Sunny Feng,张金慧 Emily
秦笑Sophie, Superman
陈蓉 Lotus, Callum`);
  const [showSettings, setShowSettings] = useState(true);
  const [isDarkMode, setIsDarkMode] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Initialize Theme based on time
  useEffect(() => {
    const hour = new Date().getHours();
    // Night time: 6 PM (18) to 6 AM (6)
    const isNight = hour >= 18 || hour < 6;
    setIsDarkMode(isNight);
  }, []);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  const generateId = () => Math.random().toString(36).substr(2, 9);

  const restoreDefaultNames = () => {
    if (confirm('Are you sure you want to restore the default name list?')) {
      setReferenceNames(DEFAULT_REFERENCE_NAMES);
    }
  };

  const processFiles = useCallback((files: File[]) => {
    const newUploadedFiles: UploadedFile[] = [];
    const validTypes = ['image/png', 'image/jpeg', 'image/jpg', 'application/pdf', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', 'application/vnd.ms-excel'];

    files.forEach(file => {
      // Basic type check
      const isExcel = file.name.endsWith('.xlsx') || file.name.endsWith('.xls');
      const isValid = validTypes.some(t => file.type.includes(t)) || isExcel;

      if (isValid) {
        // Create preview immediately
        let previewUrl: string | null = null;
        if (file.type.startsWith('image/') || file.type === 'application/pdf') {
             const reader = new FileReader();
             reader.onload = (e) => {
                 setUploadedFiles(prev => prev.map(item => {
                     if (item.file === file) {
                         return { ...item, previewUrl: e.target?.result as string };
                     }
                     return item;
                 }));
             };
             reader.readAsDataURL(file);
        }

        newUploadedFiles.push({
            id: generateId(),
            file,
            previewUrl // Initially null, updated async for images/pdf
        });
      }
    });

    if (newUploadedFiles.length > 0) {
        setUploadedFiles(prev => [...prev, ...newUploadedFiles]);
        setError(null);
        setExtractedData(null); // Reset results on new upload
        setUnmatchedRows([]);
    } else if (files.length > 0) {
        setError('No valid files selected. Please use Images, PDF, or Excel.');
    }
  }, []);

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      processFiles(Array.from(e.target.files));
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      processFiles(Array.from(e.dataTransfer.files));
    }
  };

  // Add Paste Event Listener
  useEffect(() => {
    const handlePaste = (e: ClipboardEvent) => {
      if (e.clipboardData && e.clipboardData.items) {
        const files: File[] = [];
        for (let i = 0; i < e.clipboardData.items.length; i++) {
          const item = e.clipboardData.items[i];
          if (item.type.indexOf('image') !== -1) {
            const blob = item.getAsFile();
            if (blob) files.push(blob);
          }
        }
        if (files.length > 0) {
            processFiles(files);
            e.preventDefault();
        }
      }
    };

    document.addEventListener('paste', handlePaste);
    return () => {
      document.removeEventListener('paste', handlePaste);
    };
  }, [processFiles]);

  const removeFile = (id: string) => {
      setUploadedFiles(prev => prev.filter(f => f.id !== id));
      setExtractedData(null); 
      setUnmatchedRows([]);
  };

  const clearAllFiles = () => {
    setUploadedFiles([]);
    setExtractedData(null);
    setUnmatchedRows([]);
    setError(null);
  };

  const calculateScore = (count: number) => {
    if (count <= 10) return 0;
    if (count <= 20) return 1;
    if (count <= 35) return 3;
    return 5;
  };

  const normalizeCode = (code: string) => {
    if (!code) return "";
    return code.replace(/\s+/g, '').toUpperCase();
  };

  const getKeywords = (standardNameLine: string) => {
    const parts = standardNameLine.match(/[\u4e00-\u9fa5]+|[a-zA-Z]+/g);
    return parts ? parts.map(p => p.toLowerCase()) : [];
  };

  const calculateKeywordFrequency = (matchers: {fullName: string, keywords: string[]}[]) => {
      const freqMap = new Map<string, number>();
      matchers.forEach(m => {
          m.keywords.forEach(k => {
              freqMap.set(k, (freqMap.get(k) || 0) + 1);
          });
      });
      return freqMap;
  };

  const analyzeData = async () => {
    if (uploadedFiles.length === 0) return;

    setIsAnalyzing(true);
    setError(null);
    setUnmatchedRows([]);

    try {
      // Parallel Processing
      const allRawRowsResults = await Promise.all(uploadedFiles.map(async (uFile) => {
          const { file, previewUrl } = uFile;
          let fileRows: RawRow[] = [];

          try {
            // BRANCH 1: AI PROCESSING (IMAGE OR PDF)
            if ((file.type.startsWith('image/') || file.type === 'application/pdf') && previewUrl) {
                const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
                const base64Data = previewUrl.split(',')[1];

                let prompt = `
                Analyze this ${file.type === 'application/pdf' ? 'PDF document' : 'image'} containing a table.
                The document may contain multiple pages or long lists. You MUST extract data from ALL pages/sections.

                Columns usually are: "Teacher Name", "Subject Name", "Subject Code", "Number of Columns" (Count).

                Task:
                1. Extract EVERY SINGLE data row. Do NOT summarize. Do NOT truncate. 
                2. Exclude "Total" rows.
                3. Handle Merged Cells: If "Teacher Name" is empty/merged, assume it is the same as the row above it.

                Return a JSON array of objects:
                [
                    { "teacher": "Exact string from doc", "code": "Subject Code", "count": 123 },
                    ...
                ]

                Output valid JSON only. Ensure you output the COMPLETE list.
                `;

                const response = await ai.models.generateContent({
                model: 'gemini-2.5-flash',
                contents: {
                    parts: [
                    {
                        inlineData: {
                        mimeType: file.type,
                        data: base64Data
                        }
                    },
                    { text: prompt }
                    ]
                },
                config: {
                    responseMimeType: "application/json"
                }
                });

                const responseText = response.text;
                if (!responseText) throw new Error(`No data returned for ${file.name}`);

                try {
                const parsed = JSON.parse(responseText);
                let rows: any[] = [];
                if (Array.isArray(parsed)) {
                    rows = parsed;
                } else if (typeof parsed === 'object') {
                    const key = Object.keys(parsed).find(k => Array.isArray(parsed[k]));
                    if (key) rows = parsed[key];
                }

                // Robust mapping for AI output keys
                fileRows = rows.map((r: any) => {
                    // Try to find keys case-insensitively and with variations
                    const teacherKey = Object.keys(r).find(k => /teacher|name|姓名|instructor/i.test(k));
                    const countKey = Object.keys(r).find(k => /count|num|节数|quantity/i.test(k));
                    const codeKey = Object.keys(r).find(k => /code|subject|代码/i.test(k));

                    return {
                        teacher: teacherKey ? String(r[teacherKey]).trim() : "",
                        code: codeKey ? String(r[codeKey]).trim() : "",
                        count: countKey ? (Number(r[countKey]) || 0) : 0,
                        sourceFile: file.name
                    };
                }).filter(r => r.teacher && r.count > 0);

                } catch (e) {
                    console.warn(`Failed to parse AI response for ${file.name}`);
                }
            } 
            // BRANCH 2: EXCEL PROCESSING (LOCAL)
            else if (file.name.endsWith('.xlsx') || file.name.endsWith('.xls') || file.type.includes('spreadsheet') || file.type.includes('excel')) {
                const arrayBuffer = await file.arrayBuffer();
                const workbook = XLSX.read(arrayBuffer);
                const firstSheetName = workbook.SheetNames[0];
                const worksheet = workbook.Sheets[firstSheetName];

                const jsonData = XLSX.utils.sheet_to_json(worksheet, { defval: "" });

                let lastTeacher = "";

                fileRows = jsonData.map((row: any) => {
                    const teacherKey = Object.keys(row).find(k => /teacher|name|姓名|instructor/i.test(k));
                    const codeKey = Object.keys(row).find(k => /code|subject|代码/i.test(k));
                    const countKey = Object.keys(row).find(k => /column|count|节数|数量|num/i.test(k));

                    let teacher = teacherKey ? String(row[teacherKey]).trim() : "";
                    let code = codeKey ? String(row[codeKey]).trim() : "";
                    let countStr = countKey ? String(row[countKey]) : "0";
                    let count = parseFloat(countStr) || 0;

                    if (!teacher && lastTeacher) {
                        teacher = lastTeacher;
                    } else if (teacher) {
                        lastTeacher = teacher;
                    }

                    return {
                        teacher: teacher,
                        code: code,
                        count: count,
                        sourceFile: file.name
                    };
                }).filter(r => {
                    if (!r.teacher || r.teacher.toLowerCase().includes('total')) return false;
                    if (r.count <= 0) return false;
                    return true;
                });
            }
          } catch (err) {
              console.error(`Error processing file ${file.name}:`, err);
          }
          return fileRows;
      }));

      // Flatten all rows from all files
      const rawRows = allRawRowsResults.flat();

      if (rawRows.length === 0) {
          throw new Error("No valid data extracted. Please check if your file has columns like 'Teacher', 'Code', 'Count'.");
      }

      // --- Client-Side Matching Algorithm ---

      // 1. Prepare Standard Names
      const stdNamesList = referenceNames.split('\n').map(n => n.trim()).filter(n => n);
      const stdNameMatchers = stdNamesList.map(name => ({
          fullName: name,
          keywords: getKeywords(name)
      }));

      const keywordFreq = calculateKeywordFrequency(stdNameMatchers);

      // 2. Match Rows - Best Match Strategy with Uniqueness Weighting & Mismatch Penalty
      const matchedRows: RawRow[] = rawRows.map(row => {
          const rawTeacher = (row.teacher || "").toLowerCase();
          const rawKeywords = getKeywords(rawTeacher); // Extract keywords from the input row

          let bestMatch: { name: string, score: number } | null = null;

          stdNameMatchers.forEach(matcher => {
              let currentScore = 0;

              // A. Positive Matching
              matcher.keywords.forEach(keyword => {
                  if (keyword.length < 2) return; 

                  if (rawTeacher.includes(keyword)) {
                       // Rule 1: Chinese characters
                       if (/[\u4e00-\u9fa5]/.test(keyword)) {
                           currentScore += 50;
                       } 
                       // Rule 2: English keywords
                       else {
                           let score = keyword.length;
                           // Rule 3: Uniqueness Boost
                           if (keywordFreq.get(keyword) === 1) {
                               score += 20; 
                           }
                           currentScore += score;
                       }
                  }
              });

              // B. Mismatch Penalty
              // If the Raw Name contains a word that is NOT in the Standard Name, deduct points.
              // e.g. Raw: "Annabelle Yang", Std: "Sunny Yang". 
              // "Annabelle" is not in "Sunny Yang" -> Penalty.
              let mismatchPenalty = 0;
              if (currentScore > 0) { // Only check penalty if there is some match
                  rawKeywords.forEach(rawK => {
                      if (rawK.length < 2) return;
                      // Check if this raw keyword exists in the matcher's keywords
                      // We use a loose check (includes) to be safe
                      const isFound = matcher.keywords.some(mk => mk === rawK || mk.includes(rawK) || rawK.includes(mk));
                      if (!isFound) {
                          mismatchPenalty += 20; // Significant penalty for mismatched First or Last names
                      }
                  });
              }

              const finalScore = currentScore - mismatchPenalty;

              if (finalScore > 0) {
                  if (!bestMatch || finalScore > bestMatch.score) {
                      bestMatch = { name: matcher.fullName, score: finalScore };
                  }
              }
          });

          return {
              ...row,
              matchedStandardName: bestMatch ? bestMatch.name : null,
              normalizedCode: normalizeCode(row.code)
          };
      });

      setUnmatchedRows(matchedRows.filter(r => !r.matchedStandardName));

      // 3. Co-teaching Logic
      const rowsToHalve = new Set<RawRow>();
      const halvedCodesMap = new Map<string, Set<string>>();

      const coTeachingGroups = coTeachingNames
        .split('\n')
        .map(line => line.split(/,|，/).map(n => n.trim().toLowerCase()).filter(n => n))
        .filter(group => group.length > 0);

      coTeachingGroups.forEach(groupKeywords => {
         const groupRows = matchedRows.filter(row => {
             const standard = (row.matchedStandardName || "").toLowerCase();
             const raw = (row.teacher || "").toLowerCase();
             return groupKeywords.some(k => standard.includes(k) || raw.includes(k));
         });

         const codeMap = new Map<string, typeof matchedRows>();
         groupRows.forEach(row => {
             if (!row.normalizedCode) return;
             if (!codeMap.has(row.normalizedCode)) codeMap.set(row.normalizedCode, []);
             codeMap.get(row.normalizedCode)?.push(row);
         });

         codeMap.forEach((rowsInCode, code) => {
             const uniqueTeachers = new Set(rowsInCode.map(r => r.matchedStandardName || r.teacher));
             if (uniqueTeachers.size > 1) {
                 rowsInCode.forEach(r => {
                     rowsToHalve.add(r);
                     const ownerName = r.matchedStandardName;
                     if (ownerName) {
                         if (!halvedCodesMap.has(ownerName)) halvedCodesMap.set(ownerName, new Set());
                         halvedCodesMap.get(ownerName)?.add(code);
                     }
                 });
             }
         });
      });

      // 4. Aggregation
      const results: ProcessedRow[] = stdNamesList.map(stdName => {
          const teacherRows = matchedRows.filter(r => r.matchedStandardName === stdName);

          let rawTotal = 0;
          let adjustedTotal = 0;

          teacherRows.forEach(r => {
              const val = Number(r.count) || 0;
              rawTotal += val;

              if (rowsToHalve.has(r)) {
                  adjustedTotal += val / 2;
              } else {
                  adjustedTotal += val;
              }
          });

          const halvedSubjects = Array.from(halvedCodesMap.get(stdName) || []).join(', ');

          return {
              "姓名": stdName,
              "原始课时": rawTotal,
              "调整课时": adjustedTotal,
              "分数": calculateScore(adjustedTotal),
              "Halved Subjects": halvedSubjects
          };
      });

      setExtractedData(results);

    } catch (err) {
      console.error(err);
      setError("Failed to process. " + (err as Error).message);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const downloadExcel = () => {
    if (!extractedData || extractedData.length === 0) return;

    const ws = XLSX.utils.json_to_sheet(extractedData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Scores");

    ws['!cols'] = [
        { wch: 20 }, 
        { wch: 10 }, 
        { wch: 15 }, 
        { wch: 10 }, 
        { wch: 30 }
    ];
    XLSX.writeFile(wb, "class_scores.xlsx");
  };

  const renderPreview = (uFile: UploadedFile) => {
    const { file, previewUrl } = uFile;

    if (file.type.startsWith('image/') && previewUrl) {
        return <img src={previewUrl} alt="Preview" className="h-20 w-20 object-cover rounded-md border dark:border-gray-600" />;
    }

    return (
       <div className="h-20 w-20 bg-gray-100 dark:bg-gray-700 rounded-md border dark:border-gray-600 flex flex-col items-center justify-center">
          {file.type.includes('pdf') ? (
              <FileText className="w-8 h-8 text-red-600 dark:text-red-400" />
          ) : (
              <FileSpreadsheet className="w-8 h-8 text-green-600 dark:text-green-400" />
          )}
          <span className="text-[10px] text-gray-500 dark:text-gray-300 mt-1 uppercase font-bold px-1 truncate w-full text-center">
              {file.name.split('.').pop()}
          </span>
       </div>
    );
  };

  return (
    <div className={isDarkMode ? 'dark' : ''}>
      <div className="min-h-screen bg-gray-50 dark:bg-gray-900 flex flex-col items-center py-12 px-4 sm:px-6 lg:px-8 text-gray-800 dark:text-gray-100 transition-colors duration-200">
        <div className="max-w-4xl w-full space-y-6">

          {/* Header */}
          <div className="flex flex-col items-center text-center relative">
            {/* Theme Toggle Button */}
            <button 
              onClick={toggleTheme} 
              className="absolute right-0 top-0 p-2 rounded-full bg-white dark:bg-gray-800 shadow-sm border border-gray-200 dark:border-gray-700 text-gray-500 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors"
              title={isDarkMode ? "Switch to Light Mode" : "Switch to Dark Mode"}
            >
              {isDarkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
            </button>

            <div className="mx-auto h-16 w-16 bg-blue-100 dark:bg-blue-900/40 rounded-full flex items-center justify-center mb-4">
              <FileSpreadsheet className="h-8 w-8 text-blue-600 dark:text-blue-400" />
            </div>
            <h1 className="text-3xl font-bold text-gray-900 dark:text-white tracking-tight">Score Calculator</h1>
            <p className="mt-2 text-lg text-gray-600 dark:text-gray-400">
              Upload images, PDFs, or Excel files. Multi-file upload supported.
            </p>
          </div>

          {/* Settings */}
          <div className="bg-white dark:bg-gray-800 shadow-md rounded-xl overflow-hidden border border-gray-100 dark:border-gray-700">
            <div 
              className="px-6 py-4 bg-gray-50 dark:bg-gray-850 border-b border-gray-200 dark:border-gray-700 flex items-center justify-between cursor-pointer"
              onClick={() => setShowSettings(!showSettings)}
            >
              <div className="flex items-center gap-2 font-medium text-gray-700 dark:text-gray-200">
                <Settings className="w-5 h-5" />
                <span>Settings</span>
              </div>
              <span className="text-sm text-blue-600 dark:text-blue-400 hover:text-blue-800 dark:hover:text-blue-300">
                {showSettings ? 'Hide' : 'Show'}
              </span>
            </div>

            {showSettings && (
              <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
                 {/* Standard Names */}
                 <div>
                     <div className="mb-2 text-sm text-gray-700 dark:text-gray-300 font-semibold flex items-center justify-between">
                       <div className="flex items-center gap-2">
                          <Users className="w-4 h-4" />
                          Standard Name List (Required)
                       </div>
                       <button 
                         onClick={restoreDefaultNames} 
                         className="flex items-center gap-1 text-xs text-blue-600 dark:text-blue-400 hover:underline"
                         title="Restore default list"
                       >
                          <RotateCcw className="w-3 h-3" /> Default
                       </button>
                     </div>
                     <textarea
                       value={referenceNames}
                       onChange={(e) => setReferenceNames(e.target.value)}
                       className="w-full h-48 p-3 border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm font-mono text-gray-900 dark:text-gray-100"
                     />
                 </div>

                 {/* Co-teaching Groups */}
                 <div>
                     <div className="mb-2 text-sm text-gray-700 dark:text-gray-300 font-semibold flex items-center gap-2">
                       <Info className="w-4 h-4" />
                       Co-teaching Groups
                     </div>
                     <div className="mb-2 text-xs text-gray-500 dark:text-gray-400">
                       One group per line, comma separated.<br/>
                       Example: <code>Sherry, Linna</code>
                     </div>
                     <textarea
                       value={coTeachingNames}
                       onChange={(e) => setCoTeachingNames(e.target.value)}
                       className="w-full h-48 p-3 border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm font-mono text-gray-900 dark:text-gray-100"
                     />
                 </div>
              </div>
            )}
          </div>

          {/* Scoring Legend */}
          <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-xl p-4 flex items-start gap-3">
              <HelpCircle className="w-5 h-5 text-blue-600 dark:text-blue-400 shrink-0 mt-0.5" />
              <div>
                  <h3 className="text-sm font-semibold text-blue-900 dark:text-blue-200">Scoring Rules</h3>
                  <div className="mt-1 flex flex-wrap gap-4 text-sm text-blue-800 dark:text-blue-300">
                      <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-gray-400 dark:bg-gray-500"></span> Count ≤ 10: <b>0 pts</b></span>
                      <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-blue-400"></span> 11-20: <b>1 pt</b></span>
                      <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-blue-600"></span> 21-35: <b>3 pts</b></span>
                      <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-green-500"></span> > 35: <b>5 pts</b></span>
                  </div>
              </div>
          </div>

          {/* Main Area */}
          <div className="bg-white dark:bg-gray-800 shadow-xl rounded-2xl overflow-hidden border border-gray-100 dark:border-gray-700 flex flex-col md:flex-row min-h-[500px]">

            {/* Left Panel: Upload & Preview */}
            <div className="w-full md:w-5/12 bg-gray-50 dark:bg-gray-850 border-r border-gray-200 dark:border-gray-700 p-4 flex flex-col">

                {/* Drop Zone */}
                <div 
                  className="border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-xl p-6 flex flex-col items-center justify-center hover:border-blue-500 hover:bg-blue-50 dark:hover:bg-gray-700/50 cursor-pointer transition-colors bg-white dark:bg-gray-800 mb-4"
                  onDragOver={handleDragOver}
                  onDrop={handleDrop}
                  onClick={() => fileInputRef.current?.click()}
                >
                  <Upload className="h-8 w-8 text-gray-400 dark:text-gray-500 mb-2" />
                  <p className="text-sm font-medium text-gray-700 dark:text-gray-300 text-center">
                     Click to Upload or Drag & Drop<br/>
                     <span className="text-xs text-gray-500 dark:text-gray-400 font-normal">Images, PDFs, Excel (Multiple allowed)</span>
                  </p>
                  <input 
                    type="file" 
                    multiple 
                    ref={fileInputRef} 
                    className="hidden" 
                    accept="image/*,.pdf,.xlsx,.xls,application/pdf,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel" 
                    onChange={handleFileSelect} 
                  />
                </div>

                {/* File List Gallery */}
                {uploadedFiles.length > 0 && (
                  <div className="flex-1 overflow-y-auto">
                     <div className="flex items-center justify-between mb-2 px-1">
                        <span className="text-xs font-semibold text-gray-500 dark:text-gray-400">{uploadedFiles.length} FILES</span>
                        <button onClick={clearAllFiles} className="text-xs text-red-500 hover:text-red-700 hover:underline">Clear All</button>
                     </div>
                     <div className="grid grid-cols-3 gap-2">
                        {uploadedFiles.map((uFile) => (
                            <div key={uFile.id} className="relative group">
                                {renderPreview(uFile)}
                                <button 
                                  onClick={(e) => { e.stopPropagation(); removeFile(uFile.id); }}
                                  className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full p-0.5 shadow-md opacity-0 group-hover:opacity-100 transition-opacity"
                                >
                                  <X className="w-3 h-3" />
                                </button>
                            </div>
                        ))}
                        <div 
                          onClick={() => fileInputRef.current?.click()}
                          className="h-20 w-20 border-2 border-dashed border-gray-200 dark:border-gray-600 rounded-md flex items-center justify-center text-gray-400 hover:text-blue-500 hover:border-blue-300 cursor-pointer bg-white dark:bg-gray-800"
                        >
                            <Plus className="w-6 h-6" />
                        </div>
                     </div>
                  </div>
                )}

                {uploadedFiles.length === 0 && (
                   <div className="flex-1 flex items-center justify-center text-gray-400 dark:text-gray-500 text-sm italic">
                      Files will appear here
                   </div>
                )}
            </div>

            {/* Right Panel: Actions & Results */}
            <div className="w-full md:w-7/12 p-6 flex flex-col relative bg-white dark:bg-gray-800">

                {/* Action Button Area */}
                {uploadedFiles.length > 0 && !extractedData && !isAnalyzing && (
                  <div className="absolute inset-0 flex items-center justify-center z-10 bg-white/80 dark:bg-gray-800/80 backdrop-blur-sm rounded-r-xl">
                     <button onClick={analyzeData} className="transform hover:scale-105 transition-transform bg-blue-600 hover:bg-blue-700 dark:bg-blue-600 dark:hover:bg-blue-500 text-white font-bold py-4 px-8 rounded-full shadow-lg flex items-center gap-3 text-lg">
                        <FileSpreadsheet className="w-6 h-6" />
                        Calculate Scores for {uploadedFiles.length} File{uploadedFiles.length > 1 ? 's' : ''}
                     </button>
                  </div>
                )}

                {isAnalyzing && (
                   <div className="absolute inset-0 flex flex-col items-center justify-center z-10 bg-white/90 dark:bg-gray-800/95 rounded-r-xl">
                      <Loader2 className="h-12 w-12 text-blue-600 dark:text-blue-400 animate-spin mb-4" />
                      <p className="text-lg font-medium text-gray-700 dark:text-gray-200">Analyzing {uploadedFiles.length} file(s)...</p>
                      <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">Merging data and calculating scores</p>
                   </div>
                )}

                {error && (
                  <div className="mb-6 p-4 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg text-red-700 dark:text-red-300 flex items-center gap-3">
                     <AlertCircle className="w-5 h-5 shrink-0" />
                     <div>
                       <p className="font-medium">Analysis Failed</p>
                       <p className="text-sm">{error}</p>
                     </div>
                     <button onClick={analyzeData} className="ml-auto text-sm underline hover:text-red-900 dark:hover:text-red-100">Retry</button>
                  </div>
                )}

                {/* Results Table */}
                {extractedData && (
                    <div className="flex flex-col h-full w-full">
                      <div className="flex justify-between items-center mb-4">
                          <span className="text-green-700 dark:text-green-400 font-medium flex items-center gap-2"><CheckCircle className="w-5 h-5"/> Analysis Complete</span>
                          <div className="flex gap-2">
                               {unmatchedRows.length > 0 && (
                                  <button 
                                      onClick={() => setShowUnmatched(!showUnmatched)}
                                      className={`text-xs px-2 py-1 rounded flex items-center gap-1 ${showUnmatched ? 'bg-orange-100 text-orange-700 dark:bg-orange-900/50 dark:text-orange-300' : 'bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600'}`}
                                  >
                                      {showUnmatched ? <EyeOff className="w-3 h-3"/> : <Eye className="w-3 h-3"/>}
                                      {unmatchedRows.length} Unmatched
                                  </button>
                               )}
                              <span className="text-xs bg-gray-100 dark:bg-gray-700 dark:text-gray-300 px-2 py-1 rounded">{extractedData.filter(r => r["原始课时"] > 0).length} names found</span>
                          </div>
                      </div>

                      {/* Unmatched Rows Warning */}
                      {showUnmatched && unmatchedRows.length > 0 && (
                          <div className="mb-4 bg-orange-50 dark:bg-orange-900/20 border border-orange-200 dark:border-orange-800 rounded-lg p-3 text-xs overflow-auto max-h-[150px]">
                              <h4 className="font-semibold text-orange-800 dark:text-orange-300 mb-2">Data found but not in Standard List:</h4>
                              <table className="w-full text-left text-orange-900 dark:text-orange-200">
                                  <thead>
                                      <tr>
                                          <th className="pb-1">Teacher Found</th>
                                          <th className="pb-1">Count</th>
                                          <th className="pb-1">Source</th>
                                      </tr>
                                  </thead>
                                  <tbody>
                                      {unmatchedRows.map((r, i) => (
                                          <tr key={i} className="border-t border-orange-100 dark:border-orange-800/50">
                                              <td className="py-1 pr-2">{r.teacher}</td>
                                              <td className="py-1">{r.count}</td>
                                              <td className="py-1 text-orange-400 dark:text-orange-400/70 italic text-[10px]">{r.sourceFile}</td>
                                          </tr>
                                      ))}
                                  </tbody>
                              </table>
                              <p className="mt-2 text-orange-600 dark:text-orange-400 italic">Check if names in "Settings" match these exact spellings.</p>
                          </div>
                      )}

                      <div className="flex-1 overflow-auto border dark:border-gray-700 rounded-lg mb-4 bg-gray-50 dark:bg-gray-850 scrollbar-hide">
                        <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700 text-sm">
                          <thead className="bg-gray-100 dark:bg-gray-700 sticky top-0 z-10">
                            <tr>
                              <th className="px-3 py-2 text-left text-gray-500 dark:text-gray-300">姓名</th>
                              <th className="px-3 py-2 text-center text-gray-500 dark:text-gray-300">原始课时</th>
                              <th className="px-3 py-2 text-center text-gray-500 dark:text-gray-300">调整课时</th>
                              <th className="px-3 py-2 text-center text-gray-500 dark:text-gray-300">分数</th>
                            </tr>
                          </thead>
                          <tbody className="divide-y divide-gray-200 dark:divide-gray-700 bg-white dark:bg-gray-800">
                            {extractedData.map((row, idx) => (
                              <tr key={idx} className={`${row["原始课时"] === 0 ? "opacity-50" : ""} hover:bg-gray-50 dark:hover:bg-gray-700/50`}>
                                <td className="px-3 py-2 whitespace-nowrap font-medium text-gray-900 dark:text-gray-100">{row['姓名']}</td>
                                <td className="px-3 py-2 text-center text-gray-400 dark:text-gray-500">{row['原始课时']}</td>
                                <td className="px-3 py-2 text-center text-blue-600 dark:text-blue-400 font-medium group relative cursor-help">
                                  {row['调整课时']}
                                  {row['Halved Subjects'] && (
                                    <div className="hidden group-hover:block absolute bottom-full left-1/2 -translate-x-1/2 mb-2 p-2 bg-gray-800 dark:bg-gray-900 text-white text-xs rounded shadow-lg whitespace-normal min-w-[150px] z-20">
                                      Halved: {row['Halved Subjects']}
                                    </div>
                                  )}
                                </td>
                                <td className={`px-3 py-2 text-center font-bold ${row['分数'] >= 5 ? 'text-green-600 dark:text-green-400' : row['分数'] >= 3 ? 'text-blue-600 dark:text-blue-400' : 'text-gray-500 dark:text-gray-500'}`}>{row['分数']}</td>
                              </tr>
                            ))}
                          </tbody>
                        </table>
                      </div>
                      <button onClick={downloadExcel} className="w-full bg-blue-600 hover:bg-blue-700 dark:bg-blue-600 dark:hover:bg-blue-500 text-white font-semibold py-3 px-6 rounded-lg shadow-md flex items-center justify-center gap-2">
                        <Download className="w-5 h-5" /> Download Excel
                      </button>
                    </div>
                )}

                {uploadedFiles.length === 0 && (
                    <div className="flex-1 flex flex-col items-center justify-center text-gray-300 dark:text-gray-600">
                        <div className="w-16 h-16 rounded-full bg-gray-100 dark:bg-gray-700 mb-4"></div>
                        <div className="h-4 w-32 bg-gray-100 dark:bg-gray-700 rounded mb-2"></div>
                        <div className="h-4 w-24 bg-gray-100 dark:bg-gray-700 rounded"></div>
                    </div>
                )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

