import React, { useState, useRef, useEffect, useCallback } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI } from "@google/genai";
import * as XLSX from 'https://esm.sh/xlsx';
import { Upload, FileSpreadsheet, Loader2, CheckCircle, AlertCircle, X, Download, Image as ImageIcon, Settings, Info, Users, HelpCircle, Eye, EyeOff, FileText, Trash2, Plus, Moon, Sun, RotateCcw } from 'lucide-react';

// Interfaces for type safety
interface RawRow {
  teacher: string;
  code: string;
  count: number;
  matchedStandardName?: string | null;
  normalizedCode?: string;
  sourceFile?: string; // Track which file the data came from
}

interface ProcessedRow {
  "姓名": string;
  "原始课时": number;
  "调整课时": number;
  "分数": number;
  "Halved Subjects": string;
}

interface UploadedFile {
  id: string;
  file: File;
  previewUrl: string | null;
}

const DEFAULT_REFERENCE_NAMES = `杨晶晶 Jenny
